css:
/* =========================================================
   LIFE CLINICS — OPERATIONS & SERVICE MODULE
   Complete Custom HTML Block CSS
   ========================================================= */

.life-ops-dashboard {

  position: relative;
  width: 100%;
  min-height: 720px;
  box-sizing: border-box;
  overflow: hidden;
  border: 1px solid #e8edf3;
  border-radius: 16px;
  background:
    linear-gradient(
      180deg,
      #f7faff 0%,
      #f1f5f9 100%
    );
  color: #172033;
  font-family:
    Inter,
    -apple-system,
    BlinkMacSystemFont,
    "Segoe UI",
    Roboto,
    Helvetica,
    Arial,
    sans-serif;
}

.navbar { display: none; }
.web-footer { display: none; }

.life-ops-dashboard *,
.life-ops-dashboard *::before,
.life-ops-dashboard *::after {
  box-sizing: border-box;
}

.life-ops-dashboard button,
.life-ops-dashboard input,
.life-ops-dashboard select,
.life-ops-dashboard textarea {
  font: inherit;
}

/* =========================================================
   HEADER — LIGHT GREEN VERSION
   ========================================================= */

.life-ops-dashboard .lo-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 18px;
  min-height: 92px;
  padding: 18px 22px;
  border-bottom: 4px solid #059669; /* darker green border */
  background: linear-gradient(135deg, #d1fae5 0%, #a7f3d0 100%);
  color: #064e3b;
}

.life-ops-dashboard .lo-brand {
  display: flex;
  align-items: center;
  gap: 13px;
  min-width: 300px;
}

.life-ops-dashboard .lo-logo {
  display: flex;
  flex: 0 0 52px;
  align-items: center;
  justify-content: center;
  width: 52px;
  height: 52px;
  border: 1px solid rgba(6, 78, 59, 0.22);
  border-radius: 14px;
  background: rgba(255, 255, 255, 0.45);
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.5);
  font-size: 25px;
  color: #064e3b;
}

.life-ops-dashboard .lo-title {
  margin: 0;
  color: #064e3b;
  font-size: 20px;
  font-weight: 800;
  line-height: 1.25;
  letter-spacing: -0.2px;
}

.life-ops-dashboard .lo-subtitle {
  margin-top: 5px;
  color: #065f46;
  font-size: 11px;
  font-weight: 600;
  line-height: 1.45;
  letter-spacing: 0.25px;
}

.life-ops-dashboard .lo-header-actions {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: flex-end;
  gap: 9px;
}

/* "LIVE" badge — solid dark green */
.life-ops-dashboard .lo-live-badge {
  display: inline-flex;
  align-items: center;
  min-height: 34px;
  padding: 7px 11px;
  border: 1px solid #059669;
  border-radius: 999px;
  background: #059669;
  color: #ffffff;
  font-size: 11px;
  font-weight: 800;
  white-space: nowrap;
}

/* Branch dropdown — white background, green border */
.life-ops-dashboard .lo-head-branch {
  width: 180px;
  min-width: 160px;
  border-color: #059669;
  background-color: #ffffff;
  color: #064e3b;
}

.life-ops-dashboard .lo-clock-box {
  display: flex;
  min-width: 105px;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: 6px 10px;
  border: 1px solid rgba(6, 78, 59, 0.2);
  border-radius: 9px;
  background: rgba(255, 255, 255, 0.3);
  text-align: center;
}

.life-ops-dashboard .lo-clock-box strong {
  color: #064e3b;
  font-size: 12px;
  font-weight: 800;
  line-height: 1.2;
}

.life-ops-dashboard .lo-clock-box span {
  margin-top: 2px;
  color: #065f46;
  font-size: 10px;
}

/* =========================================================
   BUTTONS AND INPUTS
   ========================================================= */

.life-ops-dashboard .lo-btn {
  display: inline-flex;
  min-height: 36px;
  align-items: center;
  justify-content: center;
  gap: 6px;
  padding: 8px 13px;
  border: 1px solid transparent;
  border-radius: 8px;
  outline: none;
  cursor: pointer;
  font-size: 12px;
  font-weight: 750;
  line-height: 1.2;
  text-decoration: none;
  white-space: nowrap;
  transition:
    transform 0.15s ease,
    background-color 0.15s ease,
    border-color 0.15s ease,
    box-shadow 0.15s ease,
    opacity 0.15s ease;
}

.life-ops-dashboard .lo-btn:hover:not(:disabled) {
  transform: translateY(-1px);
}

.life-ops-dashboard .lo-btn:active:not(:disabled) {
  transform: translateY(0);
}

.life-ops-dashboard .lo-btn:focus-visible {
  box-shadow:
    0 0 0 3px rgba(37, 99, 235, 0.22);
}

.life-ops-dashboard .lo-btn:disabled {
  cursor: not-allowed;
  opacity: 0.48;
  transform: none;
}

.life-ops-dashboard .lo-btn.lo-primary {
  border-color: #0A9B7A;
  background: #0A9B7A;
  color: #ffffff;
  box-shadow:
    0 5px 14px rgba(10, 155, 122, 0.22);
}

.life-ops-dashboard .lo-btn.lo-primary:hover:not(:disabled) {
  border-color: #088a6c;
  background: #088a6c;
}

.life-ops-dashboard .lo-header .lo-btn.lo-primary {
  border-color: #d5a325;
  background: #d5a325;
  color: #1d2533;
  box-shadow:
    0 6px 16px rgba(213, 163, 37, 0.25);
}

.life-ops-dashboard .lo-header .lo-btn.lo-primary:hover:not(:disabled) {
  border-color: #e7ba45;
  background: #e7ba45;
}

.life-ops-dashboard .lo-btn.lo-light {
  border-color: #d7dee8;
  background: #ffffff;
  color: #29364d;
}

.life-ops-dashboard .lo-btn.lo-light:hover:not(:disabled) {
  border-color: #aeb9c8;
  background: #f9fbfd;
}

/* Header "Manage Rooms" – white with green border */
.life-ops-dashboard .lo-header .lo-btn.lo-light {
  border-color: #059669;
  background: #ffffff;
  color: #064e3b;
}

.life-ops-dashboard .lo-header .lo-btn.lo-light:hover:not(:disabled) {
  border-color: #047857;
  background: #ecfdf5;
}

.life-ops-dashboard .lo-input {
  width: 100%;
  min-height: 36px;
  padding: 8px 10px;
  border: 1px solid #d7dee8;
  border-radius: 8px;
  outline: none;
  background: #ffffff;
  color: #172033;
  font-size: 12px;
  line-height: 1.25;
  transition:
    border-color 0.15s ease,
    box-shadow 0.15s ease,
    background-color 0.15s ease;
}

.life-ops-dashboard .lo-input:hover:not(:disabled) {
  border-color: #b6c0cf;
}

.life-ops-dashboard .lo-input:focus {
  border-color: #0A9B7A;
  box-shadow:
    0 0 0 3px rgba(10, 155, 122, 0.12);
}

.life-ops-dashboard .lo-input::placeholder {
  color: #8793a6;
}

.life-ops-dashboard .lo-input:disabled,
.life-ops-dashboard .lo-input[readonly] {
  cursor: not-allowed;
  background: #f1f4f8;
  color: #64748b;
}

.life-ops-dashboard .lo-input.is-invalid {
  border-color: #dc3545;
  background: #fff0f1;
  box-shadow:
    0 0 0 3px rgba(220, 53, 69, 0.1);
}

.life-ops-dashboard textarea.lo-input {
  resize: vertical;
}

.life-ops-dashboard .lo-search {
  min-width: 230px;
}

/* =========================================================
   KPI CARDS
   ========================================================= */

.life-ops-dashboard .lo-kpi-grid {
  display: grid;
  grid-template-columns:
    repeat(4, minmax(0, 1fr));
  gap: 14px;
  padding: 17px 20px;
}

.life-ops-dashboard .lo-kpi-card {
  position: relative;
  min-height: 112px;
  overflow: hidden;
  padding: 17px 18px;
  border: 1px solid #e8edf3;
  border-radius: 12px;
  background: #ffffff;
  box-shadow: 0 10px 28px rgba(19, 48, 91, 0.08);
}

.life-ops-dashboard .lo-kpi-card::before {
  position: absolute;
  top: 0;
  left: 0;
  width: 5px;
  height: 100%;
  background: #0A9B7A;
  content: "";
}

.life-ops-dashboard .lo-kpi-card:nth-child(2)::before {
  background: #198754;
}

.life-ops-dashboard .lo-kpi-card:nth-child(3)::before {
  background: #e67e22;
}

.life-ops-dashboard .lo-kpi-card:nth-child(4)::before {
  background: #7c3aed;
}

.life-ops-dashboard .lo-kpi-card > span {
  display: block;
  color: #64748b;
  font-size: 12px;
  font-weight: 750;
}

.life-ops-dashboard .lo-kpi-card > strong {
  display: block;
  margin-top: 7px;
  color: #12305b;
  font-size: 30px;
  font-weight: 850;
  line-height: 1;
}

.life-ops-dashboard .lo-kpi-card > small {
  display: block;
  margin-top: 8px;
  color: #8793a6;
  font-size: 10px;
  font-weight: 600;
}

/* =========================================================
   TABS AND PAGES
   ========================================================= */

.life-ops-dashboard .lo-tabs {
  display: flex;
  gap: 5px;
  padding: 0 20px;
  border-bottom: 1px solid #d7dee8;
  background: transparent;
}

.life-ops-dashboard .lo-tab {
  position: relative;
  min-height: 44px;
  padding: 10px 15px;
  border: 0;
  border-radius: 8px 8px 0 0;
  outline: none;
  background: transparent;
  color: #64748b;
  cursor: pointer;
  font-size: 12px;
  font-weight: 750;
  white-space: nowrap;
  transition:
    color 0.15s ease,
    background-color 0.15s ease;
}

.life-ops-dashboard .lo-tab:hover {
  background: rgba(255, 255, 255, 0.65);
  color: #12305b;
}

.life-ops-dashboard .lo-tab.active {
  background: #ffffff;
  color: #0A9B7A;
}

.life-ops-dashboard .lo-tab.active::after {
  position: absolute;
  right: 10px;
  bottom: -1px;
  left: 10px;
  height: 3px;
  border-radius: 2px 2px 0 0;
  background: #0A9B7A;
  content: "";
}

.life-ops-dashboard .lo-page {
  display: none;
  padding: 18px 20px 24px;
}

.life-ops-dashboard .lo-page.active {
  display: block;
  animation:
    loFadeIn 0.2s ease;
}

@keyframes loFadeIn {
  from {
    opacity: 0;
    transform: translateY(3px);
  }

  to {
    opacity: 1;
    transform: translateY(0);
  }
}

/* =========================================================
   CARDS AND TOOLBARS
   ========================================================= */

.life-ops-dashboard .lo-card {
  overflow: hidden;
  border: 1px solid #e8edf3;
  border-radius: 12px;
  background: #ffffff;
  box-shadow: 0 10px 28px rgba(19, 48, 91, 0.08);
}

.life-ops-dashboard .lo-card-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 15px;
  min-height: 70px;
  padding: 15px 17px;
  border-bottom: 1px solid #e8edf3;
  background:
    linear-gradient(
      180deg,
      #ffffff 0%,
      #f9fbfd 100%
    );
}

.life-ops-dashboard .lo-card-head h3 {
  margin: 0;
  color: #12305b;
  font-size: 16px;
  font-weight: 820;
  line-height: 1.3;
}

.life-ops-dashboard .lo-card-subtitle {
  margin: 4px 0 0;
  color: #64748b;
  font-size: 11px;
  line-height: 1.45;
}

.life-ops-dashboard .lo-count {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 7px 10px;
  border: 1px solid #e8edf3;
  border-radius: 999px;
  background: #ffffff;
  color: #64748b;
  font-size: 10px;
  font-weight: 700;
  white-space: nowrap;
}

.life-ops-dashboard .lo-count span {
  color: #12305b;
  font-size: 12px;
  font-weight: 850;
}

.life-ops-dashboard .lo-toolbar {
  display: flex;
  flex-wrap: wrap;
  align-items: flex-end;
  gap: 10px;
  padding: 13px 15px;
  border-bottom: 1px solid #e8edf3;
  background: #f9fbfd;
}

.life-ops-dashboard section.lo-page > .lo-toolbar {
  margin-bottom: 13px;
  border: 1px solid #e8edf3;
  border-radius: 8px;
  background: #ffffff;
  box-shadow: 0 10px 28px rgba(19, 48, 91, 0.08);
}

.life-ops-dashboard .lo-field-inline {
  display: flex;
  min-width: 135px;
  flex-direction: column;
  gap: 5px;
}

.life-ops-dashboard .lo-label {
  color: #45536b;
  font-size: 10px;
  font-weight: 800;
  line-height: 1;
}

.life-ops-dashboard .lo-report-toolbar {
  align-items: flex-end;
}

.life-ops-dashboard .lo-date-error {
  min-height: 0;
  padding: 0 15px;
  color: #dc3545;
  font-size: 11px;
  font-weight: 700;
}

.life-ops-dashboard .lo-date-error:not(:empty) {
  padding-top: 8px;
  padding-bottom: 8px;
  border-bottom: 1px solid #fff0f1;
  background: #fff0f1;
}

/* =========================================================
   QUICK FILTERS
   ========================================================= */

.life-ops-dashboard .lo-quick-row {
  display: flex;
  overflow-x: auto;
  gap: 7px;
  padding: 12px 15px;
  border-bottom: 1px solid #e8edf3;
  scrollbar-width: thin;
}

.life-ops-dashboard .lo-quick {
  min-height: 32px;
  padding: 6px 11px;
  border: 1px solid #d7dee8;
  border-radius: 999px;
  outline: none;
  background: #ffffff;
  color: #45536b;
  cursor: pointer;
  font-size: 10px;
  font-weight: 750;
  white-space: nowrap;
  transition:
    background-color 0.15s ease,
    color 0.15s ease,
    border-color 0.15s ease;
}

.life-ops-dashboard .lo-quick:hover {
  border-color: #aeb8c6;
  background: #f4f7fa;
}

.life-ops-dashboard .lo-quick.active {
  border-color: #0A9B7A;
  background: #0A9B7A;
  color: #ffffff;
}

/* =========================================================
   TABLES
   ========================================================= */

.life-ops-dashboard .lo-table-wrap {
  width: 100%;
  overflow: auto;
  scrollbar-width: thin;
  scrollbar-color:
    #b9c3d0
    #eef2f6;
}

.life-ops-dashboard .lo-table-wrap::-webkit-scrollbar {
  width: 9px;
  height: 9px;
}

.life-ops-dashboard .lo-table-wrap::-webkit-scrollbar-track {
  background: #eef2f6;
}

.life-ops-dashboard .lo-table-wrap::-webkit-scrollbar-thumb {
  border: 2px solid #eef2f6;
  border-radius: 999px;
  background: #b9c3d0;
}

.life-ops-dashboard .lo-table {
  width: 100%;
  min-width: 1080px;
  border-collapse: separate;
  border-spacing: 0;
  background: #ffffff;
  color: #29364d;
  font-size: 11px;
}

.life-ops-dashboard .lo-table th,
.life-ops-dashboard .lo-table td {
  padding: 10px 11px;
  border-right: 1px solid #edf1f5;
  border-bottom: 1px solid #e6ebf1;
  vertical-align: middle;
  text-align: left;
}

.life-ops-dashboard .lo-table th:last-child,
.life-ops-dashboard .lo-table td:last-child {
  border-right: 0;
}

.life-ops-dashboard .lo-table thead th {
  position: sticky;
  top: 0;
  z-index: 5;
  background:
    linear-gradient(
      180deg,
      #eff4fa 0%,
      #e9eff6 100%
    );
  color: #12305b;
  font-size: 10px;
  font-weight: 850;
  letter-spacing: 0.15px;
  white-space: nowrap;
}

.life-ops-dashboard .lo-table tbody tr:nth-child(even) td,
.life-ops-dashboard .lo-table tbody tr:nth-child(even) th {
  background: #f8fafc;
}

.life-ops-dashboard .lo-table tbody tr:hover td,
.life-ops-dashboard .lo-table tbody tr:hover th {
  background: #edf5ff;
}

.life-ops-dashboard .lo-table td strong {
  display: block;
  color: #172033;
  font-weight: 750;
  line-height: 1.35;
}

.life-ops-dashboard .lo-table td small {
  display: block;
  margin-top: 3px;
  color: #8793a6;
  font-size: 9px;
  line-height: 1.35;
}

.life-ops-dashboard .lo-id {
  max-width: 150px;
  color: #0A9B7A;
  font-family:
    ui-monospace,
    SFMono-Regular,
    Menlo,
    Monaco,
    Consolas,
    monospace;
  font-size: 10px;
  font-weight: 700;
  overflow-wrap: anywhere;
}

.life-ops-dashboard .lo-empty {
  height: 110px;
  color: #8793a6;
  font-size: 12px;
  font-weight: 650;
  text-align: center !important;
}

.life-ops-dashboard .lo-link-btn {
  display: inline-flex;
  min-height: 29px;
  align-items: center;
  justify-content: center;
  padding: 5px 9px;
  border: 1px solid #b9cdf5;
  border-radius: 7px;
  outline: none;
  background: #eaf8f0;
  color: #0A9B7A;
  cursor: pointer;
  font-size: 10px;
  font-weight: 800;
  transition:
    background-color 0.15s ease,
    border-color 0.15s ease;
}

.life-ops-dashboard .lo-link-btn:hover {
  border-color: #0A9B7A;
  background: #dfeeff;
}

.life-ops-dashboard .lo-status {
  display: inline-flex;
  min-height: 25px;
  align-items: center;
  justify-content: center;
  padding: 4px 8px;
  border: 1px solid #d7dee8;
  border-radius: 999px;
  background: #f4f7fa;
  color: #45536b;
  font-size: 9px;
  font-weight: 800;
  line-height: 1.1;
  white-space: nowrap;
}

.life-ops-dashboard .lo-status.success {
  border-color: #a9e2c1;
  background: #eaf8f0;
  color: #126c43;
}

.life-ops-dashboard .lo-status.warning {
  border-color: #f4cf9f;
  background: #fff4e8;
  color: #a45715;
}

.life-ops-dashboard .lo-status.danger {
  border-color: #f2b5bb;
  background: #fff0f1;
  color: #b82635;
}

.life-ops-dashboard .lo-status.neutral {
  border-color: #d7dee8;
  background: #f4f7fa;
  color: #45536b;
}

/* =========================================================
   SCHEDULER
   ========================================================= */

.life-ops-dashboard .lo-scheduler-head {
  align-items: flex-start;
}

.life-ops-dashboard .lo-scheduler-stats {
  display: flex;
  flex-wrap: wrap;
  justify-content: flex-end;
  gap: 8px;
}

.life-ops-dashboard .lo-scheduler-stat {
  display: flex;
  min-width: 90px;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: 7px 10px;
  border: 1px solid #e8edf3;
  border-radius: 8px;
  background: #ffffff;
}

.life-ops-dashboard .lo-scheduler-stat small {
  color: #8793a6;
  font-size: 9px;
  font-weight: 700;
}

.life-ops-dashboard .lo-scheduler-stat strong {
  margin-top: 2px;
  color: #12305b;
  font-size: 16px;
  font-weight: 850;
}

.life-ops-dashboard .lo-scheduler-table {
  min-width: 1650px;
  table-layout: fixed;
}

.life-ops-dashboard .lo-scheduler-table th,
.life-ops-dashboard .lo-scheduler-table td {
  width: 145px;
  min-width: 145px;
  padding: 6px;
}

.life-ops-dashboard .lo-scheduler-table .lo-time-head,
.life-ops-dashboard .lo-scheduler-table .lo-time-cell {
  position: sticky;
  left: 0;
  z-index: 7;
  width: 88px;
  min-width: 88px;
  max-width: 88px;
  border-right: 2px solid #d4dce7;
  background: #e7edf5;
  color: #12305b;
  font-weight: 850;
  text-align: center;
  white-space: nowrap;
}

.life-ops-dashboard .lo-scheduler-table thead .lo-time-head {
  z-index: 9;
}

.life-ops-dashboard .lo-scheduler-table thead th small {
  display: block;
  margin-bottom: 2px;
  color: #8793a6;
  font-size: 8px;
  font-weight: 750;
}

.life-ops-dashboard .lo-sched-cell {
  height: 58px;
  padding: 5px !important;
  vertical-align: top !important;
}

.life-ops-dashboard .lo-past-cell {
  background: #f4f5f7 !important;
  color: #adb5bd;
  text-align: center !important;
  vertical-align: middle !important;
}

.life-ops-dashboard .lo-free-cell {
  background: #fbfdfb;
  text-align: center !important;
  vertical-align: middle !important;
}

.life-ops-dashboard .lo-slot-plus {
  display: inline-flex;
  width: 30px;
  height: 30px;
  align-items: center;
  justify-content: center;
  border: 1px dashed #83c69f;
  border-radius: 8px;
  outline: none;
  background: #f1fbf5;
  color: #198754;
  cursor: pointer;
  font-size: 18px;
  font-weight: 500;
  transition:
    transform 0.15s ease,
    border-color 0.15s ease,
    background-color 0.15s ease;
}

.life-ops-dashboard .lo-slot-plus:hover {
  transform: scale(1.06);
  border-color: #198754;
  background: #e2f7ea;
}

.life-ops-dashboard .lo-apt-card {
  display: block;
  width: 100%;
  margin-bottom: 4px;
  padding: 6px 7px;
  border: 1px solid #bfd2f4;
  border-left: 4px solid #0A9B7A;
  border-radius: 7px;
  outline: none;
  background:
    linear-gradient(
      180deg,
      #f5f9ff 0%,
