javascript:
// LIFE Operations & Service Module V93 - First 4D Cryo Per Plan Mandatory Fields
/* LIFE Operations & Service Module V82
 * Therapy execution rows = Therapy Plan child table only.
 * Sales Invoice items are not used for therapy/session balance rows.
 * custom_is_inactive is intentionally ignored for execution visibility.
 */

/* =========================================================
   LIFE OPS V44 — MOBILE PRIVACY DISPLAY
   - Shows first 3 + masked middle + last 3 digits
   - Hover/focus temporarily shows the full mobile number
   - Does not modify the actual mobile value used for search/save
   ========================================================= */
function lifeOpsPrivateMobile(value) {
  var digits = String(value || "").replace(/\D/g, "");

  if (digits.length > 10) {
    digits = digits.slice(-10);
  }

  if (!digits) {
    return { full: "-", masked: "-" };
  }

  if (digits.length <= 6) {
    return { full: digits, masked: digits };
  }

  return {
    full: digits,
