        async function renderRows(tabId, rows) {
          const tbody = dashboard.querySelector(`[data-table="${tabId}"]`);
          if (!tbody) return;

          const headers = setTableHeaders(tabId);
          const colspan = Math.max(headers.length, 1);
          const state = tableState[tabId];
          state.rows = Array.isArray(rows) ? rows : [];

          let totalPages = 1;
          let startIndex = 0;
          let pageRows = state.rows;

          if (state.serverPaged) {
            if (state.totalKnown) {
              totalPages = Math.max(
                1,
                Math.ceil(Math.max(0, Number(state.total || 0)) / PAGE_SIZE)
              );
              state.page = Math.max(1, Math.min(state.page, totalPages));
            } else {
              totalPages = Math.max(
                1,
                state.page + (state.hasMore ? 1 : 0)
              );
            }

            startIndex = (state.page - 1) * PAGE_SIZE;
          } else {
            state.total = state.rows.length;
            state.totalKnown = true;
            totalPages = Math.max(1, Math.ceil(state.rows.length / PAGE_SIZE));
            state.page = Math.max(1, Math.min(state.page, totalPages));
            startIndex = (state.page - 1) * PAGE_SIZE;
            pageRows = state.rows.slice(startIndex, startIndex + PAGE_SIZE);
          }

          tbody.innerHTML = `<tr><td colspan="${colspan}" class="lo-empty">Loading row details...</td></tr>`;

          if (pageRows.length) {
            await enrichSessionProgress(pageRows);
            await enrichResultsManagerNames(pageRows);

            /*
             * V63: Both execution reports show Consent / Before / After links.
             */
            if (
              tabId === "slimming-execution" ||
              tabId === "dermat-execution"
            ) {
              await enrichExecutionAttachments(pageRows);
            }
          }

          if (!pageRows.length) {
            tbody.innerHTML = `<tr><td colspan="${colspan}" class="lo-empty">No sessions found.</td></tr>`;
          } else {
            tbody.innerHTML = pageRows.map(function (row) {
              return "<tr>" + headers.map(function (header) {
                const classes = [];
                if (header === "Action") classes.push("lo-session-action-cell");
                if (header === "In") classes.push("lo-session-in-cell");
                if (header === "Dietitian") classes.push("lo-dietitian-cell");
                if (header === "Results Manager") classes.push("lo-results-manager-cell");
                const classAttribute = classes.length
                  ? ` class="${classes.join(" ")}"`
                  : "";
                return `<td${classAttribute}>${getCellHtml(tabId, header, row)}</td>`;
              }).join("") + "</tr>";
            }).join("");
          }

          const count = dashboard.querySelector(`[data-count="${tabId}"]`);
          if (count) {
            if (state.serverPaged && !state.totalKnown) {
              count.textContent = String(startIndex + pageRows.length) + (state.hasMore ? "+" : "");
            } else {
              count.textContent = String(Math.max(0, Number(state.total || 0)));
            }
          }

          const prefix = tabId === "therapy-session-report" ? "ts" : tabId;
          const info = dashboard.querySelector(`[data-role="${prefix}-page-info"]`);
          if (info) {
            const shownFrom = pageRows.length ? startIndex + 1 : 0;
            const shownTo = startIndex + pageRows.length;

            if (state.serverPaged && !state.totalKnown) {
              info.textContent = pageRows.length
                ? `Showing ${shownFrom}–${shownTo}${state.hasMore ? "+" : ""}`
                : "Showing 0";
            } else {
              const capNote = !state.serverPaged && state.capped
                ? ` (first ${MAX_SESSION_ROWS}; use a date filter for older records)`
                : "";

              info.textContent = pageRows.length
                ? `Showing ${shownFrom}–${shownTo} of ${Math.max(0, Number(state.total || 0))}${capNote}`
                : "Showing 0";
            }
          }

          const pageNumber = dashboard.querySelector(`[data-role="${prefix}-page-number"]`);
          if (pageNumber) {
            pageNumber.textContent = state.serverPaged && !state.totalKnown
              ? `Page ${state.page}`
              : `Page ${state.page} of ${totalPages}`;
          }

          const previous = dashboard.querySelector(`[data-action="${prefix}-prev"]`);
          const next = dashboard.querySelector(`[data-action="${prefix}-next"]`);
          if (previous) previous.disabled = state.page <= 1;
          if (next) {
            next.disabled = state.serverPaged && !state.totalKnown
              ? !state.hasMore
              : state.page >= totalPages || pageRows.length === 0;
          }
        }

        async function fetchAndRender(tabId, options) {
          const settings = options || {};
          const force = Boolean(settings.force);
          const tbody = dashboard.querySelector(`[data-table="${tabId}"]`);
          if (!tbody) return;

          const state = tableState[tabId];
          const filters = getFilters(tabId);

          /*
           * Keep the original Therapy Session Report behaviour unchanged.
           * Only Slimming Execution and Dermat Execution use true server-side
           * pagination in this build.
           */
          if (!state.serverPaged) {
            const requestKey = JSON.stringify({
              tabId: tabId,
              branch: filters.branch,
              status: filters.status,
              search: filters.search,
              from: filters.from,
              to: filters.to
            });

            if (
              !force &&
              state.loadedKey === requestKey &&
              state.rows.length &&
              Date.now() - state.loadedAt < DATA_CACHE_TTL_MS
            ) {
              await renderRows(tabId, state.rows);
              return;
            }

            const cached = dataCache.get(requestKey);
            if (
              !force &&
              cached &&
              Date.now() - cached.loadedAt < DATA_CACHE_TTL_MS
            ) {
              state.rows = cached.rows.map(function (row) {
                return Object.assign({}, row);
              });
              state.loadedKey = requestKey;
              state.loadedAt = cached.loadedAt;
              state.capped = cached.capped;
              state.total = state.rows.length;
              state.totalKnown = true;
              await renderRows(tabId, state.rows);
              return;
            }

            if (state.loadingPromise && !force) {
              return state.loadingPromise;
            }

            const headers = setTableHeaders(tabId);
            tbody.innerHTML =
              `<tr><td colspan="${Math.max(headers.length, 1)}" class="lo-empty">` +
              "Loading sessions...</td></tr>";

            const requestToken = state.requestToken + 1;
            state.requestToken = requestToken;

            const loadingPromise = (async function () {
              const fields = await getTherapySessionQueryFields();
              let serverFilters = buildServerFilters(filters);

              const response = await frappe.call({
                method: "frappe.client.get_list",
                args: {
                  doctype: "Therapy Session",
                  fields: fields,
                  filters: serverFilters,
                  limit_page_length: MAX_SESSION_ROWS,
                  order_by: "start_date desc, start_time desc, creation desc"
                }
              });

              let rows = (response.message || []).filter(function (row) {
                return sessionMatchesSearch(row, filters.search);
              });

              if (state.requestToken !== requestToken) return;

              state.rows = rows;
              state.total = rows.length;
              state.totalKnown = true;
              state.loadedKey = requestKey;
              state.loadedAt = Date.now();
              state.capped = (response.message || []).length >= MAX_SESSION_ROWS;

              dataCache.set(requestKey, {
                loadedAt: state.loadedAt,
                capped: state.capped,
                rows: rows.map(function (row) {
                  return Object.assign({}, row);
                })
              });

              await renderRows(tabId, rows);
            })().catch(function (error) {
              if (state.requestToken !== requestToken) return;

              void 0;
              tbody.innerHTML = (
                `<tr><td colspan="${Math.max(headers.length, 1)}" class="lo-empty">` +
                `Error loading sessions. ${escapeHtml(error?.message || "Check console.")}</td></tr>`
              );
            });

            state.loadingPromise = loadingPromise;

            loadingPromise.then(
              function () {
                if (
                  state.requestToken === requestToken &&
                  state.loadingPromise === loadingPromise
                ) {
                  state.loadingPromise = null;
                }
              },
              function () {
                if (
                  state.requestToken === requestToken &&
                  state.loadingPromise === loadingPromise
                ) {
                  state.loadingPromise = null;
                }
              }
            );

            return loadingPromise;
          }

          const baseRequestKey = JSON.stringify({
            tabId: tabId,
            branch: filters.branch,
            status: filters.status,
            search: filters.search,
            from: filters.from,
            to: filters.to
          });
          const pageRequestKey = baseRequestKey + "|page=" + String(state.page);

          const cachedPage = dataCache.get(pageRequestKey);
          if (
            !force &&
            cachedPage &&
            Date.now() - cachedPage.loadedAt < DATA_CACHE_TTL_MS
          ) {
            state.rows = (cachedPage.rows || []).map(function (row) {
              return Object.assign({}, row);
            });
            state.total = Number(cachedPage.total || 0);
            state.totalKnown = cachedPage.totalKnown !== false;
            state.hasMore = Boolean(cachedPage.hasMore);
            state.loadedKey = pageRequestKey;
            state.loadedAt = cachedPage.loadedAt;
            await renderRows(tabId, state.rows);
            return;
          }

          if (state.loadingPromise && !force) {
            return state.loadingPromise;
          }

          const headers = setTableHeaders(tabId);
          tbody.innerHTML =
            `<tr><td colspan="${Math.max(headers.length, 1)}" class="lo-empty">` +
            "Loading current page...</td></tr>";

          const requestToken = state.requestToken + 1;
          state.requestToken = requestToken;

          const loadingPromise = (async function () {
            const fields = await getTherapySessionQueryFields();
            let serverFilters = buildServerFilters(filters);

            await loadCategoryMap();
            const therapyTypes = getCategoryTherapyTypes(tabId);

            if (therapyTypes.length) {
              serverFilters = serverFilters.concat([
                ["therapy_type", "in", therapyTypes]
              ]);
            }

            const orFilters = buildSessionSearchOrFilters(
              filters.search,
              fields
            );

            const countKey = baseRequestKey + "|count";
            let total = null;
            const cachedCount = countCache.get(countKey);

            if (
              !force &&
              cachedCount &&
              Date.now() - cachedCount.loadedAt < DATA_CACHE_TTL_MS
            ) {
              total = cachedCount.total;
            } else {
              total = await getSessionFilteredCount(
                serverFilters,
                orFilters
              );

              if (total != null) {
                countCache.set(countKey, {
                  total: total,
                  loadedAt: Date.now()
                });
              }
            }

            const totalKnown = total != null && Number.isFinite(Number(total));

            if (totalKnown) {
              total = Math.max(0, Number(total));
              const totalPages = Math.max(1, Math.ceil(total / PAGE_SIZE));
              state.page = Math.max(1, Math.min(state.page, totalPages));
            }

            const limitStart = (state.page - 1) * PAGE_SIZE;
            const pageLength = totalKnown ? PAGE_SIZE : PAGE_SIZE + 1;

            const listArgs = {
              doctype: "Therapy Session",
              fields: fields,
              filters: serverFilters,
              limit_start: limitStart,
              limit_page_length: pageLength,
              order_by: "start_date desc, start_time desc, creation desc"
            };

            if (orFilters.length) {
              listArgs.or_filters = orFilters;
            }

            const response = await frappe.call({
              method: "frappe.client.get_list",
              args: listArgs
            });

            let rows = Array.isArray(response && response.message)
              ? response.message.slice()
              : [];

            let hasMore = false;
            if (totalKnown) {
              hasMore = limitStart + rows.length < total;
            } else if (rows.length > PAGE_SIZE) {
              hasMore = true;
              rows = rows.slice(0, PAGE_SIZE);
            } else {
              hasMore = rows.length === PAGE_SIZE;
            }

            if (state.requestToken !== requestToken) return;

            state.rows = rows;
            state.total = totalKnown
              ? total
              : limitStart + rows.length + (hasMore ? 1 : 0);
            state.totalKnown = totalKnown;
            state.hasMore = hasMore;
            state.loadedKey = baseRequestKey + "|page=" + String(state.page);
            state.loadedAt = Date.now();
            state.capped = false;

            dataCache.set(state.loadedKey, {
              loadedAt: state.loadedAt,
              total: state.total,
              totalKnown: state.totalKnown,
              hasMore: state.hasMore,
              rows: rows.map(function (row) {
                return Object.assign({}, row);
              })
            });

            await renderRows(tabId, rows);
          })().catch(function (error) {
            if (state.requestToken !== requestToken) return;

            void 0;
            tbody.innerHTML = (
              `<tr><td colspan="${Math.max(headers.length, 1)}" class="lo-empty">` +
              `Error loading sessions. ${escapeHtml(error?.message || "Check console.")}</td></tr>`
            );
          });

          state.loadingPromise = loadingPromise;

          loadingPromise.then(
            function () {
              if (
                state.requestToken === requestToken &&
                state.loadingPromise === loadingPromise
              ) {
                state.loadingPromise = null;
              }
            },
            function () {
              if (
                state.requestToken === requestToken &&
                state.loadingPromise === loadingPromise
              ) {
                state.loadingPromise = null;
              }
            }
          );

          return loadingPromise;
        }

        function resetAndFetch(tabId) {
          tableState[tabId].page = 1;
          return fetchAndRender(tabId, { force: true });
        }

        /* V61 - Slimming/Dermat client autocomplete after 3 chars */
        const execClientTimers = Object.create(null);

        function ensureExecClientAutocomplete(tabId) {
          if (tabId !== "slimming-execution" && tabId !== "dermat-execution") return null;

          const input = dashboard.querySelector(`[data-role="${tabId}-search"]`);
          if (!input) return null;

          let wrap = input.closest(".lo-exec-client-wrap");
          if (!wrap) {
            wrap = document.createElement("div");
            wrap.className = "lo-exec-client-wrap";
            wrap.style.position = "relative";
            wrap.style.minWidth = "280px";
            input.parentNode.insertBefore(wrap, input);
            wrap.appendChild(input);
          }

          let box = wrap.querySelector(".lo-exec-client-results");
          if (!box) {
            box = document.createElement("div");
            box.className = "lo-exec-client-results";
            box.style.cssText =
              "display:none;position:absolute;left:0;right:0;top:calc(100% + 4px);z-index:10150;" +
              "max-height:320px;overflow:auto;background:#fff;border:1px solid #d7dee8;border-radius:10px;" +
              "box-shadow:0 12px 30px rgba(15,23,42,.18);";
            wrap.appendChild(box);
          }

          input.placeholder = "Type 3+ letters or mobile digits";
          input.autocomplete = "off";

          return { input: input, box: box };
        }

        function hideExecClientResults(tabId) {
          const ui = ensureExecClientAutocomplete(tabId);
          if (!ui) return;
          ui.box.style.display = "none";
          ui.box.innerHTML = "";
        }

        async function searchExecClients(tabId, query) {
          const ui = ensureExecClientAutocomplete(tabId);
          if (!ui) return;

          query = clean(query);
          if (query.length < 3) {
            hideExecClientResults(tabId);
            return;
          }

          ui.box.innerHTML = '<div style="padding:10px 12px;color:#64748b;font-size:11px;">Searching clients...</div>';
          ui.box.style.display = "block";

          const prefix = tabId;
          const branchEl = dashboard.querySelector(`[data-role="${prefix}-branch"]`);
          const branch = branchEl && branchEl.value && branchEl.value !== "all"
            ? clean(branchEl.value)
            : "";

          const filters = [["Patient", "status", "!=", "Disabled"]];
          if (branch) {
            filters.push(["Patient", "branch_name", "=", branch]);
          }

          const orFilters = [
            ["Patient", "name", "like", "%" + query + "%"],
            ["Patient", "patient_name", "like", "%" + query + "%"],
            ["Patient", "first_name", "like", "%" + query + "%"]
          ];

          const mobileQuery = String(query).replace(/\D/g, "");
          if (mobileQuery.length >= 3) {
            orFilters.push(
              ["Patient", "mobile", "like", "%" + mobileQuery + "%"],
              ["Patient", "phone", "like", "%" + mobileQuery + "%"]
            );
          }

          try {
            const response = await frappe.call({
              method: "frappe.client.get_list",
              args: {
                doctype: "Patient",
                fields: [
                  "name",
                  "patient_name",
                  "first_name",
                  "mobile",
                  "phone",
                  "branch_name",
                  "custom_branch"
                ],
                filters: filters,
                or_filters: orFilters,
                order_by: "modified desc",
                limit_start: 0,
                limit_page_length: 20
              }
            });

            const rows = Array.isArray(response && response.message)
              ? response.message
              : [];

            if (!rows.length) {
              ui.box.innerHTML = '<div style="padding:10px 12px;color:#64748b;font-size:11px;">No matching clients found.</div>';
              ui.box.style.display = "block";
              return;
            }

            ui.box.innerHTML = rows.map(function (row) {
              const name = clean(row.patient_name || row.first_name || row.name);
              const mobile = clean(row.mobile || row.phone || "-");
              const digits = String(mobile).replace(/\D/g, "").slice(-10);
              const masked = digits.length > 6
                ? digits.slice(0, 3) + "*".repeat(digits.length - 6) + digits.slice(-3)
                : digits;

              return (
                '<button type="button" data-exec-client-id="' + escapeHtml(row.name) + '" ' +
                'style="display:flex;width:100%;justify-content:space-between;gap:12px;padding:10px 12px;' +
                'border:0;border-bottom:1px solid #edf1f5;background:#fff;text-align:left;cursor:pointer;">' +
                  '<span>' +
                    '<strong style="display:block;color:#12305b;font-size:12px;">' + escapeHtml(name) + '</strong>' +
                    '<small style="color:#64748b;">ID: ' + escapeHtml(row.name) +
                    ' · ' + escapeHtml(row.branch_name || row.custom_branch || "-") + '</small>' +
                  '</span>' +
                  '<span style="color:#0a7f65;font-size:11px;font-weight:800;">' + escapeHtml(masked || "-") + '</span>' +
                '</button>'
              );
            }).join("");

            ui.box.style.display = "block";
          } catch (error) {
            void 0;
            ui.box.innerHTML = '<div style="padding:10px 12px;color:#b42318;font-size:11px;">Client search failed.</div>';
            ui.box.style.display = "block";
          }
        }

        function bindTableEvents(tabId) {
          const page = dashboard.querySelector(`[data-page="${tabId}"]`);
          if (!page) return;

          page.querySelectorAll("[data-ts-filter], .lo-cat-quick").forEach(function (button) {
            button.addEventListener("click", function () {
              page.querySelectorAll("[data-ts-filter], .lo-cat-quick").forEach(function (item) {
                item.classList.remove("active");
              });

              button.classList.add("active");

              const quickValue =
                button.dataset.tsFilter ||
                button.dataset.catFilter ||
                "all";

              /*
               * Keep the visible From and To inputs synchronized with the
               * selected quick filter before querying Therapy Session.
               */
              applyQuickDateRangeToFields(tabId, quickValue);
              resetAndFetch(tabId);
            }, { signal });
          });

          const prefix =
            tabId === "therapy-session-report"
              ? "ts"
              : tabId;

          const dateFields = getDateFieldElements(tabId);

          [dateFields.from, dateFields.to].forEach(function (field) {
            if (!field) return;

            field.addEventListener("change", function () {
              /* A manually changed date range is treated as a custom range. */
              page.querySelectorAll("[data-ts-filter], .lo-cat-quick").forEach(function (item) {
                item.classList.toggle(
                  "active",
                  (item.dataset.tsFilter || item.dataset.catFilter) === "all"
                );
              });
            }, { signal });
          });

          const apply = dashboard.querySelector(
            `[data-action="${prefix}-apply-filters"], ` +
            `[data-action="${prefix}-date-search"]`
          );

          if (apply) {
            apply.addEventListener(
              "click",
              function () {
                resetAndFetch(tabId);
              },
              { signal }
            );
          }

          const branch = dashboard.querySelector(
            `[data-role="${prefix}-branch"]`
          );

          if (branch) {
            branch.addEventListener(
              "change",
              function () {
                resetAndFetch(tabId);
              },
              { signal }
            );
          }

          const search = dashboard.querySelector(
            `[data-role="${prefix}-search"]`
          );

          if (search) {
            if (
              tabId === "slimming-execution" ||
              tabId === "dermat-execution"
            ) {
              const ui = ensureExecClientAutocomplete(tabId);

              search.addEventListener(
                "input",
                function () {
                  window.clearTimeout(execClientTimers[tabId]);
                  const q = clean(search.value);

                  if (q.length < 3) {
                    hideExecClientResults(tabId);
                    return;
                  }

                  execClientTimers[tabId] = window.setTimeout(function () {
                    searchExecClients(tabId, q);
                  }, 220);
                },
                { signal }
              );

              if (ui && ui.box) {
                ui.box.addEventListener(
                  "click",
                  function (event) {
                    const btn = event.target.closest("[data-exec-client-id]");
                    if (!btn) return;

                    search.value = clean(btn.dataset.execClientId);
                    hideExecClientResults(tabId);
                    resetAndFetch(tabId);
                  },
                  { signal }
                );
              }
            }

            search.addEventListener(
              "keydown",
              function (event) {
                if (event.key === "Enter") {
                  hideExecClientResults(tabId);
                  resetAndFetch(tabId);
                }
                if (event.key === "Escape") {
                  hideExecClientResults(tabId);
                }
              },
              { signal }
            );
          }

          const previous = dashboard.querySelector(
            `[data-action="${prefix}-prev"]`
          );
          const next = dashboard.querySelector(
            `[data-action="${prefix}-next"]`
          );

          if (previous) {
            previous.addEventListener("click", function () {
              const currentState = tableState[tabId];
              if (currentState.page > 1) {
                currentState.page -= 1;

                if (currentState.serverPaged) {
                  fetchAndRender(tabId);
                } else {
                  renderRows(
                    tabId,
                    currentState.rows || []
                  );
                }
              }
            }, { signal });
          }

          if (next) {
            next.addEventListener("click", function () {
              const currentState = tableState[tabId];

              if (currentState.serverPaged) {
                const totalPages = currentState.totalKnown
