      function pickValue(doc, keys) {
        for (
          var i = 0;
          i < keys.length;
          i += 1
        ) {
          var value = doc
            ? doc[keys[i]]
            : null;

          if (
            value !== undefined &&
            value !== null &&
            text(value).trim() !== ""
