      async function mapWithConcurrency(
        items,
        concurrency,
        mapper
      ) {
        var list = Array.isArray(items)
          ? items
          : [];

        var results = new Array(list.length);
        var currentIndex = 0;

        async function worker() {
          while (currentIndex < list.length) {
            var index = currentIndex;

            currentIndex += 1;

            try {
              results[index] = await mapper(
                list[index],
                index
              );
            } catch (error) {

              results[index] = null;
            }
          }
        }

        var workerCount = Math.max(
          1,
          Math.min(
            Number(concurrency || 8),
            list.length || 1
          )
        );

        var workers = [];

        for (
          var i = 0;
          i < workerCount;
          i += 1
        ) {
          workers.push(worker());
        }

        await Promise.all(workers);

        return results.filter(Boolean);
      }
