      // Scans a child-table array (e.g. doc.custom_upload_images) and returns
      // the first value that looks like an uploaded file URL, regardless of
      // the exact Attach fieldname used on that child doctype.
      function extractFirstAttachUrl(rows) {
        if (!Array.isArray(rows)) {
          return "";
        }

        for (var i = 0; i < rows.length; i += 1) {
          var row = rows[i];
          if (!row || typeof row !== "object") {
            continue;
          }

          for (var key in row) {
            if (!Object.prototype.hasOwnProperty.call(row, key)) {
              continue;
            }

            var value = row[key];

            if (
              typeof value === "string" &&
              (
                value.indexOf("/files/") === 0 ||
                value.indexOf("/private/files/") === 0 ||
                /\.(jpe?g|png|webp|gif|bmp)$/i.test(value)
              )
            ) {
              return value;
            }
          }
        }

        return "";
      }

