        async function resolveSessionTherapistNames(
        rows
      ) {
        var sessions =
          Array.isArray(rows)
            ? rows
            : [];

        /*
         * Fetch only practitioner IDs for which
         * the Therapy Session did not already provide a name.
         */
        var practitionerIds =
          uniqueSortedValues(
            sessions
              .filter(
                function (row) {
                  var practitionerId =
                    text(
                      row.therapist_id
                    ).trim();

                  var currentValue =
                    text(
                      row.therapist
                    ).trim();

                  return (
                    practitionerId &&
                    (
                      !currentValue ||
                      currentValue ===
                        practitionerId
                    ) &&
                    /^HLC-PRAC-/i.test(
                      practitionerId
                    )
                  );
                }
              )
              .map(
                function (row) {
                  return row.therapist_id;
                }
              )
          );

        var idsToLoad =
          practitionerIds.filter(
            function (practitionerId) {
              return !state
                .practitionerNameMap[
                  practitionerId
                ];
            }
          );

        if (idsToLoad.length) {
          var practitionerDocs =
            await mapWithConcurrency(
              idsToLoad,
              8,
              function (
                practitionerId
              ) {
                return callGetDoc(
                  "Healthcare Practitioner",
                  practitionerId
                );
              }
            );

          practitionerDocs.forEach(
            function (doc) {
              if (
                !doc ||
                !doc.name
              ) {
                return;
              }

              state.practitionerNameMap[
                doc.name
              ] =
                pickValue(
                  doc,
                  [
                    "practitioner_name",
                    "employee_name",
                    "full_name",
                    "name"
                  ]
                ) ||
                doc.name;
            }
          );
        }

        sessions.forEach(
          function (row) {
            var resolvedName =
              state.practitionerNameMap[
                row.therapist_id
              ];

            if (resolvedName) {
              row.therapist =
                resolvedName;
            }
          }
        );
      }

