      function appointmentRange(filterName) {
        var today = state.today;

        if (filterName === "today") {
          return {
            from: today,
            to: today,
            limit: 1000
          };
        }

        if (filterName === "yesterday") {
          var yesterday = addDays(
            today,
            -1
          );

          return {
            from: yesterday,
            to: yesterday,
            limit: 1000
          };
        }

        if (filterName === "tomorrow") {
          var tomorrow = addDays(
            today,
            1
          );

          return {
            from: tomorrow,
            to: tomorrow,
            limit: 1000
          };
        }

        if (filterName === "thisweek") {
          return {
            from: startOfWeek(today),
            to: endOfWeek(today),
            limit: 2500
          };
        }

        if (filterName === "nextweek") {
          var nextWeekStart = addDays(
            startOfWeek(today),
            7
          );

          return {
            from: nextWeekStart,
            to: addDays(
              nextWeekStart,
              6
            ),
            limit: 2500
          };
        }

        if (filterName === "lastmonth") {
          var previousLifeMonth = getBusinessMonthRange(today, -1);

          return {
            from: previousLifeMonth.from,
            to: previousLifeMonth.to,
            limit: 5000
          };
        }

        if (filterName === "thismonth") {
          var currentLifeMonth = getBusinessMonthRange(today, 0);

          return {
            from: currentLifeMonth.from,
            to: currentLifeMonth.to,
            limit: 5000
          };
        }

        if (filterName === "nextmonth") {
          var nextLifeMonth = getBusinessMonthRange(today, 1);

          return {
            from: nextLifeMonth.from,
            to: nextLifeMonth.to,
            limit: 5000
          };
        }

        return {
          from: "",
          to: "",
          limit: 1000
        };
      }

      function sessionRange(filterName) {
        return appointmentRange(filterName);
      }

