        }

        try {
          var rows = await callFrappe(
            "frappe.client.get_list",
            args
          );

          rows = Array.isArray(rows) ? rows : [];

          if (rows.length) {
            var total = Number(
              rows[0].total != null
                ? rows[0].total
                : rows[0].count
            );

            if (Number.isFinite(total)) {
              return total;
            }
          }
        } catch (error) {
          window.__lifeOpsV4Debug && void 0;
        }

        if (!orFilters || !orFilters.length) {
          try {
            var count = await callFrappe(
              "frappe.client.get_count",
              {
                doctype: doctype,
                filters: filters || []
              }
            );

            count = Number(count);
            if (Number.isFinite(count)) {
              return count;
            }
          } catch (fallbackError) {
            window.__lifeOpsV4Debug && void 0;
          }
        }

        return null;
      }

      async function getAppointmentReportServerQuery() {
        var fields = await getAppointmentListFields();
        var available = {};

        fields.forEach(function (fieldname) {
          available[fieldname] = true;
        });

        var fromInput = qs('[data-role="report-from-date"]');
        var toInput = qs('[data-role="report-to-date"]');
        var fromDate = fromInput ? text(fromInput.value).trim() : "";
        var toDate = toInput ? text(toInput.value).trim() : "";

        if (!fromDate || !toDate) {
          var quickRange = appointmentRange(
            state.reportFilter || "today"
          );

          if (!fromDate && quickRange && quickRange.from) {
            fromDate = quickRange.from;
          }
          if (!toDate && quickRange && quickRange.to) {
            toDate = quickRange.to;
          }
        }

        var branchInput = qs('[data-role="report-branch"]');

        /*
         * FAST + SAFE:
         * Never wait for the visible Branch select before the report query.
         * The logged Employee/default branch is the source of truth.
         */
        var branchValue = text(
          state.loginBranch ||
          state.branch ||
          (
            branchInput
              ? branchInput.value
              : ""
          ) ||
          "all"
        ).trim();

        var statusInput = qs('[data-role="report-status"]');
        var statusValue = statusInput
          ? text(statusInput.value || "all").trim()
          : "all";

        var searchInput = qs('[data-role="report-search"]');
        var searchValue = searchInput
          ? text(searchInput.value).trim()
          : "";

        var filters = [];

        if (fromDate) {
          filters.push(["appointment_date", ">=", fromDate]);
        }

        if (toDate) {
          filters.push(["appointment_date", "<=", toDate]);
        }

        if (branchValue && branchValue !== "all") {
          if (available.branch) {
            filters.push(["branch", "=", branchValue]);
          } else if (available.branch_name) {
            filters.push(["branch_name", "=", branchValue]);
          }
        }

        if (statusValue && statusValue !== "all") {
          if (available.call_back_status) {
            filters.push(["call_back_status", "=", statusValue]);
          } else if (available.status) {
            filters.push(["status", "=", statusValue]);
          }
        }

        var orFilters = [];
        if (searchValue) {
          [
            "name",
            "patient",
            "client",
            "patient_name",
            "client_name",
            "custom_client_mobile_no",
            "mobile",
            "mobile_number",
            "concern",
            "therapy_type1",
            "therapy_type",
            "service_room",
            "service_unit",
            "room",
            "practitioner",
            "healthcare_practitioner",
            "practitioner_name",
            "healthcare_practitioner_name",
            "branch",
            "branch_name",
            "status",
            "call_back_status"
          ].forEach(function (fieldname) {
            if (available[fieldname]) {
              orFilters.push([
                fieldname,
                "like",
                "%" + searchValue + "%"
              ]);
            }
          });
        }

        return {
          fields: fields,
          filters: filters,
          orFilters: orFilters,
          fromDate: fromDate,
          toDate: toDate,
          branch: branchValue,
          status: statusValue,
          search: searchValue
        };
      }

      async function loadAppointmentReportPage(force) {
        /*
         * V26 FAST REPORT:
         * Load the visible 25 rows first. Do NOT block the table on a
         * full filtered count query. The old count-first flow could leave
         * the Appointment Report sitting on "Loading appointments..." for
         * a long time on large Patient Appointment tables.
         */
        var pageSize = Math.max(
          1,
          Number(state.reportPageSize || 25)
        );

        var query =
          await getAppointmentReportServerQuery();

        var baseKey = JSON.stringify({
          from: query.fromDate,
          to: query.toDate,
          branch: query.branch,
          status: query.status,
          search: query.search
        });

        var pageKey =
          baseKey +
          "|page=" +
          String(state.reportPage);

        var cachedPage =
          state.reportPageCache.get(pageKey);

        if (
          !force &&
          cachedPage &&
          Date.now() - cachedPage.loadedAt <
            state.reportCacheTtlMs
        ) {
          state.reportRows =
            cachedPage.rows.map(function (row) {
              return Object.assign({}, row);
            });

          state.reportTotal =
            Number(cachedPage.total || 0);

          state.reportTotalKnown =
            cachedPage.totalKnown === true;

          state.reportHasMore =
            Boolean(cachedPage.hasMore);

          return true;
        }

        var requestToken =
          state.reportRequestToken + 1;

        state.reportRequestToken =
          requestToken;

        /*
         * If an exact total is already cached, use it.
         * Otherwise keep loading non-blocking and infer Next from row 26.
         */
        var countKey =
          baseKey + "|count";

        var cachedCount =
          state.reportCountCache.get(countKey);

        var total =
          (
            !force &&
            cachedCount &&
            Date.now() - cachedCount.loadedAt <
              state.reportCacheTtlMs
          )
            ? Number(cachedCount.total)
            : null;

        var totalKnown =
          total != null &&
          Number.isFinite(total);

        if (totalKnown) {
          total = Math.max(0, total);

          var totalPages =
            Math.max(
              1,
              Math.ceil(total / pageSize)
            );

          state.reportPage =
            Math.max(
              1,
              Math.min(
                state.reportPage,
                totalPages
              )
            );
        }

        var limitStart =
          (state.reportPage - 1) *
          pageSize;

        /*
         * Always request one extra row when total is unknown.
         * This avoids an expensive count before first paint.
         */
        var pageLength =
          totalKnown
            ? pageSize
            : pageSize + 1;

        var args = {
          doctype: "Patient Appointment",
          fields: query.fields,
          filters: query.filters,
          order_by:
            "appointment_date asc, appointment_time asc, creation asc",
          limit_start: limitStart,
          limit_page_length: pageLength
        };

        if (query.orFilters.length) {
          args.or_filters =
            query.orFilters;
        }

        var rows =
          await callFrappe(
            "frappe.client.get_list",
            args
          );

        rows =
          Array.isArray(rows)
            ? rows
            : [];

        var hasMore = false;

        if (totalKnown) {
          hasMore =
            limitStart +
            rows.length <
            total;
        } else if (rows.length > pageSize) {
          hasMore = true;
          rows =
            rows.slice(0, pageSize);
        } else {
          hasMore = false;
        }

        rows =
          rows.map(
            normalizeAppointment
          );

        if (
          state.reportRequestToken !==
          requestToken
        ) {
          return false;
        }

        state.reportRows = rows;

        state.reportTotal =
          totalKnown
            ? total
            : (
                limitStart +
                rows.length +
                (hasMore ? 1 : 0)
              );

        state.reportTotalKnown =
          totalKnown;

        state.reportHasMore =
          hasMore;

        var finalPageKey =
          baseKey +
          "|page=" +
          String(state.reportPage);

        state.reportPageCache.set(
          finalPageKey,
          {
            loadedAt: Date.now(),
            total: state.reportTotal,
            totalKnown:
              state.reportTotalKnown,
            hasMore:
              state.reportHasMore,
            rows:
              rows.map(function (row) {
                return Object.assign(
                  {},
                  row
                );
              })
          }
        );

        if (
          state.reportPageCache.size >
          30
        ) {
          var oldestKey =
            state.reportPageCache
              .keys()
              .next()
              .value;

          state.reportPageCache.delete(
            oldestKey
          );
        }

        /*
         * Exact count is optional and runs AFTER rows are available.
         * It must never block the visible Appointment Report.
         */
        if (!totalKnown) {
          Promise.resolve()
            .then(function () {
              return getFilteredListCount(
                "Patient Appointment",
                query.filters,
                query.orFilters
              );
            })
            .then(function (backgroundTotal) {
              backgroundTotal =
                Number(backgroundTotal);

              if (
                !Number.isFinite(
                  backgroundTotal
                )
              ) {
                return;
              }

              state.reportCountCache.set(
                countKey,
                {
                  total:
                    backgroundTotal,
                  loadedAt:
                    Date.now()
                }
              );

              /*
               * Only update the current report state if the user has not
               * already switched page/filter while the count was running.
               */
              if (
                state.reportRequestToken ===
                  requestToken &&
                state.reportPage ===
                  Math.floor(
                    limitStart /
                    pageSize
                  ) + 1
              ) {
                state.reportTotal =
                  Math.max(
                    0,
                    backgroundTotal
                  );

                state.reportTotalKnown =
                  true;

                state.reportHasMore =
                  limitStart +
                  state.reportRows.length <
                  state.reportTotal;

                var liveCached =
                  state.reportPageCache.get(
                    finalPageKey
                  );

                if (liveCached) {
                  liveCached.total =
                    state.reportTotal;
                  liveCached.totalKnown =
                    true;
                  liveCached.hasMore =
                    state.reportHasMore;
                }

                /*
                 * Update only counters/pagination. Do not restart the table
                 * load or show another loading row.
                 */
                var countNode =
                  qs(
                    '[data-count="report"]'
                  );

                var pageInfoNode =
                  qs(
                    '[data-role="report-page-info"]'
                  );

                var pageNumberNode =
                  qs(
                    '[data-role="report-page-number"]'
                  );

                var nextNode =
                  qs(
                    '[data-action="report-next"]'
                  );

                var startIndex =
                  limitStart;

                var endIndex =
                  startIndex +
                  state.reportRows.length;

                var totalPagesNow =
                  Math.max(
                    1,
                    Math.ceil(
                      state.reportTotal /
                      pageSize
                    )
                  );

                if (countNode) {
                  countNode.textContent =
                    String(
                      state.reportTotal
                    );
                }

                if (pageInfoNode) {
                  pageInfoNode.textContent =
                    state.reportRows.length
                      ? (
                          "Showing " +
                          (startIndex + 1) +
                          "–" +
                          endIndex +
                          " of " +
                          state.reportTotal +
                          " clients"
                        )
                      : "Showing 0 clients";
                }

                if (pageNumberNode) {
                  pageNumberNode.textContent =
                    "Page " +
                    state.reportPage +
                    " of " +
                    totalPagesNow;
                }

                if (nextNode) {
                  nextNode.disabled =
                    state.reportPage >=
                      totalPagesNow ||
                    !state.reportRows.length;
                }
              }
            })
            .catch(function (countError) {
              window.__lifeOpsV4Debug &&
                void 0;
            });
        }

        return true;
      }

      async function loadAppointmentRange(
        fromDate,
        toDate,
        maximumRows
      ) {
        var rangeKey =
          appointmentRangeKey(fromDate, toDate) +
          "|" +
          String(Number(maximumRows || 1000));

        var cachedRange =
          state.appointmentRangeCache.get(rangeKey);

        if (
          cachedRange &&
          Date.now() - cachedRange.loadedAt <
            state.appointmentRangeCacheTtlMs
        ) {
          state.appointments = cachedRange.rows.map(
            function (row) {
              return Object.assign({}, row);
            }
          );
          state.appointmentsVersion += 1;
          state.schedulerRenderKey = "";

          state.currentAppointmentRange = {
            from: fromDate || "",
            to: toDate || "",
            key: appointmentRangeKey(fromDate, toDate)
          };

          return;
        }

        var filters = [];

        if (
          fromDate &&
          toDate &&
          fromDate === toDate
        ) {
          filters.push([
            "Patient Appointment",
            "appointment_date",
            "=",
            fromDate
          ]);
        } else {
          if (fromDate) {
            filters.push([
              "Patient Appointment",
              "appointment_date",
              ">=",
              fromDate
            ]);
          }

          if (toDate) {
            filters.push([
              "Patient Appointment",
              "appointment_date",
              "<=",
              toDate
            ]);
          }
        }

        var fields =
          await getAppointmentListFields();

        /*
         * IMPORTANT PERFORMANCE FIX:
         * The old code fetched only names and then called
         * frappe.client.get once for every appointment (N+1 requests).
         * This query returns all required report/scheduler fields in one call.
         */
        var rows = await callFrappe(
          "frappe.client.get_list",
          {
            doctype: "Patient Appointment",
            fields: fields,
            filters: filters,
            order_by:
              "appointment_date asc, appointment_time asc",
            limit_start: 0,
            limit_page_length:
              Math.max(
                1,
                Math.min(
                  Number(maximumRows || 1000),
                  5000
                )
              )
          }
        );

        rows = Array.isArray(rows)
          ? rows
          : [];

        state.appointments =
          rows.map(normalizeAppointment);
        state.appointmentsVersion += 1;
        state.schedulerRenderKey = "";

        state.appointmentRangeCache.set(
          rangeKey,
          {
            loadedAt: Date.now(),
            rows: state.appointments.map(
              function (row) {
                return Object.assign({}, row);
              }
            )
          }
        );

        /* Keep the cache bounded during long desk sessions. */
        if (state.appointmentRangeCache.size > 12) {
          var oldestAppointmentCacheKey =
            state.appointmentRangeCache.keys().next().value;
          state.appointmentRangeCache.delete(
            oldestAppointmentCacheKey
          );
        }

        state.currentAppointmentRange = {
          from: fromDate || "",
          to: toDate || "",
          key: appointmentRangeKey(
            fromDate,
            toDate
          )
        };

      }

