      async function loadBranches() {
        var shared =
          window.__lifeOpsUnifiedSessionCache ||
          (window.__lifeOpsUnifiedSessionCache = {});

        var fixedLoginBranch =
          state.loginBranch ||
          (
            typeof window.lifeOpsGetLoggedEmployeeBranch === "function"
              ? await window.lifeOpsGetLoggedEmployeeBranch()
              : ""
          );

        if (fixedLoginBranch) {
          state.loginBranch = fixedLoginBranch;
          state.branch = fixedLoginBranch;
          state.schedulerBranch = fixedLoginBranch;
          state.branches = [fixedLoginBranch];
          shared.branchNames = [fixedLoginBranch];
          return;
        }

        function applyBranchNames(branchNames) {
          state.branches = uniqueSortedValues(
            (Array.isArray(branchNames) ? branchNames : [])
              .filter(function (branchName) {
                return (
                  Boolean(branchName) &&
                  !(
                    typeof window.lifeOpsIsExcludedBranch === "function" &&
                    window.lifeOpsIsExcludedBranch(branchName)
                  )
                );
              })
          );
        }

        if (Array.isArray(shared.branchNames)) {
          applyBranchNames(shared.branchNames);
          return;
        }

        if (!shared.branchPromise) {
          shared.branchPromise = callFrappe(
            "frappe.client.get_list",
            {
              doctype: "Branch",
              fields: ["name"],
              order_by: "name asc",
              limit_start: 0,
              limit_page_length: 500
            }
          ).then(function (rows) {
            return (Array.isArray(rows) ? rows : [])
              .map(function (row) {
                return row.name;
              })
              .filter(Boolean);
          }).catch(function (error) {

            return [];
          });
        }

        try {
          var branchNames = await shared.branchPromise;
          shared.branchNames = branchNames;
          applyBranchNames(branchNames);
        } finally {
          shared.branchPromise = null;
        }
      }

