      function getBusinessMonthRange(
      referenceDate,
      monthOffset
    ) {
      var reference =
        parseDate(
          referenceDate ||
          state.today
        );

      var start;

      if (
        reference.getDate() >= 6
      ) {
        start =
          new Date(
            reference.getFullYear(),
            reference.getMonth(),
            6
          );
      } else {
        start =
          new Date(
            reference.getFullYear(),
            reference.getMonth() - 1,
            6
          );
      }

      start =
        new Date(
          start.getFullYear(),
          start.getMonth() +
            Number(monthOffset || 0),
          6
        );

      var end =
        new Date(
          start.getFullYear(),
          start.getMonth() + 1,
          5
        );

      return {
        from: toISO(start),
        to: toISO(end)
      };
    }

