      function cleanServiceRoomLabel(
        roomName,
        branch
      ) {
        var room =
          text(roomName).trim();

        var branchName =
          text(branch).trim();

        if (
          !room ||
          !branchName
        ) {
          return room;
        }

        var cleanedLabel =
          room.replace(
            new RegExp(
              "\\s*-\\s*" +
                escapeRegExp(branchName) +
                "\\s*$",
              "i"
            ),
            ""
          ).trim();

        /*
         * Some sites have a Service Room whose document name is
         * exactly the same as the Branch name. Removing the branch
         * suffix in that case produced a blank Scheduler heading.
         */
        return (
          cleanedLabel ||
          room ||
          "Service Room"
        );
      }

      function serviceRoomBelongsToBranch(
        roomName,
        branch
      ) {
        var room =
          text(roomName)
            .trim()
            .toLowerCase();

        var branchName =
          text(branch)
            .trim()
            .toLowerCase();

        if (
          !room ||
          !branchName
        ) {
          return false;
        }

        return (
          room === branchName ||
          room.endsWith(
            "-" + branchName
          ) ||
          room.endsWith(
            " - " + branchName
          )
        );
      }

