      function getBranchServiceRooms(
        branch
      ) {
        var branchName =
          text(branch).trim();

        if (!branchName) {
          return [];
        }

        return state.serviceRooms
          .filter(
            function (roomName) {
              return serviceRoomBelongsToBranch(
                roomName,
                branchName
              );
            }
          )
          .sort(
            function (a, b) {
              var left =
                cleanServiceRoomLabel(
                  a,
                  branchName
                );

              var right =
                cleanServiceRoomLabel(
                  b,
                  branchName
                );

              var leftKey =
                canonicalRoom(left);

              var rightKey =
                canonicalRoom(right);

              var orderMap = {
                "cryo-zimmer": 0,
                "hair-1": 1,
                "laser-1": 2,
                "skin-1": 3,
                "slimming-1": 4,
                "slimming-2": 5,
                "slimming-3": 6,
                "slimming-4": 7,
                "slimming-5": 8,
                "slimming-6": 9
              };

              var leftOrder =
                Object.prototype.hasOwnProperty.call(
                  orderMap,
                  leftKey
                )
                  ? orderMap[leftKey]
                  : 999;

              var rightOrder =
                Object.prototype.hasOwnProperty.call(
                  orderMap,
                  rightKey
                )
                  ? orderMap[rightKey]
                  : 999;

              if (
                leftOrder !==
                rightOrder
              ) {
                return (
                  leftOrder -
                  rightOrder
                );
              }

              return left.localeCompare(
                right,
                undefined,
                {
                  numeric: true,
                  sensitivity: "base"
                }
              );
            }
          );
      }

      function resolveServiceRoomName(
        roomValue,
        branch
      ) {
        var suppliedRoom =
          text(roomValue).trim();

        var branchName =
          text(branch).trim();

        if (
          !suppliedRoom ||
          !branchName
        ) {
          return "";
        }

        /*
         * The current value is already the real
         * Service Room document name.
         */
        if (
          state.serviceRooms.indexOf(
            suppliedRoom
          ) !== -1
        ) {
          return suppliedRoom;
        }

        var suppliedLabel =
          cleanServiceRoomLabel(
            suppliedRoom,
            branchName
          );

        var branchRooms =
          getBranchServiceRooms(
            branchName
          );

        var exactMatch =
          branchRooms.find(
            function (roomName) {
              return (
                cleanServiceRoomLabel(
                  roomName,
                  branchName
                ).toLowerCase() ===
                suppliedLabel.toLowerCase()
              );
            }
          );

        if (exactMatch) {
          return exactMatch;
        }

        var canonicalMatch =
          branchRooms.find(
            function (roomName) {
              return (
                canonicalRoom(
                  cleanServiceRoomLabel(
                    roomName,
                    branchName
                  )
                ) ===
                canonicalRoom(
                  suppliedLabel
                )
              );
            }
          );

        return (
          canonicalMatch ||
          ""
        );
      }

      function schedulerRoomsForBranch(
        branch
      ) {
        var selectedBranch =
          text(branch).trim();

        var branchesToShow =
          isAllBranch(selectedBranch)
            ? collectBranches()
            : [selectedBranch];

        var schedulerRooms = [];

        branchesToShow.forEach(
          function (branchName) {
            if (!branchName) {
              return;
            }

            getBranchServiceRooms(
              branchName
            ).forEach(
              function (roomName) {
                schedulerRooms.push({
                  /*
                   * Real Service Room Link value.
                   */
                  name:
                    roomName,

                  /*
                   * Branch that owns this room.
                   * Required when Scheduler is on All Branches.
                   */
                  branch:
                    branchName,

                  /*
                   * Short heading displayed in the Scheduler.
                   */
                  label:
                    cleanServiceRoomLabel(
                      roomName,
                      branchName
                    )
                });
              }
            );
          }
        );

        return schedulerRooms;
      }

