    async function reloadTodayData() {
      if (state.loading) {
        return;
      }

      state.loading = true;

      try {
        /*
         * V26 FAST START:
         * Use the already-booted User Default branch immediately so the
         * Appointment Report can start before Employee/KPI count requests.
         */
        var immediateBranch =
          text(
            getDefaultBranch() || ""
          ).trim();

        if (
          immediateBranch &&
          !(
            typeof window.lifeOpsIsExcludedBranch === "function" &&
            window.lifeOpsIsExcludedBranch(
              immediateBranch
            )
          )
        ) {
          state.loginBranch =
            immediateBranch;

          state.branch =
            immediateBranch;

          state.schedulerBranch =
            immediateBranch;

          state.branches = [
            immediateBranch
          ];

          populateBranchOptions();

          /*
           * Render the visible Appointment Report immediately.
           * Do not wait for KPI counts.
           */
          renderAll();
        }

        /*
         * Resolve the Employee.branch in parallel. For accounts without a
         * User Default branch we wait for this before exposing report data.
         */
        var branchPromise =
          (
            typeof window.lifeOpsGetLoggedEmployeeBranch ===
              "function"
          )
            ? window.lifeOpsGetLoggedEmployeeBranch()
            : Promise.resolve(
                immediateBranch
              );

        var resolvedBranch =
          await branchPromise;

        resolvedBranch =
          text(
            resolvedBranch ||
            immediateBranch ||
            ""
          ).trim();

        if (
          resolvedBranch &&
          !(
            typeof window.lifeOpsIsExcludedBranch === "function" &&
            window.lifeOpsIsExcludedBranch(
              resolvedBranch
            )
          )
        ) {
          var branchChanged =
            state.branch !==
            resolvedBranch;

          state.loginBranch =
            resolvedBranch;

          state.branch =
            resolvedBranch;

          state.schedulerBranch =
            resolvedBranch;

          state.branches = [
            resolvedBranch
          ];

          if (branchChanged) {
            state.reportPage = 1;
            state.reportPageCache.clear();
            state.reportCountCache.clear();
          }
        } else {
          await loadBranches();
        }

        state.reportFilter = "today";
        state.executionFilter = "today";
        state.reportPage = 1;
        state.executionPage = 1;

        populateBranchOptions();

        /*
         * Start/refresh report now. This is the primary visible data.
         */
        renderAll();

        /*
         * KPI counts are secondary. Run them in the background so a slow
         * count cannot hold the Appointment Report on "Loading...".
         */
        Promise.all([
          loadAppointmentKpiCounts(),
          loadTodayExecutionCount()
        ])
          .then(function () {
            renderKPIs();
          })
          .catch(function (kpiError) {
            window.__lifeOpsV4Debug &&
              void 0;
          });

        /* Warm the small Service Room master while the report is idle. */
        prefetchSchedulerRooms();

      } catch (error) {
        void 0;

        showError(
          "Dashboard data could not be loaded. Check the first red console error."
        );
      } finally {
        state.loading = false;
        setLoading(false);
      }
    }

      function collectBranches() {
        var values =
          state.branches.slice();

        state.appointments.forEach(
          function (row) {
            values.push(row.branch);
          }
        );

        state.sessions.forEach(
          function (row) {
            values.push(row.branch);
          }
        );

        state.todaySessions.forEach(
          function (row) {
            values.push(row.branch);
          }
        );

        if (!isAllBranch(state.branch)) {
          values.push(state.branch);
        }

        return uniqueSortedValues(
          values.filter(function (branchName) {
            return !(
              typeof window.lifeOpsIsExcludedBranch === "function" &&
              window.lifeOpsIsExcludedBranch(branchName)
            );
          })
        );
      }

      function populateBranchOptions() {
        var branches =
          collectBranches();

        /*
         * Permission-aware branch rule:
         * - 1 permitted branch  -> show/select only that branch.
         * - 2+ permitted branches -> show "All Branches" + permitted branches.
         *
         * Branches come from permission-aware frappe.client.get_list calls,
         * so this never manufactures access to an unpermitted branch.
         */
        var allowAllBranches =
          branches.length > 1;

        var singleBranch =
          branches.length === 1
            ? branches[0]
            : "";

        if (singleBranch) {
          state.branch = singleBranch;
        } else if (
          allowAllBranches &&
          !state.branch
        ) {
          state.branch = "all";
        }

        var sharedHtml = [];

        if (allowAllBranches) {
          sharedHtml.push(
            '<option value="all">All Branches</option>'
          );
        }

        branches.forEach(
          function (branch) {
            sharedHtml.push(
              '<option value="' +
                escapeHtml(branch) +
              '">' +
                escapeHtml(
                  branchLabel(branch)
                ) +
              "</option>"
            );
          }
        );

        qsa(
          '[data-role="head-branch"], ' +
          '[data-role="report-branch"], ' +
          '[data-role="execution-branch"], ' +
          '[data-role="today-exec-branch"]'
        ).forEach(
          function (select) {
            select.innerHTML =
              sharedHtml.join("");

            var preferred =
              singleBranch ||
              state.branch ||
              (
                allowAllBranches
                  ? "all"
                  : ""
              );

            var exists =
              Array.prototype.some.call(
                select.options,
                function (option) {
                  return (
                    option.value ===
                    preferred
                  );
                }
              );

            var fallback =
              singleBranch ||
              (
                allowAllBranches
                  ? "all"
                  : (
                      branches[0] ||
                      ""
                    )
              );

            select.value =
              exists
                ? preferred
                : fallback;

            if (state.loginBranch) {
              select.value = state.loginBranch;
              select.disabled = true;
              select.title =
                "Branch is fixed from the logged-in Employee.";
            } else {
              select.disabled = false;
            }
          }
        );

        var schedulerSelect =
          qs(
            '[data-role="scheduler-branch"]'
          );

        if (!schedulerSelect) {
          return;
        }

        var schedulerHtml = [];

        if (allowAllBranches) {
          schedulerHtml.push(
            '<option value="all">All Branches</option>'
          );
        }

        branches.forEach(
          function (branch) {
            schedulerHtml.push(
              '<option value="' +
                escapeHtml(branch) +
              '">' +
                escapeHtml(
                  branchLabel(branch)
                ) +
              "</option>"
            );
          }
        );

        schedulerSelect.innerHTML =
          schedulerHtml.join("");

        var preferredSchedulerBranch =
          text(
            state.schedulerBranch
          ).trim();

        if (singleBranch) {
          preferredSchedulerBranch =
            singleBranch;
        }

        var schedulerBranchExists =
          (
            allowAllBranches &&
            preferredSchedulerBranch === "all"
          ) ||
          branches.indexOf(
            preferredSchedulerBranch
          ) !== -1;

        if (!schedulerBranchExists) {
          var defaultBranch =
            text(
              getDefaultBranch()
            ).trim();

          if (
            defaultBranch &&
            branches.indexOf(
              defaultBranch
            ) !== -1
          ) {
            preferredSchedulerBranch =
              defaultBranch;
          } else if (
            !isAllBranch(state.branch) &&
            branches.indexOf(
              state.branch
            ) !== -1
          ) {
            preferredSchedulerBranch =
              state.branch;
          } else if (singleBranch) {
            preferredSchedulerBranch =
              singleBranch;
          } else if (allowAllBranches) {
            preferredSchedulerBranch =
              "all";
          } else {
            preferredSchedulerBranch =
              branches[0] || "";
          }
        }

        state.schedulerBranch =
          preferredSchedulerBranch;

        schedulerSelect.value =
          preferredSchedulerBranch;

        schedulerSelect.disabled =
          Boolean(state.loginBranch);

        if (state.loginBranch) {
          schedulerSelect.value = state.loginBranch;
          state.schedulerBranch = state.loginBranch;
          schedulerSelect.title =
            "Branch is fixed from the logged-in Employee.";
        }
      }

      function syncBranchInputs(branchValue) {
        var branches =
          collectBranches();

        var singleBranch =
          branches.length === 1
            ? branches[0]
            : "";

        var allowAllBranches =
          branches.length > 1;

        if (singleBranch) {
          state.branch = singleBranch;
        } else {
          state.branch =
            branchValue ||
            (
              allowAllBranches
                ? "all"
                : (
                    branches[0] ||
                    ""
                  )
            );
        }

        qsa(
          '[data-role="head-branch"], ' +
          '[data-role="report-branch"], ' +
          '[data-role="execution-branch"], ' +
          '[data-role="today-exec-branch"]'
        ).forEach(
          function (select) {
            var exists =
              Array.prototype.some.call(
                select.options,
                function (option) {
                  return (
                    option.value ===
                    state.branch
                  );
                }
              );

            var fallback =
              singleBranch ||
              (
                allowAllBranches
                  ? "all"
                  : (
                      branches[0] ||
                      ""
                    )
              );

            select.value =
              exists
                ? state.branch
                : fallback;
          }
        );
      }

      function appointmentStatus(row) {
        return text(
          row.call_back_status ||
          row.status
        ).trim();
      }

      function isCancelled(row) {
        return (
          appointmentStatus(row)
            .toLowerCase()
            .indexOf("cancel") !== -1
        );
      }

      function isPending(row) {
        var status =
          appointmentStatus(row)
            .toLowerCase();

        return (
          !status ||
          status.indexOf("pending") !== -1 ||
          status.indexOf("open") !== -1 ||
          status.indexOf("scheduled") !== -1 ||
          status.indexOf("re-confirm") !== -1 ||
          status.indexOf("reconfirm") !== -1 ||
          status.indexOf("confirm") !== -1
        );
      }

      function statusClass(status) {
        var value =
          text(status).toLowerCase();

        if (
          value.indexOf("cancel") !== -1 ||
          value.indexOf("reject") !== -1 ||
          value.indexOf("no show") !== -1
        ) {
          return "danger";
        }

        if (
          value.indexOf("visit") !== -1 ||
          value.indexOf("execut") !== -1 ||
          value.indexOf("complete") !== -1 ||
          value.indexOf("closed") !== -1
        ) {
          return "success";
        }

        if (
          value.indexOf("postpon") !== -1 ||
          value.indexOf("pending") !== -1 ||
          value.indexOf("re-confirm") !== -1 ||
          value.indexOf("reconfirm") !== -1
        ) {
          return "warning";
        }

        return "neutral";
      }

      function schedulerAppointmentStatusClass(status) {
      var value = text(status)
        .trim()
        .toLowerCase()
        .replace(/[_\s]+/g, "-");

      if (
        value.indexOf("cancel") !== -1 ||
        value.indexOf("no-show") !== -1 ||
        value.indexOf("reject") !== -1
      ) {
        return "lo-sched-status-cancelled";
      }

      if (value.indexOf("postpon") !== -1) {
        return "lo-sched-status-postponed";
      }

      if (
        value.indexOf("re-sched") !== -1 ||
        value.indexOf("resched") !== -1
      ) {
        return "lo-sched-status-rescheduled";
      }

      if (
        value.indexOf("re-confirm") !== -1 ||
        value.indexOf("reconfirm") !== -1
      ) {
        return "lo-sched-status-reconfirm";
      }

      if (value === "confirmed") {
        return "lo-sched-status-confirmed";
      }

      if (value.indexOf("not-answer") !== -1) {
        return "lo-sched-status-not-answering";
      }

      if (
        value.indexOf("visit") !== -1 ||
        value.indexOf("execut") !== -1 ||
        value.indexOf("complete") !== -1 ||
        value.indexOf("closed") !== -1
      ) {
        return "lo-sched-status-completed";
      }

      if (
        value.indexOf("pending") !== -1 ||
        value.indexOf("open") !== -1
      ) {
        return "lo-sched-status-pending";
      }

      return "lo-sched-status-scheduled";
    }

      function setText(
        selector,
        value
      ) {
        var element = qs(selector);

        if (element) {
          element.textContent = value;
        }
      }

      function renderKPIs() {
        var todayExecutions =
          state.todayExecutionCount === null
            ? "—"
            : state.todayExecutionCount;

        setText(
          '[data-kpi="today-appointments"]',
          state.todayAppointmentCount === null
            ? "—"
            : state.todayAppointmentCount
        );

        setText(
          '[data-kpi="month-appointments"]',
          state.monthAppointmentCount === null
            ? "—"
            : state.monthAppointmentCount
        );

        setText(
          '[data-kpi="pending-appointments"]',
          state.pendingAppointmentCount === null
            ? "—"
            : state.pendingAppointmentCount
        );

        setText(
          '[data-kpi="today-executions"]',
          todayExecutions
        );
      }

      function showTab(tabName) {
        state.activeTab = tabName;

        qsa(".lo-tab").forEach(
          function (button) {
            button.classList.toggle(
              "active",
              button.dataset.tab ===
                tabName
            );
          }
        );

        qsa(".lo-page").forEach(
          function (page) {
            page.classList.toggle(
              "active",
              page.dataset.page ===
                tabName
            );
          }
        );

        renderKPIs();

        if (tabName === "scheduler") {
          /* Paint the tab first; load the grid and overview independently. */
          showSchedulerPreparingState();
          queueSchedulerRender(0);

          var roomsPromise =
            state.serviceRoomsLoaded
              ? Promise.resolve(
                  state.serviceRooms
                )
              : loadServiceRooms();

          roomsPromise
            .then(function () {
              queueSchedulerRender(0);
            })
            .catch(function (error) {
              void 0;
            });

          loadSchedulerSelectedDate()
            .catch(function (error) {
              void 0;
            });

          queueSchedulerOverview();
          return;
        }

        renderActivePage();
      }

      function renderActivePage() {
        if (state.activeTab === "scheduler") {
          renderScheduler();
          return;
        }

        if (state.activeTab === "report") {
          renderReport();
          return;
        }

      }

      function renderAll() {
        renderKPIs();
        renderActivePage();
      }

      function schedulerSlots() {
        var slots = [];

        for (
          var minutes = 7 * 60;
          minutes <= 19 * 60;
          minutes += 30
        ) {
          var hour =
            Math.floor(minutes / 60);

          var minute =
            minutes % 60;

          slots.push(
            String(hour).padStart(2, "0") +
            ":" +
            String(minute).padStart(2, "0")
          );
        }

        return slots;
      }

      function normalizeRoom(value) {
        return text(value)
          .trim()
          .toLowerCase()
          .replace(/therapy/g, "")
          .replace(/room\s*no\.?/g, "room")
          .replace(/no\.?/g, "")
          .replace(/[._\-\/]+/g, " ")
          .replace(/\s+/g, " ")
          .trim();
      }

      function canonicalRoom(value) {
        /*
         * Keep the complete normalized Service Room name as the scheduler key.
         * The previous logic converted every unnumbered Hair room to "hair-1",
         * which caused Hair Restoration Room and Hair Transplantation Room to
         * share the same booking bucket and display one appointment twice.
         */
        return normalizeRoom(value);
      }

      function roomMatches(
        appointmentRoom,
        schedulerRoom
      ) {
        var left =
          canonicalRoom(appointmentRoom);

        var right =
          canonicalRoom(schedulerRoom);

        return Boolean(
          left &&
          right &&
          left === right
        );
      }

      function renderScheduler() {
        var dateInput =
          qs(
            '[data-role="scheduler-date"]'
          );

        var branchInput =
          qs(
            '[data-role="scheduler-branch"]'
          );

        var selectedDate =
          dateInput &&
          dateInput.value
            ? dateInput.value
            : state.today;

        var selectedBranch =
          branchInput
            ? text(
                branchInput.value
              ).trim()
            : text(
                state.schedulerBranch
              ).trim();

        if (
          dateInput &&
          !dateInput.value
        ) {
          dateInput.value =
            state.today;
        }

        if (!selectedBranch) {
          selectedBranch =
            "all";

          state.schedulerBranch =
            selectedBranch;

          if (branchInput) {
            branchInput.value =
              selectedBranch;
          }
        }

        var schedulerRooms =
          schedulerRoomsForBranch(
            selectedBranch
          );

        var appointments =
          state.appointments.filter(
            function (row) {
              return (
                row.appointment_date ===
                  selectedDate &&
                sameBranch(
                  row.branch,
                  selectedBranch
                )
              );
            }
          );

        var head =
          qs(
            '[data-table="scheduler-head"]'
          );

        var body =
          qs(
            '[data-table="scheduler"]'
          );

        if (
          !head ||
          !body
        ) {
          return;
        }

        var schedulerTable =
          head.closest
            ? head.closest("table")
            : null;

        var schedulerScroll =
          schedulerTable &&
          schedulerTable.closest
            ? schedulerTable.closest(
                ".lo-scheduler-scroll"
              )
            : null;

        var schedulerViewportWidth =
          schedulerScroll
            ? Math.max(
                0,
                Number(
                  schedulerScroll.clientWidth ||
                  schedulerScroll.offsetWidth ||
                  0
                )
              )
            : 0;

        var schedulerRenderKey = [
          selectedDate,
          selectedBranch,
          state.appointmentsVersion,
          state.serviceRoomsVersion,
          schedulerViewportWidth
        ].join("|");

        if (
          state.schedulerRenderKey ===
            schedulerRenderKey &&
          head.childNodes.length &&
          body.childNodes.length
        ) {
          return;
        }

        state.schedulerRenderKey =
          schedulerRenderKey;

        /*
         * Build explicit Scheduler columns.
         * The time column always stays narrow, while room columns
         * share the available width and become horizontally scrollable
         * when there are several rooms.
         */
        if (schedulerTable) {
          var timeColumnWidth = 96;
          var minimumRoomColumnWidth = 220;
          var roomCount =
            Math.max(
              1,
              schedulerRooms.length
            );

          var availableRoomWidth =
            Math.max(
              0,
              schedulerViewportWidth -
                timeColumnWidth -
                2
            );

          var roomColumnWidth =
            schedulerRooms.length
              ? Math.max(
                  minimumRoomColumnWidth,
                  Math.floor(
                    availableRoomWidth /
                    schedulerRooms.length
                  )
                )
              : minimumRoomColumnWidth;

          var schedulerTableWidth =
            timeColumnWidth +
            roomColumnWidth *
              roomCount;

          var previousColumnGroup =
            schedulerTable.querySelector(
              'colgroup[data-life-scheduler-columns="1"]'
            );

          if (previousColumnGroup) {
            previousColumnGroup.remove();
          }

          var schedulerColumnGroup =
            document.createElement(
              "colgroup"
            );

          schedulerColumnGroup.setAttribute(
            "data-life-scheduler-columns",
            "1"
          );

          var timeColumn =
            document.createElement("col");

          timeColumn.style.width =
            timeColumnWidth + "px";

          schedulerColumnGroup.appendChild(
            timeColumn
          );

          for (
            var roomColumnIndex = 0;
            roomColumnIndex < roomCount;
            roomColumnIndex += 1
          ) {
            var roomColumn =
              document.createElement("col");

            roomColumn.style.width =
              roomColumnWidth + "px";

            schedulerColumnGroup.appendChild(
              roomColumn
            );
          }

          schedulerTable.insertBefore(
            schedulerColumnGroup,
            schedulerTable.firstChild
          );

          schedulerTable.style.width =
            schedulerTableWidth + "px";

          schedulerTable.style.minWidth =
            schedulerTableWidth + "px";

          schedulerTable.style.tableLayout =
            "fixed";
        }

        /* Index bookings once instead of filtering per room/slot cell. */
        var schedulerBookingMap =
          new Map();

        appointments.forEach(
          function (appointment) {
            var roomKey =
              canonicalRoom(
                appointment.service_room
              );

            var slotKey =
              roundHalfHour(
                appointment.appointment_time
              );

            var branchKey =
              text(appointment.branch)
                .trim()
                .toLowerCase();

            if (
              !roomKey ||
              !slotKey
            ) {
              return;
            }

            var key = [
              branchKey,
              slotKey,
              roomKey
            ].join("||");

            if (!schedulerBookingMap.has(key)) {
              schedulerBookingMap.set(
                key,
                []
              );
            }

            schedulerBookingMap
              .get(key)
              .push(appointment);
          }
        );

        head.innerHTML =
          "<tr>" +

            '<th class="lo-time-head" ' +
              'style="width:96px;min-width:96px;max-width:96px">' +
              "⏱" +
            "</th>" +

            schedulerRooms
              .map(
                function (room) {
                  return (
                    '<th class="lo-room-head" title="' +
                      escapeHtml(
                        room.name
                      ) +
                    '">' +

                      (
                        isAllBranch(
                          selectedBranch
                        )
                          ? (
                              "<small>" +
                                escapeHtml(
                                  branchLabel(
                                    room.branch
                                  )
                                ) +
                              "</small>"
                            )
                          : ""
                      ) +

                      escapeHtml(
                        room.label
                      ) +

                    "</th>"
                  );
                }
              )
              .join("") +

          "</tr>";

        if (!schedulerRooms.length) {
          body.innerHTML =
            "<tr>" +
              '<td colspan="1" class="lo-empty">' +
                "No Service Room records were found for " +
                escapeHtml(
                  isAllBranch(
                    selectedBranch
                  )
                    ? "All Branches"
                    : (
                        selectedBranch ||
                        "the selected branch"
                      )
                ) +
                "." +
              "</td>" +
            "</tr>";

          setText(
            '[data-scheduler-stat="appointments"]',
            appointments.length
          );

          setText(
            '[data-scheduler-stat="available"]',
            0
          );

          setText(
            '[data-scheduler-stat="rooms"]',
            0
          );

          setText(
            '[data-scheduler-stat="cancelled"]',
            appointments.filter(
              isCancelled
            ).length
          );

          return;
        }

        var occupiedCells = 0;

        var slots =
          schedulerSlots();

        body.innerHTML =
          slots
            .map(
              function (slot) {
                var roomCells =
                  schedulerRooms
                    .map(
                      function (room) {
                        var bookingKey = [
                          text(room.branch)
                            .trim()
                            .toLowerCase(),
                          slot,
                          canonicalRoom(
                            room.name
                          )
                        ].join("||");

                        var bookings =
                          schedulerBookingMap.get(
                            bookingKey
                          ) || [];

                        if (
                          bookings.length
                        ) {
                          var activeBookings = bookings.filter(function (booking) {
                            var key = text(appointmentStatus(booking))
                              .toLowerCase().replace(/[-_\s]/g, "");
                            return key !== "rescheduled";
                          });

                          if (activeBookings.length) {
                            occupiedCells += 1;
                          }

                          var releasedSlotButton = "";

                          if (
                            !activeBookings.length &&
                            isFutureSlot(selectedDate, slot)
                          ) {
                            releasedSlotButton =
                              '<button type="button" ' +
                              'class="lo-slot-plus life-released-slot" ' +
                              'data-action="book-slot" ' +
                              'data-branch="' + escapeHtml(room.branch) + '" ' +
                              'data-date="' + escapeHtml(selectedDate) + '" ' +
                              'data-time="' + escapeHtml(slot) + '" ' +
                              'data-room="' + escapeHtml(room.name) + '">' +
                              '+ Book this slot</button>';
                          }

                          return (
                            '<td class="lo-sched-cell">' +

                              '<div class="lo-sched-bookings">' +

                                bookings
                                  .map(
                                    function (
                                      booking
                                    ) {
                                      var status =
                                        appointmentStatus(
                                          booking
                                        ) ||
                                        "Scheduled";

                                      var service =
                                       booking.concern ||
                                       booking.therapy_type ||
                                          "—";

                                       var schedulerStatusClass =
                                       schedulerAppointmentStatusClass(
                                       status
                                         );

                                        return (
                                        '<button ' +
                                          'type="button" ' +
                                          'class="lo-apt-card ' +
                                           schedulerStatusClass +
                                           '" ' +
                                          'data-open-appointment="' +
                                            escapeHtml(
                                              booking.name
                                            ) +
                                          '" ' +
                                          'title="' +
                                            escapeHtml(
                                              (
                                                booking.patient_name ||
                                                booking.patient ||
                                                "Client"
                                              ) +
                                              " - " +
                                              status +
                                              " - " +
                                              service
                                            ) +
                                          '">' +

                                          '<strong class="lo-apt-client">' +
                                            escapeHtml(
                                              booking.patient_name ||
                                              booking.patient ||
                                              "Client"
                                            ) +
                                          "</strong>" +

                                          '<span class="lo-apt-status">' +
                                            escapeHtml(
                                              status
                                            ) +
                                          "</span>" +

                                          '<small class="lo-apt-service">' +
                                            escapeHtml(
                                              service
                                            ) +
                                          "</small>" +

                                        "</button>"
                                      );
                                    }
                                  )
                                  .join("") +
                                  releasedSlotButton +

                              "</div>" +

                            "</td>"
                          );
                        }

                        if (
                          isFutureSlot(
                            selectedDate,
                            slot
                          )
                        ) {
                          return (
                            '<td class="lo-sched-cell lo-free-cell">' +

                              '<button ' +
                                'type="button" ' +
                                'class="lo-slot-plus" ' +
                                'data-action="book-slot" ' +
                                'data-branch="' +
                                  escapeHtml(
                                    room.branch
                                  ) +
                                '" ' +
                                'data-date="' +
                                  escapeHtml(
                                    selectedDate
                                  ) +
                                '" ' +
                                'data-time="' +
                                  escapeHtml(
                                    slot
                                  ) +
                                '" ' +
                                'data-room="' +
                                  escapeHtml(
                                    room.name
                                  ) +
                                '">' +

                                "+" +

                              "</button>" +

                            "</td>"
                          );
                        }

                        return (
                          '<td class="lo-sched-cell lo-past-cell">' +
                            "—" +
                          "</td>"
                        );
                      }
                    )
                    .join("");

                return (
                  "<tr>" +

                    '<th class="lo-time-cell" ' +
                      'style="width:96px;min-width:96px;max-width:96px">' +
                      escapeHtml(
                        displayHour(slot)
                      ) +
                    "</th>" +

                    roomCells +

                  "</tr>"
                );
              }
            )
            .join("");

        setText(
          '[data-scheduler-stat="appointments"]',
          appointments.length
        );

        setText(
          '[data-scheduler-stat="available"]',
          Math.max(
            0,
            slots.length *
              schedulerRooms.length -
              occupiedCells
          )
        );

        setText(
          '[data-scheduler-stat="rooms"]',
          schedulerRooms.length
        );

        setText(
          '[data-scheduler-stat="cancelled"]',
          appointments.filter(
            isCancelled
          ).length
        );
      }

      /* =========================================================
       APPOINTMENT REPORT QUICK DATE RANGE
    ========================================================= */
    function reportRange(filter) {
      var today = String(state.today || "");

      function parseLocalDate(value) {
        var parts = String(value).split("-");

        return new Date(
          Number(parts[0]),
          Number(parts[1]) - 1,
          Number(parts[2])
        );
      }

      function localISO(date) {
        return (
          date.getFullYear() +
          "-" +
          String(date.getMonth() + 1).padStart(2, "0") +
          "-" +
          String(date.getDate()).padStart(2, "0")
        );
      }

      function addLocalDays(value, days) {
        var date = parseLocalDate(value);

        date.setDate(
          date.getDate() + Number(days || 0)
        );

        return localISO(date);
      }

      function weekStart(value) {
        var date = parseLocalDate(value);
        var day = date.getDay();

        var difference =
          day === 0
            ? -6
            : 1 - day;

        date.setDate(
          date.getDate() + difference
        );

        return localISO(date);
      }

      if (filter === "all") {
        return null;
      }

      if (filter === "today") {
        return {
          from: today,
          to: today
        };
      }

      if (filter === "yesterday") {
        var yesterday =
          addLocalDays(today, -1);

        return {
          from: yesterday,
          to: yesterday
        };
      }

      if (filter === "tomorrow") {
        var tomorrow =
          addLocalDays(today, 1);

        return {
          from: tomorrow,
          to: tomorrow
        };
      }

      if (filter === "thisweek") {
        var thisWeekStart =
          weekStart(today);

        return {
          from: thisWeekStart,
          to: addLocalDays(
            thisWeekStart,
            6
          )
        };
      }

      if (filter === "nextweek") {
        var nextWeekStart =
          addLocalDays(
            weekStart(today),
            7
          );

        return {
          from: nextWeekStart,
          to: addLocalDays(
            nextWeekStart,
            6
          )
        };
      }

      if (filter === "lastmonth") {
        return getBusinessMonthRange(
          today,
          -1
        );
      }

      if (filter === "thismonth") {
        return getBusinessMonthRange(
          today,
          0
        );
      }

      if (filter === "nextmonth") {
        return getBusinessMonthRange(
          today,
          1
        );
      }

      return null;
    }

      function validateReportDateRange(showMessage) {
        var fromInput =
          qs('[data-role="report-from-date"]');

        var toInput =
          qs('[data-role="report-to-date"]');

        var errorBox =
          qs('[data-role="report-date-error"]');

        var fromDate =
          fromInput
            ? text(fromInput.value).trim()
            : "";

        var toDate =
          toInput
            ? text(toInput.value).trim()
            : "";

        var valid =
          !(
            fromDate &&
            toDate &&
            fromDate > toDate
          );

        if (fromInput) {
          fromInput.classList.toggle(
            "is-invalid",
            !valid
          );
        }

        if (toInput) {
          toInput.classList.toggle(
            "is-invalid",
            !valid
          );
        }

        if (errorBox) {
          errorBox.textContent =
            valid
              ? ""
              : "From Date cannot be after To Date.";
        }

        if (
          !valid &&
          showMessage
        ) {
          showAlert(
            "From Date cannot be after To Date.",
            "orange"
          );
        }

        return valid;
      }

      function selectedReportRows() {
        var searchInput =
          qs('[data-role="report-search"]');

        var statusInput =
          qs('[data-role="report-status"]');

        var branchInput =
          qs('[data-role="report-branch"]');

        var searchValue =
          searchInput
            ? text(searchInput.value)
                .trim()
                .toLowerCase()
            : "";

        var statusValue =
          statusInput
            ? text(statusInput.value)
                .trim()
                .toLowerCase()
            : "all";

        var branchValue =
          branchInput
            ? branchInput.value || "all"
            : state.branch;

        return state.appointments
          .filter(
            function (row) {
              var rowStatus =
                appointmentStatus(row)
                  .toLowerCase();

              var searchableText =
                [
                  row.patient,
                  row.patient_name,
                  row.mobile,
                  row.concern,
                  row.therapy_type,
                  row.service_room,
                  row.practitioner,
                  row.practitioner_name,
                  row.branch,
                  row.status
                ]
                  .filter(Boolean)
                  .join(" ")
                  .toLowerCase();

              if (
                searchValue &&
                searchableText.indexOf(
                  searchValue
                ) === -1
              ) {
                return false;
              }

              if (
                statusValue &&
                statusValue !== "all" &&
                rowStatus !== statusValue
              ) {
                return false;
              }

              return sameBranch(
                row.branch,
                branchValue
              );
            }
          )
          .sort(
            function (a, b) {
              return (
                text(a.appointment_date) +
                " " +
                text(a.appointment_time)
              ).localeCompare(
                text(b.appointment_date) +
                " " +
                text(b.appointment_time)
              );
            }
          );
      }

      function getShortRoomCode(roomValue) {
        var room =
          text(roomValue)
            .trim()
            .toLowerCase();

        if (!room) {
          return "-";
        }

        var numberMatch =
          room.match(
            /(?:no\.?\s*|room\s*)(\d+)/i
          );

        var roomNumber =
          numberMatch
            ? numberMatch[1]
            : "1";

        if (room.indexOf("slimming") !== -1) {
          return "SL" + roomNumber;
        }

        if (room.indexOf("skin") !== -1) {
          return "SK" + roomNumber;
        }

        if (room.indexOf("hair") !== -1) {
          return "H" + roomNumber;
        }

        if (room.indexOf("laser") !== -1) {
          return "L" + roomNumber;
        }

        if (
          room.indexOf("cryo") !== -1 ||
          room.indexOf("zimmer") !== -1
        ) {
          return "CZ";
        }

        return text(roomValue)
          .split("-")[0]
          .trim();
      }

      var appointmentUserFullNameCache =
        new Map();

      function cacheAppointmentUserFullName(
        userId,
        fullName
      ) {
        var user = text(userId).trim();
        var name = text(fullName).trim();

        if (!user || !name) {
          return;
        }

        appointmentUserFullNameCache.set(
          user,
          name
        );
      }

      function getCachedAppointmentUserFullName(
        userId
      ) {
        var user = text(userId).trim();

        if (!user) {
          return "";
        }

        if (
          appointmentUserFullNameCache.has(user)
        ) {
          return text(
            appointmentUserFullNameCache.get(user)
          ).trim();
        }

        /* Website pages may still expose the current user's full name. */
        try {
          if (
            window.frappe &&
            frappe.session &&
            text(frappe.session.user).trim() === user
          ) {
            var sessionFullName =
              text(
                frappe.session.user_fullname ||
                frappe.session.full_name ||
                ""
              ).trim();

            if (sessionFullName) {
              cacheAppointmentUserFullName(
                user,
                sessionFullName
              );
              return sessionFullName;
            }
          }
        } catch (sessionNameError) {

        }

        /* Use Frappe's already-loaded user info when available. */
        try {
          if (
            window.frappe &&
            typeof frappe.user_info === "function"
          ) {
            var info = frappe.user_info(user);
            var bootFullName =
              info
                ? text(
                    info.fullname ||
                    info.full_name ||
                    ""
                  ).trim()
                : "";

            if (bootFullName) {
              cacheAppointmentUserFullName(
                user,
                bootFullName
              );
              return bootFullName;
            }
          }
        } catch (userInfoError) {

        }

        return "";
      }

      async function enrichAppointmentGivenByNames(
        rows
      ) {
        var owners = Array.from(
          new Set(
            (Array.isArray(rows) ? rows : [])
              .filter(function (row) {
                return !(
                  row.practitioner_name ||
                  row.practitioner
                );
              })
              .map(function (row) {
                return text(row.owner).trim();
              })
              .filter(Boolean)
          )
        );

        if (!owners.length) {
          return;
        }

        var missingOwners = owners.filter(
          function (owner) {
            return !getCachedAppointmentUserFullName(
              owner
            );
          }
        );

        if (!missingOwners.length) {
          return;
        }

        try {
          var users = await callFrappe(
            "frappe.client.get_list",
            {
              doctype: "User",
              fields: [
                "name",
                "full_name",
                "first_name",
                "last_name"
              ],
              filters: [
                [
                  "name",
                  "in",
                  missingOwners
                ]
              ],
              limit_start: 0,
              limit_page_length:
                Math.max(
                  20,
                  missingOwners.length
                )
            }
          );

          (Array.isArray(users) ? users : [])
            .forEach(function (user) {
              var fullName =
                text(user.full_name).trim() ||
                [
                  text(user.first_name).trim(),
                  text(user.last_name).trim()
                ]
                  .filter(Boolean)
                  .join(" ")
                  .trim();

              cacheAppointmentUserFullName(
                user.name,
                fullName
              );
            });
        } catch (userNameLoadError) {
          /*
           * User read permission can vary by role. Never break the
           * Appointment Report just because a display-name lookup failed.
           * frappe.user_info / current-session name / email remain fallbacks.
           */
          window.__lifeOpsV4Debug && void 0;
        }
      }

      function displayGivenBy(row) {
        var practitioner =
          row.practitioner_name ||
          row.practitioner;

        if (practitioner) {
          return practitioner;
        }

        var ownerFullName =
          getCachedAppointmentUserFullName(
            row.owner
          );

        if (ownerFullName) {
          return ownerFullName;
        }

        return row.owner || "-";
      }

      function historyAppointmentKey(row) {
      return (
        text(
          row.appointment_date
        ).substring(
          0,
          10
        ) +
        " " +
        (
          normalizeTime24(
            row.appointment_time
          ) ||
          "00:00"
        )
      );
    }

    function historyMainStatus(row) {
      return text(
        row && row.status
      )
        .trim()
        .toLowerCase();
    }

    function historyCallbackStatus(row) {
      return text(
        row && row.call_back_status
      )
        .trim()
        .toLowerCase();
    }

    /*
     * Cancel history:
     * Main Status = Cancelled / No Show
     * OR Confirmation Status = Cancel.
     */
    function isHistoryCancelled(row) {
      var mainStatus =
        historyMainStatus(row);

      var callbackStatus =
        historyCallbackStatus(row);

      return (
        mainStatus === "cancel" ||
        mainStatus === "cancelled" ||
        mainStatus === "no show" ||
        mainStatus.indexOf("reject") !== -1 ||
        callbackStatus === "cancel" ||
        callbackStatus === "cancelled" ||
        callbackStatus === "no show" ||
        callbackStatus.indexOf("reject") !== -1
      );
    }

    /*
     * In this Patient Appointment workflow,
     * main status = Closed means the client visited.
     */
    function isHistoryClosed(row) {
      return (
        historyMainStatus(row) ===
          "closed" ||
        historyCallbackStatus(row) ===
          "closed"
      );
    }

    /*
     * Re-Scheduled normally comes from
     * Confirmation Status (call_back_status).
     */
    function isHistoryRescheduled(row) {
      var mainStatus =
        historyMainStatus(row);

      var callbackStatus =
        historyCallbackStatus(row);

      return (
        callbackStatus === "re-scheduled" ||
        callbackStatus === "rescheduled" ||
        callbackStatus === "re scheduled" ||
        mainStatus === "re-scheduled" ||
        mainStatus === "rescheduled" ||
        mainStatus === "re scheduled"
      );
    }

    function isHistoryReconfirm(row) {
      var callbackStatus =
        historyCallbackStatus(row);

      return (
        callbackStatus === "re-confirm" ||
        callbackStatus === "reconfirm" ||
        callbackStatus === "re confirm"
      );
    }

    function isHistoryScheduled(row) {
      return (
        historyCallbackStatus(row) ===
        "scheduled"
      );
    }

    function isHistoryNotAnswering(row) {
      var callbackStatus =
        historyCallbackStatus(row);

      return (
        callbackStatus === "not answering" ||
        callbackStatus === "not-answering" ||
        callbackStatus === "not_answering"
      );
    }

    async function loadAppointmentHistoryForRows(
      currentRows
    ) {
      var rows =
        Array.isArray(
          currentRows
        )
          ? currentRows
          : [];

      var patientNames =
        uniqueSortedValues(
          rows
            .map(
              function (row) {
                return row.patient;
              }
            )
            .filter(Boolean)
        );

      if (!patientNames.length) {
        return;
      }

      var maximumDate =
        rows
          .map(
            function (row) {
              return text(
                row.appointment_date
              ).substring(
                0,
                10
              );
            }
          )
          .filter(Boolean)
          .sort()
          .pop() ||
        state.today;

      var patientsToLoad =
        patientNames.filter(
          function (patient) {
            var cached =
              state.appointmentHistoryCache[
                patient
              ];

            return (
              !cached ||
              !cached.upto ||
              cached.upto <
                maximumDate
            );
          }
        );

      if (!patientsToLoad.length) {
        return;
      }

      var historyRows =
        await callFrappe(
          "frappe.client.get_list",
          {
            doctype:
              "Patient Appointment",

            fields: [
              "name",
              "patient",
              "appointment_date",
              "appointment_time",
              "branch",
              "status",
              "call_back_status"
            ],

            filters: [
              [
                "Patient Appointment",
                "patient",
                "in",
                patientsToLoad
              ],

              [
                "Patient Appointment",
                "appointment_date",
                "<=",
                maximumDate
              ]
            ],

            order_by:
              "appointment_date asc, appointment_time asc",

            limit_start:
              0,

            limit_page_length:
              5000
          }
        );

      historyRows =
        Array.isArray(
          historyRows
        )
          ? historyRows
          : [];

      var groupedRows = {};

      historyRows.forEach(
        function (row) {
          var patient =
            text(
              row.patient
            ).trim();

          if (!patient) {
            return;
          }

          if (
            !groupedRows[
              patient
            ]
          ) {
            groupedRows[
              patient
            ] = [];
          }

          groupedRows[
            patient
          ].push({
            name:
              row.name ||
              "",

            patient:
              patient,

            appointment_date:
              text(
                row.appointment_date
              ).substring(
                0,
                10
              ),

            appointment_time:
              normalizeTime24(
                row.appointment_time
              ),

            branch:
              row.branch ||
              "",

            status:
              row.status ||
              "",

            call_back_status:
              row.call_back_status ||
              ""
          });
        }
      );

      patientsToLoad.forEach(
        function (patient) {
          state.appointmentHistoryCache[
            patient
          ] = {
            upto:
              maximumDate,

            rows:
              groupedRows[
                patient
              ] ||
              []
          };
        }
      );
    }

    function appointmentHistoryStats(
      currentRow
    ) {
      var patient =
        text(
          currentRow.patient
        ).trim();

      var cached =
        state.appointmentHistoryCache[
          patient
        ];

      var historyRows =
        cached &&
        Array.isArray(
          cached.rows
        )
          ? cached.rows
          : [];

      var currentKey =
        historyAppointmentKey(
          currentRow
        );

      var currentBranch =
        text(
          currentRow.branch
        ).trim();

      var previousRows =
        historyRows
          .filter(
            function (row) {
              if (
                row.name ===
                currentRow.name
              ) {
                return false;
              }

              var historyBranch =
                text(
                  row.branch
                ).trim();

              /*
               * Previous history is calculated
               * within the same branch.
               */
              if (
                currentBranch &&
                historyBranch &&
                currentBranch !==
                  historyBranch
              ) {
                return false;
              }

              return (
                historyAppointmentKey(
                  row
                ) <
                currentKey
              );
            }
          )
          .sort(
            function (a, b) {
              return historyAppointmentKey(
                a
              ).localeCompare(
                historyAppointmentKey(
                  b
                )
              );
            }
          );

      var latestPrevious =
        previousRows.length
          ? previousRows[
              previousRows.length -
              1
            ]
          : null;

      /*
       * Prev Date and Prev remain previous-only.
       * Cancel, Closed and Re-Scheduled include the
       * current appointment so the row reflects its
       * latest status immediately.
       */
      var statusRows =
        previousRows.concat([
          currentRow
        ]);

      return {
      previousDate:
        latestPrevious
          ? formatDateSlash(
              latestPrevious
                .appointment_date
            )
          : "-",

      previousCount:
        previousRows.length,

      cancelledCount:
        statusRows.filter(
          isHistoryCancelled
        ).length,

      closedCount:
        statusRows.filter(
          isHistoryClosed
        ).length,

      rescheduledCount:
        statusRows.filter(
          isHistoryRescheduled
        ).length,

      reconfirmCount:
        statusRows.filter(
          isHistoryReconfirm
        ).length,

      scheduledCount:
        statusRows.filter(
          isHistoryScheduled
        ).length,

      notAnsweringCount:
        statusRows.filter(
          isHistoryNotAnswering
        ).length
    };
    }

