        state.reportPageSize ||
        25;

      var startIndex =
        (
          state.reportPage -
          1
        ) *
        pageSize;

      var endIndex =
        startIndex +
        visibleRows.length;

      var totalPages = state.reportTotalKnown
        ? Math.max(
            1,
            Math.ceil(
              Math.max(0, Number(state.reportTotal || 0)) /
              pageSize
            )
          )
        : Math.max(
            1,
            state.reportPage +
              (state.reportHasMore ? 1 : 0)
          );

      if (count) {
        count.textContent = state.reportTotalKnown
          ? String(Math.max(0, Number(state.reportTotal || 0)))
          : String(endIndex) + (state.reportHasMore ? "+" : "");
