          pageInfo.textContent =
            "Showing " +
            (startIndex + 1) +
            "–" +
            endIndex +
            (state.reportHasMore ? "+" : "") +
            " clients";
        }
      }

      if (pageNumber) {
        pageNumber.textContent = state.reportTotalKnown
          ? (
              "Page " +
              state.reportPage +
              " of " +
              totalPages
            )
          : (
              "Page " +
              state.reportPage
            );
      }

      if (previousButton) {
        previousButton.disabled =
          state.reportPage <=
          1;
      }

      if (nextButton) {
        nextButton.disabled = state.reportTotalKnown
          ? (
              state.reportPage >= totalPages ||
              visibleRows.length === 0
