      function downloadCsv(
        fileName,
        rows
      ) {
        var blob = new Blob(
          [
            "\uFEFF" +
            rows.join("\r\n")
          ],
          {
            type:
              "text/csv;charset=utf-8;"
          }
        );

        var url =
          URL.createObjectURL(blob);

        var link =
          document.createElement("a");

        link.href = url;
        link.download = fileName;

        document.body.appendChild(link);

        link.click();

        document.body.removeChild(link);

        URL.revokeObjectURL(url);
      }

      async function loadAllAppointmentReportRowsForExport() {
        var query = await getAppointmentReportServerQuery();
        var rows = [];
        var limitStart = 0;
        var batchSize = 500;
        var maximumRows = 5000;

        while (limitStart < maximumRows) {
          var args = {
            doctype: "Patient Appointment",
            fields: query.fields,
            filters: query.filters,
            order_by: "appointment_date asc, appointment_time asc, creation asc",
            limit_start: limitStart,
            limit_page_length: Math.min(batchSize, maximumRows - limitStart)
          };

          if (query.orFilters.length) {
            args.or_filters = query.orFilters;
          }

          var pageRows = await callFrappe(
            "frappe.client.get_list",
            args
          );

          pageRows = Array.isArray(pageRows) ? pageRows : [];

          if (!pageRows.length) {
            break;
          }

          pageRows.forEach(function (row) {
            rows.push(normalizeAppointment(row));
          });

          limitStart += pageRows.length;

          if (pageRows.length < batchSize) {
            break;
          }
        }

        return rows;
      }

