          csvRows
        );
      }

        function getBookingField(fieldName) {
        return qs(
          '[data-book-field="' +
            fieldName +
          '"]'
        );
      }

      /*
       * Appointment dates must never be in the past.
       * This protects both the normal Book Appointment popup
       * and the Next Appointment popup reused by Session Entry.
       */
      function enforceBookingDateMinimum() {
        var dateField =
          getBookingField(
            "appointment_date"
          );

        if (!dateField) {
          return;
        }

        var today =
          getTodayISO();

        dateField.setAttribute(
          "min",
          today
        );

        /*
         * If an old value came from Scheduler/context,
         * automatically move it to today.
         */
        if (
          dateField.value &&
          dateField.value < today
        ) {
          dateField.value =
            today;
        }

        /*
         * Bind once. This also protects against typing/pasting
         * a past date instead of using the browser date picker.
         */
        if (
          !dateField.__lifeNoPastDateBound
        ) {
          dateField.__lifeNoPastDateBound =
            true;

          dateField.addEventListener(
            "change",
            function () {
              var currentToday =
                getTodayISO();

              dateField.setAttribute(
                "min",
                currentToday
              );

              if (
                dateField.value &&
                dateField.value <
                  currentToday
              ) {
                dateField.value =
                  currentToday;

                showAlert(
                  "Past appointment dates are not allowed. Please select today or a future date.",
                  "orange"
                );
              }
            }
          );
        }
      }

      function setBookingField(
        fieldName,
        value
      ) {
        var field =
          getBookingField(fieldName);

        if (field) {
          field.value =
            value == null
              ? ""
              : String(value);
        }
      }

      function normalizeMobileNumber(value) {
        var mobile =
          text(value).replace(/\D/g, "");

        if (
          mobile.length === 12 &&
          mobile.substring(0, 2) === "91"
        ) {
          mobile = mobile.substring(2);
        }

        if (mobile.length > 10) {
          mobile =
            mobile.substring(
              mobile.length - 10
            );
        }

        return mobile;
      }

      function clearPatientResults() {
        var results =
          qs('[data-role="patient-results"]');

        if (results) {
          results.innerHTML = "";

          results.classList.remove(
            "is-open"
          );
        }
      }

      function showPatientResults(html) {
        var results =
          qs('[data-role="patient-results"]');

        if (results) {
          results.innerHTML = html;

          results.classList.add(
            "is-open"
          );
        }
      }

      function populateBookingTimes(selectedTime) {
        var select =
          getBookingField(
            "appointment_time"
          );

        if (!select) {
          return;
        }

        var options = [
          '<option value="">Select time</option>'
        ];

        for (
          var minutes = 7 * 60;
          minutes <= 20 * 60;
          minutes += 30
        ) {
          var hour =
            Math.floor(minutes / 60);

          var minute =
            minutes % 60;

          var value =
            String(hour).padStart(2, "0") +
            ":" +
            String(minute).padStart(2, "0");

          options.push(
            '<option value="' +
              value +
            '">' +
              escapeHtml(
                displayHour(value)
              ) +
            "</option>"
          );
        }

        select.innerHTML =
          options.join("");

        select.value =
          normalizeTime24(
            selectedTime
          );
      }

      function populateBookingBranches(selectedBranch) {
        var select =
          getBookingField("branch");

        if (!select) {
          return;
        }

        var branches =
          collectBranches();

        var branch =
          text(selectedBranch).trim();

        if (
          branch &&
          branches.indexOf(branch) === -1
        ) {
          branches.push(branch);

          branches.sort(
            function (a, b) {
              return a.localeCompare(b);
            }
          );
        }

        select.innerHTML =
          '<option value="">Select branch</option>' +

          branches
            .map(
              function (branchName) {
                return (
                  '<option value="' +
                    escapeHtml(branchName) +
                  '">' +
                    escapeHtml(
                      branchLabel(branchName)
                    ) +
                  "</option>"
                );
              }
            )
            .join("");

        select.value =
          branch || "";
      }

      function serviceUnitMatchesBranch(
        serviceUnit,
        branch
      ) {
        if (
          !branch ||
          isAllBranch(branch)
        ) {
          return true;
        }

        return (
          text(serviceUnit)
            .toLowerCase()
            .indexOf(
              text(branch).toLowerCase()
            ) !== -1
        );
      }

      function populateBookingRooms(
        branch,
        selectedRoom
      ) {
        var select =
          getBookingField(
            "service_room"
          );

        if (!select) {
          return;
        }

        var branchName =
          text(branch).trim();

        if (!branchName) {
