      function normalizeBookingStaffBranch(value) {
        return text(value)
          .trim()
          .toLowerCase()
          .replace(/\s*-\s*lsacpl\s*$/i, "")
          .replace(/^[a-z0-9]{1,6}\s*[—–-]\s*/i, "")
          .replace(/\s+/g, " ")
          .trim();
      }

      function bookingBranchListMatches(
        value,
        branch
      ) {
        var branchKey =
          normalizeBookingStaffBranch(
            branch
          );

        if (!branchKey || !value) {
          return false;
        }

        var raw = text(value);

        var parts = raw
          .split(/[\n\r,;|]+/)
          .map(function (item) {
            return normalizeBookingStaffBranch(
              item
            );
          })
          .filter(Boolean);

        if (
          parts.some(function (item) {
            return item === branchKey;
          })
        ) {
          return true;
        }

        return (
          normalizeBookingStaffBranch(raw) ===
          branchKey
        );
      }

      function practitionerMatchesBranch(
        practitioner,
        branch
      ) {
        /*
         * Appointment staff must be STRICTLY scoped to the selected
         * client's branch. Do not show all practitioners when Branch is
         * blank/All Branches and do not include a practitioner only because
         * "Available All Branches" is enabled.
         */
        if (
          !branch ||
          isAllBranch(branch)
        ) {
          return false;
        }

        var selectedBranchKey =
          normalizeBookingStaffBranch(
            branch
          );

        if (!selectedBranchKey) {
          return false;
        }

        /*
         * 1. Main Healthcare Practitioner.branch
         */
        if (
          normalizeBookingStaffBranch(
            practitioner.branch
          ) === selectedBranchKey
        ) {
          return true;
        }

        /*
         * 2. Branches mirrored from Healthcare Practitioner child table
         *    into custom_branch_list_text / additional_branches.
         */
        return bookingBranchListMatches(
          practitioner.additional_branches,
          branch
        );
      }

      async function loadBranchStaff(
        branch,
        selectedPractitioner
      ) {
        /*
         * Once a client is selected, their branch is the authoritative
         * staff scope for this appointment.
         */
        branch =
          text(
            state.bookingClientBranch ||
            branch ||
            ""
          ).trim();

        var select =
          getBookingField(
            "practitioner"
          );

        if (!select) {
          return;
        }

        var selected =
          text(selectedPractitioner).trim();

        if (!branch) {
          state.branchStaff = [];

          select.innerHTML =
            '<option value="">Select branch first</option>';

          select.disabled = true;

          return;
        }

        if (!state.bookingMastersLoaded) {
          await loadBookingMasterOptions();
        }

        state.branchStaff =
          state.practitioners
            .filter(
              function (practitioner) {
                return practitionerMatchesBranch(
                  practitioner,
                  branch
                );
              }
            )
            .sort(
              function (a, b) {
                return text(
                  a.practitioner_name ||
                  a.name
                ).localeCompare(
                  text(
                    b.practitioner_name ||
                    b.name
                  )
                );
              }
            );

        select.innerHTML =
          '<option value="">Select branch staff</option>' +

          state.branchStaff
            .map(
              function (practitioner) {
                return (
                  '<option value="' +
                    escapeHtml(
                      practitioner.name
                    ) +
                  '">' +
                    escapeHtml(
                      practitioner.practitioner_name ||
                      practitioner.name
                    ) +
                  "</option>"
                );
              }
            )
            .join("");

        select.disabled = false;
        select.value = selected || "";
      }

      function notifyBookingSelectUpdated(fieldName) {
        var select = getBookingField(fieldName);
        if (!select) return;

        /*
         * IMPORTANT: this function is only for repainting the visible
         * searchable appointment field after programmatic option/value changes.
         * Do NOT dispatch a native change event here. The page-level change
         * handler calls applySelectedTherapyPlan()/applySelectedConcern(), and
         * those functions call this sync helper again. Dispatching change from
         * here therefore creates an endless change -> apply -> sync -> change
         * loop and eventually "Maximum call stack size exceeded".
         *
         * Real user choices still dispatch change from createSearchField().
         */
        if (
          typeof select.__lifeOpsSyncBookingSearch === "function"
        ) {
          select.__lifeOpsSyncBookingSearch();
        }
      }

      function getTherapyTypeOptionsFromPlan(doc) {
        var rows = [];
        var seen = Object.create(null);

        function numberFrom(row, names) {
          for (var i = 0; i < names.length; i += 1) {
            var raw = row && row[names[i]];
            if (raw === undefined || raw === null || raw === "") {
              continue;
            }
            var value = Number(raw);
            if (Number.isFinite(value)) return value;
          }
          return 0;
        }

        function addOption(source, fallbackCategory) {
          if (!source || typeof source !== "object") return;

          var therapyType = text(
            pickValue(source, [
              "therapy_type",
              "therapy_type1",
              "therapy",
              "therapy_name",
              "service",
              "service_name",
              "procedure",
              "procedure_template",
              "treatment",
              "treatment_name",
              "item",
              "item_code"
            ])
          ).trim();

          if (!therapyType) return;

          var serviceUnit = text(
            pickValue(source, [
              "service_unit",
              "healthcare_service_unit",
              "category",
              "medical_department",
              "department"
            ]) || fallbackCategory || ""
          ).trim();

          var total = numberFrom(source, [
            "no_of_sessions",
            "number_of_sessions",
            "total_sessions",
            "sessions",
            "session_qty",
            "qty",
            "quantity",
            "custom_total_sessions"
          ]);

          var completed = numberFrom(source, [
            "sessions_completed",
            "completed_sessions",
            "total_sessions_completed",
            "custom_sessions_complted",
            "custom_sessions_completed",
            "used_sessions",
            "completed"
          ]);

          var pendingValue = numberFrom(source, [
            "pending_sessions",
            "balance_sessions",
            "remaining_sessions",
            "custom_balance_sessions"
          ]);

          var pending = pendingValue > 0
            ? pendingValue
            : (total > 0 ? Math.max(total - completed, 0) : 0);

          /* Completed detail rows are not valid for a fresh appointment. */
          if (total > 0 && pending <= 0) return;

          var key = [
            therapyType.toLowerCase(),
            serviceUnit.toLowerCase()
          ].join("|||");

          if (seen[key]) return;
          seen[key] = true;

          rows.push({
            therapy_type: therapyType,
            service_unit: serviceUnit,
            total_sessions: total,
            completed_sessions: completed,
            pending_sessions: pending
          });
        }

        var planCategory = text(
          pickValue(doc, [
            "service_unit",
            "category",
            "healthcare_service_unit",
            "medical_department"
          ])
        ).trim();

        /*
         * LIFE Therapy Plan stores the actual therapies in
         * therapy_plan_details. Read this child table explicitly first. This
         * is also permission-safe because frappe.client.get on the parent
         * returns its child rows to branch users who can open the plan.
         */
        var details = Array.isArray(doc && doc.therapy_plan_details)
          ? doc.therapy_plan_details
          : [];

        details.forEach(function (row) {
          addOption(row, planCategory);
        });

        /* Compatibility with older/custom Therapy Plan child table names. */
        Object.keys(doc || {}).forEach(function (key) {
          if (key === "therapy_plan_details") return;
          var value = doc[key];
          if (!Array.isArray(value)) return;

          value.forEach(function (row) {
            addOption(row, planCategory);
          });
        });

        /* Fallback for a plan that stores one Therapy Type on the parent. */
        addOption(doc, planCategory);

        return rows;
      }

      function getTherapyTypeNamesFromPlan(doc) {
        return getTherapyTypeOptionsFromPlan(doc).map(function (row) {
          return row.therapy_type;
        });
      }

      function therapyPlanOptionLabel(plan) {
        var parts = [];

        if (plan.name) {
          parts.push(plan.name);
        }

        if (plan.category) {
          parts.push(plan.category);
        }

        if (Array.isArray(plan.therapy_type_options) && plan.therapy_type_options.length) {
          var serviceNames = plan.therapy_type_options
            .map(function (row) {
              return row.therapy_type;
            })
            .filter(Boolean);

          if (serviceNames.length) {
            var preview = serviceNames.slice(0, 2).join(", ");
            if (serviceNames.length > 2) {
              preview += " +" + (serviceNames.length - 2);
            }
            parts.push(preview);
          }
        }

        return parts.join(" — ") || "Therapy Plan";
      }

      function formatConcernOptionLabel(row) {
        var label = text(row.therapy_type).trim() || "Therapy Type";
        var details = [];

        if (row.service_unit) {
          details.push(row.service_unit);
        }

        var total = Number(row.total_sessions || 0);
        var completed = Number(row.completed_sessions || 0);
        var pending = Number(row.pending_sessions || 0);

        if (total > 0) {
          details.push(
            "Pending " + pending +
            " | Done " + completed + "/" + total
          );
        }

        return details.length
          ? label + " — " + details.join(" — ")
          : label;
      }

      function populateConcernOptions(plan, selectedConcern) {
        var concernField = getBookingField("concern");
        if (!concernField) return;

        var options =
          plan && Array.isArray(plan.therapy_type_options)
            ? plan.therapy_type_options
            : [];

        if (!options.length) {
          concernField.innerHTML =
            '<option value="">No pending Therapy Type / Concern found</option>';
          concernField.disabled = true;
          concernField.value = "";
          notifyBookingSelectUpdated("concern");
          return;
        }

        concernField.innerHTML =
          '<option value="">Select Therapy Type / Concern</option>' +
          options.map(function (row) {
            return (
              '<option value="' +
              escapeHtml(row.therapy_type) +
              '" data-service-unit="' +
              escapeHtml(row.service_unit || plan.category || "") +
              '">' +
              escapeHtml(formatConcernOptionLabel(row)) +
              "</option>"
            );
          }).join("");

        concernField.disabled = false;

        var requested = text(selectedConcern).trim();
        var exists = options.some(function (row) {
          return text(row.therapy_type).trim() === requested;
        });

        if (exists) {
          concernField.value = requested;
        } else if (options.length === 1) {
          concernField.value = options[0].therapy_type;
        } else {
          concernField.value = "";
        }

        applySelectedConcern(concernField.value);
        notifyBookingSelectUpdated("concern");
      }

      function applySelectedConcern(concernName) {
        var planSelect = getBookingField("therapy_plan");
        var planName = planSelect ? text(planSelect.value).trim() : "";

        var plan = state.selectedPatientPlans.find(function (row) {
          return text(row.name).trim() === planName;
        });

        if (!plan) return;

        var selected = (plan.therapy_type_options || []).find(function (row) {
          return text(row.therapy_type).trim() === text(concernName).trim();
        });

        setBookingField(
          "category",
          selected && selected.service_unit
            ? selected.service_unit
            : plan.category || ""
        );

        setBookingField(
          "service_unit",
          selected && selected.service_unit
            ? selected.service_unit
            : plan.category || ""
        );
      }

      function clearPatientPlanFields() {
        state.selectedPatientPlans = [];

        var planSelect = getBookingField("therapy_plan");
        if (planSelect) {
          planSelect.innerHTML =
            '<option value="">Select client first</option>';
          planSelect.disabled = true;
          planSelect.value = "";
        }

        var concernSelect = getBookingField("concern");
        if (concernSelect) {
          concernSelect.innerHTML =
            '<option value="">Select client first</option>';
          concernSelect.disabled = true;
          concernSelect.value = "";
        }

        notifyBookingSelectUpdated("therapy_plan");
        notifyBookingSelectUpdated("concern");

        setBookingField("category", "");
        setBookingField("service_unit", "");
      }

      function applySelectedTherapyPlan(planName, selectedConcern) {
        var selectedName = text(planName).trim();

        var plan = state.selectedPatientPlans.find(function (row) {
          return text(row.name).trim() === selectedName;
        });

        if (!plan) {
          var concernField = getBookingField("concern");
          if (concernField) {
            concernField.innerHTML =
              '<option value="">Select Therapy Plan first</option>';
            concernField.disabled = true;
            concernField.value = "";
          }

          notifyBookingSelectUpdated("concern");
          setBookingField("category", "");
          setBookingField("service_unit", "");
          return;
        }

        setBookingField("category", plan.category || "");
        setBookingField("service_unit", plan.category || "");

        populateConcernOptions(plan, selectedConcern);
        notifyBookingSelectUpdated("therapy_plan");
      }

      function applyFastBookingPlan(planData) {
        /*
         * This helper belongs to the main Appointment module, not the
         * Session Report module. Do not call clean() here because that helper
         * is scoped inside other modules.
         */
        function bookingClean(value) {
          return text(value).trim();
        }

        if (!planData || !bookingClean(planData.name)) {
          return false;
        }

        var select = getBookingField("therapy_plan");
        if (!select) {
          return false;
        }

        var optionRows =
          Array.isArray(planData.therapy_type_options)
            ? planData.therapy_type_options
            : [];

        if (!optionRows.length) {
          var therapyTypes =
            Array.isArray(planData.therapy_types)
              ? planData.therapy_types.filter(Boolean)
              : [];

          if (
            !therapyTypes.length &&
            bookingClean(planData.therapy_type)
          ) {
            therapyTypes.push(
              bookingClean(planData.therapy_type)
            );
          }

          optionRows = therapyTypes.map(function (name) {
            return {
              therapy_type: name,
              service_unit: bookingClean(
                planData.category ||
                planData.service_unit
              ),
              total_sessions: 0,
              completed_sessions: 0,
              pending_sessions: 0
            };
          });
        }

        var normalizedPlan = {
          name: bookingClean(planData.name),
          branch: bookingClean(planData.branch),
          category: bookingClean(
            planData.category ||
            planData.service_unit
          ),
          status: bookingClean(planData.status),
          therapy_type_options: optionRows,
          therapy_types: optionRows.map(function (row) {
            return row.therapy_type;
          })
        };

        state.selectedPatientPlans = [
          normalizedPlan
        ];

        select.innerHTML =
          '<option value="' +
          escapeHtml(normalizedPlan.name) +
          '">' +
          escapeHtml(
            therapyPlanOptionLabel(
              normalizedPlan
            )
          ) +
          "</option>";

        select.disabled = false;
        select.value =
          normalizedPlan.name;

        applySelectedTherapyPlan(
          normalizedPlan.name,
          bookingClean(
            planData.therapy_type ||
            planData.concern
          )
        );

        notifyBookingSelectUpdated(
          "therapy_plan"
        );
        notifyBookingSelectUpdated(
          "concern"
        );

        return true;
      }

      async function loadPatientTherapyPlans(patientName, selectedPlan, selectedConcern) {
        var select = getBookingField("therapy_plan");
        if (!select) return;

        if (!patientName) {
          clearPatientPlanFields();
          return;
        }

        select.disabled = true;
        select.innerHTML =
          '<option value="">Loading client Therapy Plans...</option>';
        select.value = "";
        notifyBookingSelectUpdated("therapy_plan");

        var concernSelect = getBookingField("concern");
        if (concernSelect) {
          concernSelect.disabled = true;
          concernSelect.innerHTML =
            '<option value="">Loading Therapy Types...</option>';
          concernSelect.value = "";
          notifyBookingSelectUpdated("concern");
        }

        try {
          /*
           * First get only permitted Therapy Plan names. Then fetch each parent
           * document so therapy_plan_details arrives with the plan. This avoids
           * child-DocType permission errors for branch logins.
           */
          var names = await callFrappe(
            "frappe.client.get_list",
            {
              doctype: "Therapy Plan",
              fields: ["name"],
              filters: [
                ["Therapy Plan", "patient", "=", patientName]
              ],
              order_by: "modified desc",
              limit_start: 0,
              limit_page_length: 100
            }
          );

          names = Array.isArray(names) ? names : [];

          var documents = await mapWithConcurrency(
            names,
            6,
            function (row) {
              return callGetDoc("Therapy Plan", row.name)
                .catch(function (error) {
                  void 0;
                  return null;
                });
            }
          );

          state.selectedPatientPlans = documents
            .filter(Boolean)
            .filter(function (doc) {
              var status = text(
                pickValue(doc, ["status", "workflow_state"])
              ).toLowerCase();

              /*
               * Do NOT exclude a Therapy Plan because its due/expiry date has
               * passed. LIFE operations must still allow appointments for any
               * therapy row that has pending/balance sessions. Do not check the
               * custom inactive flag here. Only cancelled documents are excluded.
               */
              return (
                Number(doc.docstatus || 0) !== 2 &&
                status.indexOf("cancel") === -1
              );
            })
            .map(function (doc) {
              var options = getTherapyTypeOptionsFromPlan(doc);

              return {
                name: doc.name || "",
                branch: pickValue(doc, ["branch", "branch_name"]),
                category: pickValue(doc, [
                  "service_unit",
                  "category",
                  "healthcare_service_unit",
                  "medical_department"
                ]),
                status: pickValue(doc, ["status", "workflow_state"]),
                therapy_type_options: options,
                therapy_types: options.map(function (row) {
                  return row.therapy_type;
                })
              };
            })
            .filter(function (plan) {
              /* Appointment must point to an actual therapy row. */
              return plan.name && plan.therapy_type_options.length > 0;
            });

          if (!state.selectedPatientPlans.length) {
            select.innerHTML =
              '<option value="">No Therapy Plan with pending sessions</option>';
            select.disabled = true;
            select.value = "";

            if (concernSelect) {
              concernSelect.innerHTML =
                '<option value="">No pending Therapy Type / Concern</option>';
              concernSelect.disabled = true;
              concernSelect.value = "";
            }

            notifyBookingSelectUpdated("therapy_plan");
            notifyBookingSelectUpdated("concern");
            return;
          }

          select.innerHTML =
            '<option value="">Select Therapy Plan</option>' +
            state.selectedPatientPlans.map(function (plan) {
              return (
                '<option value="' +
                escapeHtml(plan.name) +
                '" title="' +
                escapeHtml(therapyPlanOptionLabel(plan)) +
                '">' +
                escapeHtml(therapyPlanOptionLabel(plan)) +
                "</option>"
              );
            }).join("");

          select.disabled = false;

          var requestedPlan = text(selectedPlan).trim();
          var planExists = state.selectedPatientPlans.some(function (plan) {
            return plan.name === requestedPlan;
          });

          if (planExists) {
            select.value = requestedPlan;
            applySelectedTherapyPlan(requestedPlan, selectedConcern);
          } else if (state.selectedPatientPlans.length === 1) {
            select.value = state.selectedPatientPlans[0].name;
            applySelectedTherapyPlan(
              state.selectedPatientPlans[0].name,
              selectedConcern
            );
          } else {
            select.value = "";
            if (concernSelect) {
              concernSelect.innerHTML =
                '<option value="">Select Therapy Plan first</option>';
              concernSelect.disabled = true;
              concernSelect.value = "";
            }
          }

          notifyBookingSelectUpdated("therapy_plan");
          notifyBookingSelectUpdated("concern");
        } catch (error) {
          void 0;

          state.selectedPatientPlans = [];
          select.innerHTML =
            '<option value="">Unable to load Therapy Plans</option>';
          select.disabled = true;
          select.value = "";

          if (concernSelect) {
            concernSelect.innerHTML =
              '<option value="">Unable to load Therapy Types</option>';
            concernSelect.disabled = true;
            concernSelect.value = "";
          }

          notifyBookingSelectUpdated("therapy_plan");
          notifyBookingSelectUpdated("concern");

          showAlert(
            "The client was selected, but Therapy Plans could not be loaded.",
            "orange"
          );
        }
      }
        function maskAppointmentMobile(value) {
          var digits = String(value || "").replace(/\D/g, "");

          if (!digits) {
            return "-";
          }

          if (digits.length > 10) {
            digits = digits.slice(-10);
          }

          if (digits.length <= 6) {
            return digits;
          }

          return (
            digits.slice(0, 3) +
            "*".repeat(Math.max(1, digits.length - 6)) +
            digits.slice(-3)
          );
        }

        async function searchPatients(searchValue) {
        var query =
          text(searchValue).trim();

        if (query.length < 2) {
          clearPatientResults();
          return;
        }

        showPatientResults(
          '<div class="lo-patient-result-message">' +
            "Searching clients..." +
          "</div>"
        );

        try {
          var rows = await callFrappe(
            "frappe.client.get_list",
            {
              doctype: "Patient",

              fields: [
                "name",
                "patient_name",
                "mobile",
                "sex"
              ],

              or_filters: [
                [
                  "Patient",
                  "name",
                  "like",
                  "%" + query + "%"
                ],
                [
                  "Patient",
                  "patient_name",
                  "like",
                  "%" + query + "%"
                ],
                [
                  "Patient",
                  "mobile",
                  "like",
                  "%" + query + "%"
                ]
              ],

              order_by:
                "modified desc",

              limit_start: 0,

              limit_page_length:
                20
            }
          );

          rows = Array.isArray(rows)
            ? rows
            : [];

          if (!rows.length) {
            showPatientResults(
              '<div class="lo-patient-result-message">' +
                "No matching clients found." +
              "</div>"
            );

            return;
          }

          showPatientResults(
      rows
        .map(
          function (row) {
            var patientName =
              text(
                row.patient_name ||
                row.name ||
                "Unnamed Client"
              ).trim();

            var mobile =
              normalizeMobileNumber(
                row.mobile || ""
              );

            return (
              '<button ' +
                'type="button" ' +
                'class="lo-patient-result" ' +

                'data-action="select-patient" ' +

                'data-patient="' +
                  escapeHtml(
                    row.name
                  ) +
                '" ' +

                'data-patient-name="' +
                  escapeHtml(
                    patientName
                  ) +
                '" ' +

                'data-mobile="' +
                  escapeHtml(
                    mobile
                  ) +
                '" ' +

                'data-gender="' +
                  escapeHtml(
                    row.sex || ""
                  ) +
                '" ' +

                'title="' +
                  escapeHtml(
                    patientName
                  ) +
                '">' +

                '<span class="lo-patient-result-name">' +
                  escapeHtml(
                    patientName
                  ) +
                "</span>" +

                (function () {
                  var privateMobile = lifeOpsPrivateMobile(mobile);
                  return (
                    '<span class="lo-patient-result-mobile lo-mobile-private" ' +
                      'tabindex="0" ' +
                      'data-mobile-masked="' +
                        escapeHtml(privateMobile.masked) +
                      '" ' +
                      'data-mobile-full="' +
                        escapeHtml(privateMobile.full) +
                      '" title="Hover to view full mobile number">' +
                        escapeHtml(privateMobile.masked) +
                    "</span>"
                  );
                })() +

              "</button>"
            );
          }
        )
        .join("")
    );

        } catch (error) {
          void 0;

          showPatientResults(
            '<div class="lo-patient-result-message lo-error-text">' +
              "Unable to search clients." +
            "</div>"
          );
        }
      }

      async function selectPatientForBooking(actionElement) {
        var patientName =
          text(
            actionElement.dataset.patient
          ).trim();

        if (!patientName) {
          return;
        }

        setBookingField(
          "patient",
          patientName
        );

        setBookingField(
          "patient-search",
          actionElement.dataset.patientName ||
          patientName
        );

        setBookingField(
          "mobile",
          normalizeMobileNumber(
            actionElement.dataset.mobile ||
            ""
          )
        );

        setBookingField(
          "gender",
          actionElement.dataset.gender ||
          ""
        );

        clearPatientResults();
        clearPatientPlanFields();

        try {
          var patientDoc =
            actionElement.__lifeOpsPatientDoc ||
            await callGetDoc(
              "Patient",
              patientName
            );

          var patientDisplayName =
            pickValue(
              patientDoc,
              [
                "patient_name",
                "customer_name",
                "full_name",
                "name"
              ]
            );

          var mobile =
            pickValue(
              patientDoc,
              [
                "mobile",
                "mobile_number",
                "custom_mobile_number",
                "custom_client_mobile_no"
              ]
            );

          var gender =
            pickValue(
              patientDoc,
              [
                "sex",
                "gender"
              ]
            );

          var clientBranch =
            pickValue(
              patientDoc,
              [
                "branch_name",
                "branch",
                "custom_branch"
              ]
            );

          setBookingField(
            "patient-search",
            patientDisplayName ||
            actionElement.dataset.patientName ||
            patientName
          );

          setBookingField(
            "mobile",
            normalizeMobileNumber(
              mobile ||
              actionElement.dataset.mobile ||
              ""
            )
          );

          setBookingField(
            "gender",
            gender ||
            actionElement.dataset.gender ||
            ""
          );

          var currentBookingBranch =
            text(
              getBookingField("branch")
                ? getBookingField("branch").value
                : ""
            ).trim();

          var currentBookingRoom =
            text(
              getBookingField("service_room")
                ? getBookingField("service_room").value
                : ""
            ).trim();

          /*
           * Appointment staff/booking must follow the CLIENT'S branch.
           * If the Patient has a branch, it takes priority over Scheduler
           * context or any previously selected branch.
           */
          var effectiveBranch =
            text(
              clientBranch ||
              state.bookingContext.branch ||
              currentBookingBranch ||
              state.loginBranch ||
              state.schedulerBranch ||
              ""
            ).trim();

          var effectiveRoom =
            resolveServiceRoomName(
              state.bookingContext.room ||
              currentBookingRoom,
              effectiveBranch
            );

          state.bookingClientBranch =
            effectiveBranch;

          populateBookingBranches(
            effectiveBranch
          );

          setBookingField(
            "branch",
            effectiveBranch
          );

          populateBookingRooms(
            effectiveBranch,
            effectiveRoom
          );

          var fastPlanApplied =
            applyFastBookingPlan(
              actionElement.__lifeOpsPlanData
            );

          await loadBranchStaff(
            effectiveBranch,
            ""
          );

          if (!fastPlanApplied) {
            await loadPatientTherapyPlans(
              patientName,
              ""
            );
          }

          if (!effectiveBranch) {
            showAlert(
              "No branch is selected for this appointment.",
              "orange"
            );
          }
        } catch (error) {
          void 0;

          /*
           * A Patient detail fetch can fail for a branch user because of field
           * permissions, even though the appointment already has a perfectly
           * valid logged-in branch. Do not show a false "client branch could not
           * be fetched" warning in that case. Fall back to the branch already
           * fixed by the logged-in Employee / scheduler context and continue
           * loading the client's Therapy Plans.
           */
          var fallbackBranch = text(
            (state.bookingContext && state.bookingContext.branch) ||
            (getBookingField("branch") ? getBookingField("branch").value : "") ||
            state.loginBranch ||
            (!isAllBranch(state.branch) ? state.branch : "") ||
            state.schedulerBranch ||
            ""
          ).trim();

          if (fallbackBranch) {
            populateBookingBranches(fallbackBranch);
            setBookingField("branch", fallbackBranch);
            populateBookingRooms(
              fallbackBranch,
              state.bookingContext && state.bookingContext.room
                ? state.bookingContext.room
                : ""
            );

            try {
              await loadBranchStaff(fallbackBranch, "");
            } catch (staffError) {
              void 0;
            }
          }

          await loadPatientTherapyPlans(
            patientName,
            ""
          );

          if (!fallbackBranch) {
            showAlert(
              "Client selected, but no branch is available for appointment booking.",
              "orange"
            );
          }
        }
      }

