      async function openAppointmentModal(options) {
        var settings = options || {};

        state.bookingContext = {
          branch:
            text(
              settings.branch
            ).trim(),

          room:
            text(
              settings.room
            ).trim(),

          date:
            text(
              settings.date
            ).trim(),

          time:
            text(
              settings.time
            ).trim()
        };

        var modal =
          qs('[data-role="appointment-modal"]');

        if (!modal) {
          showError(
            "Appointment booking modal was not found in the HTML."
          );

          return;
        }

        setLoading(
          true,
          "Loading booking options..."
        );

        try {
          await loadBookingMasterOptions();

          resetBookingForm();

          var selectedBranch =
            text(
              settings.branch ||
              (
                state.activeTab === "scheduler"
                  ? state.schedulerBranch
                  : (
                      isAllBranch(state.branch)
                        ? ""
                        : state.branch
                    )
              )
            ).trim();

          populateBookingBranches(
            selectedBranch
          );

          setBookingField(
            "branch",
            selectedBranch
          );

          populateBookingRooms(
            selectedBranch,
            settings.room || ""
          );

          setBookingField(
            "appointment_date",
            settings.date ||
            getTodayISO()
          );

          enforceBookingDateMinimum();

          populateBookingTimes(
            settings.time || ""
          );

          await loadBranchStaff(
            selectedBranch,
            settings.practitioner || ""
          );

          modal.classList.add(
            "is-open"
          );

          modal.setAttribute(
            "aria-hidden",
            "false"
          );

          document.body.classList.add(
            "lo-modal-open"
          );

          window.setTimeout(
            function () {
              var patientSearch =
                getBookingField(
                  "patient-search"
                );

              if (patientSearch) {
                patientSearch.focus();
              }
            },
            50
          );
        } catch (error) {
          void 0;

          showError(
            "Booking options could not be loaded."
          );
        } finally {
          setLoading(false);
        }
      }

      function closeAppointmentModal() {
        var modal =
          qs('[data-role="appointment-modal"]');

        if (!modal) {
          return;
        }

        modal.classList.remove(
          "is-open"
        );

        modal.setAttribute(
          "aria-hidden",
          "true"
        );

        document.body.classList.remove(
          "lo-modal-open"
        );

        closeBookingWarningDialog();

        clearPatientResults();

        root.__lifeOpsAppointmentBookingContext =
          null;
      }

