      root.__lifeOpsAppointmentBridge = {
        openForLiveSession:
          async function (options) {
            var settings =
              options || {};

            root.__lifeOpsAppointmentBookingContext = {
              mode:
                settings.mode || "normal",

              stayOnCurrentTab:
                settings.stayOnCurrentTab === true,

              onCreated:
                typeof settings.onCreated ===
                  "function"
                  ? settings.onCreated
                  : null
            };

            await openAppointmentModal({
              branch:
                settings.branch || "",

              room:
                settings.room || "",

              date:
                settings.date || state.today,

              time:
                settings.time || "",

              practitioner:
                settings.practitioner || ""
            });

            var modal = qs(
              '[data-role="appointment-modal"]'
            );

            if (
              !modal ||
              !modal.classList.contains(
                "is-open"
              )
            ) {
              root.__lifeOpsAppointmentBookingContext =
                null;
              return;
            }

            if (settings.patient) {
              var patientButton =
                document.createElement(
                  "button"
                );

              patientButton.dataset.patient =
                settings.patient;

              patientButton.dataset.patientName =
                settings.patient_name ||
                settings.patient;

              patientButton.dataset.mobile =
                settings.mobile || "";

              patientButton.dataset.gender =
                settings.gender || "";

              patientButton.__lifeOpsPatientDoc =
                settings.patient_doc || null;

              patientButton.__lifeOpsPlanData =
                settings.plan_data || null;

              await selectPatientForBooking(
                patientButton
              );
            }

            if (settings.therapy_plan) {
              setBookingField(
                "therapy_plan",
                settings.therapy_plan
              );

              applySelectedTherapyPlan(
                settings.therapy_plan
              );
            }

            if (settings.therapy_type) {
              setBookingField(
                "concern",
                settings.therapy_type
              );
            }

            notifyBookingSelectUpdated("therapy_plan");
            notifyBookingSelectUpdated("concern");

            if (settings.category) {
              setBookingField(
                "category",
                settings.category
              );
            }

            if (
              settings.service_unit ||
              settings.category
            ) {
              setBookingField(
                "service_unit",
                settings.service_unit ||
                settings.category
              );
            }

            if (settings.date) {
              setBookingField(
                "appointment_date",
                settings.date
              );
            }

            populateBookingTimes(
              settings.time || ""
            );

            var selectedBranch = text(
              getBookingField("branch")
                ? getBookingField("branch").value
                : settings.branch || ""
            ).trim();

            await loadBranchStaff(
              selectedBranch,
              settings.practitioner || ""
            );

            if (settings.practitioner) {
              setBookingField(
                "practitioner",
                settings.practitioner
              );
            }

            var patientSearch =
              getBookingField(
                "patient-search"
              );

            if (patientSearch) {
              patientSearch.readOnly = true;
              patientSearch.setAttribute(
                "data-live-booking-fixed",
                "1"
              );
            }

            var title = qs(
              "#lo-booking-title"
            );

            if (title) {
              title.textContent =
                settings.title ||
                "Add Appointment";
            }
          }
      };

