      function appointmentDetailStatusOptions(
        currentStatus
      ) {
        var statuses = [
          "Scheduled",
          "Re-Confirm",
          "Re-Scheduled",
          "Not Answering",
          "Closed",
          "Cancel"
        ];

        var current =
          text(currentStatus).trim();

        if (
          current &&
          statuses.indexOf(current) === -1
        ) {
          statuses.unshift(current);
        }

        return statuses
          .map(
            function (status) {
              return (
                '<option value="' +
                  escapeHtml(status) +
                '"' +
                (
                  status === current
                    ? " selected"
                    : ""
                ) +
                '>' +
                  escapeHtml(status) +
                '</option>'
              );
            }
          )
          .join("");
      }

      function isAppointmentRescheduleStatus(
        value
      ) {
        var key =
          text(value)
            .trim()
            .toLowerCase()
            .replace(/[\s_-]+/g, "");

        return (
          key === "rescheduled" ||
          key === "reschedule"
        );
      }

      function appointmentDetailTimeInputValue(
        value
      ) {
        var normalized =
          normalizeTime24(value || "");

        return normalized
          ? normalized.substring(0, 5)
          : "";
      }

      function toggleAppointmentRescheduleFields() {
        var statusSelect =
          qs('[data-role="appointment-detail-status"]');

        var showFields =
          statusSelect &&
          isAppointmentRescheduleStatus(
            statusSelect.value
          );

        qsa(
          '[data-role="appointment-reschedule-field"]'
        ).forEach(
          function (field) {
            field.hidden =
              !showFields;
          }
        );

        var updateButton =
          qs('[data-action="update-appointment-status"]');

        if (
          updateButton &&
          !state.detailStatusUpdating
        ) {
          updateButton.textContent =
            showFields
              ? "Create Re-Scheduled Appointment"
              : "Update Status";
        }
      }

