      async function openAppointmentDetailsModal(
        appointmentName
      ) {
        var name =
          text(appointmentName).trim();

        if (!name) {
          return;
        }

        var modal =
          ensureAppointmentDetailModal();

        state.detailAppointmentName =
          name;

        state.detailAppointmentDoc =
          null;

        var content =
          qs('[data-role="appointment-detail-content"]');

        var updateButton =
          qs('[data-action="update-appointment-status"]');

        if (content) {
          content.innerHTML =
            '<div class="lo-appt-detail-loading">Loading appointment details...</div>';
        }

        if (updateButton) {
          updateButton.disabled =
            true;

          updateButton.textContent =
            "Update Status";
        }

        modal.classList.add(
          "is-open"
        );

        modal.setAttribute(
          "aria-hidden",
          "false"
        );

        document.body.classList.add(
          "lo-modal-open"
        );

        try {
          var doc =
            await callGetDoc(
              "Patient Appointment",
              name
            );

          if (!doc || !doc.name) {
            throw new Error(
              "Appointment details were not returned."
            );
          }

          if (
            state.detailAppointmentName !==
            name
          ) {
            return;
          }

          // LIFE_RESCHEDULE_CARD_REDIRECT_V2
          var callbackKey = text(doc.call_back_status || "")
            .toLowerCase().replace(/[-_\s]/g, "");

          if (callbackKey === "rescheduled") {
            var movedRows = await callFrappe(
              "frappe.client.get_list",
              {
                doctype: "Patient Appointment",
                filters: {
                  patient: doc.patient,
                  branch: doc.branch,
                  docstatus: ["<", 2],
                  notes: [
                    "like",
                    "Re-scheduled from " + doc.name + ".%"
                  ]
                },
                fields: [
                  "name",
                  "appointment_date",
                  "appointment_time",
                  "branch"
                ],
                limit_page_length: 2,
                order_by: "creation desc"
              }
            );

            if (state.detailAppointmentName !== name) {
              return;
            }

            if (Array.isArray(movedRows) && movedRows.length === 1) {
              var moved = movedRows[0];
              var targetDate = text(moved.appointment_date)
                .substring(0, 10);

              var dateField = qs('[data-role="scheduler-date"]');
              var branchField = qs('[data-role="scheduler-branch"]');

              if (dateField) {
                dateField.value = targetDate;
              }

              if (moved.branch) {
                state.schedulerBranch = moved.branch;
                if (branchField) {
                  branchField.value = moved.branch;
                }
              }

              closeAppointmentDetails();
              state.currentAppointmentRange = null;
              showTab("scheduler");
              await loadSchedulerSelectedDate();

              showAlert(
                "Opened rescheduled appointment " +
                moved.name + " on " + targetDate +
                " at " + text(moved.appointment_time),
                "green"
              );
              return;
            }

            showAlert(
              movedRows && movedRows.length > 1
                ? "Multiple linked bookings found. Please review the appointment details."
                : "No linked rescheduled booking found. Please review the appointment details.",
              "orange"
            );
          }

          state.detailAppointmentDoc =
            doc;

          renderAppointmentDetail(doc);

          if (updateButton) {
            updateButton.disabled =
              false;
          }

        } catch (error) {
          void 0;

          if (content) {
            content.innerHTML =
              '<div class="lo-appt-detail-loading">Unable to load appointment details.</div>';
          }

          showError(
            "Appointment details could not be loaded."
          );
        }
      }

      async function openAppointmentDetails(
