      async function updateAppointmentStatus() {
        if (
          state.detailStatusUpdating ||
          !state.detailAppointmentName
        ) {
          return;
        }

        var statusSelect =
          qs('[data-role="appointment-detail-status"]');

        var newStatus =
          statusSelect
            ? text(statusSelect.value).trim()
            : "";

        if (!newStatus) {
          showAlert(
            "Select a Booking Status.",
            "orange"
          );
          return;
        }

        var updateButton =
          qs('[data-action="update-appointment-status"]');

        var originalAppointmentName =
          state.detailAppointmentName;

        var sourceDocument =
          state.detailAppointmentDoc ||
          {};

        var isReschedule =
          isAppointmentRescheduleStatus(
            newStatus
          );

        var newAppointmentDate = "";
        var newAppointmentTime = "";

        if (isReschedule) {
          var dateInput =
            qs('[data-role="appointment-reschedule-date"]');

          var timeInput =
            qs('[data-role="appointment-reschedule-time"]');

          newAppointmentDate =
            dateInput
              ? text(dateInput.value).trim()
              : "";

          newAppointmentTime =
            normalizeTime24(
              timeInput
                ? timeInput.value
                : ""
            );

          if (
            !newAppointmentDate ||
            !newAppointmentTime
          ) {
            showAlert(
              "Select the new appointment date and time.",
              "orange"
            );
            return;
          }

          if (
            newAppointmentDate <
            (state.today || "")
          ) {
            showAlert(
              "The new appointment date cannot be in the past.",
              "orange"
            );
            return;
          }

          if (
            /^\d{2}:\d{2}$/.test(
              newAppointmentTime
            )
          ) {
            newAppointmentTime +=
              ":00";
          }

          var oldAppointmentDate =
            text(
              sourceDocument.appointment_date
            ).substring(0, 10);

          var oldAppointmentTime =
            normalizeTime24(
              sourceDocument.appointment_time ||
              ""
            );

          if (
            /^\d{2}:\d{2}$/.test(
              oldAppointmentTime
            )
          ) {
            oldAppointmentTime +=
              ":00";
          }

          if (
            oldAppointmentDate ===
              newAppointmentDate &&
            oldAppointmentTime ===
              newAppointmentTime
          ) {
            showAlert(
              "Change the date or time before creating the re-scheduled appointment.",
              "orange"
            );
            return;
          }
        }

        state.detailStatusUpdating =
          true;

        if (updateButton) {
          updateButton.disabled =
            true;

          updateButton.textContent =
            isReschedule
              ? "Creating..."
              : "Updating...";
        }

        function statusUpdateErrorMessage(
          error
        ) {
          var message = "";
          var serverMessages = "";

          if (error) {
            message =
              text(
                error.message ||
                error.responseText ||
                ""
              ).trim();

            if (
              error.responseJSON &&
              error.responseJSON._server_messages
            ) {
              serverMessages =
                error.responseJSON._server_messages;
            } else if (
              error._server_messages
            ) {
              serverMessages =
                error._server_messages;
            }
          }

          if (serverMessages) {
            try {
              var parsedMessages =
                typeof serverMessages === "string"
                  ? JSON.parse(serverMessages)
                  : serverMessages;

              if (
                Array.isArray(parsedMessages) &&
                parsedMessages.length
              ) {
                var firstMessage =
                  parsedMessages[0];

                try {
                  var parsedFirst =
                    typeof firstMessage === "string"
                      ? JSON.parse(firstMessage)
                      : firstMessage;

                  message =
                    text(
                      parsedFirst &&
                      (
                        parsedFirst.message ||
                        parsedFirst.title
                      )
                    ).trim() ||
                    text(firstMessage).trim();
                } catch (innerError) {
                  message =
                    text(firstMessage).trim();
                }
              }
            } catch (parseError) {
              message =
                text(serverMessages).trim() ||
                message;
            }
          }

          message =
            text(message)
              .replace(/<[^>]+>/g, " ")
              .replace(/\s+/g, " ")
              .trim();

          if (
            message.indexOf(
              "life_ops_update_appointment_status"
            ) !== -1 &&
            (
              message.toLowerCase().indexOf(
                "not found"
              ) !== -1 ||
              message.toLowerCase().indexOf(
                "failed to get method"
              ) !== -1
            )
          ) {
            return (
              "The API Server Script " +
              "life_ops_update_appointment_status " +
              "is missing or disabled."
            );
          }

          return (
            message ||
            "Appointment status could not be updated."
          );
        }

        try {
          /*
           * IMPORTANT:
           * Do not use frappe.client.set_value here.
           * That method calls Patient Appointment doc.save(),
           * which triggers the site's faulty service_room_restrict
           * before_save hook while only changing the callback status.
           *
           * The API Server Script performs the re-schedule transaction:
           *   old appointment -> Re-Scheduled
           *   new appointment -> Scheduled
           * and uses frappe.db.set_value for the old status so the
           * unrelated room hook is not executed.
           */
          var result =
            await callFrappe(
              "life_ops_update_appointment_status",
              {
                appointment_name:
                  originalAppointmentName,

                new_status:
                  newStatus,

                new_appointment_date:
                  newAppointmentDate,

                new_appointment_time:
                  newAppointmentTime
              }
            );

          if (
            !result ||
            result.ok !== true
          ) {
            throw new Error(
              result && result.message
                ? result.message
                : "The server did not confirm the appointment update."
            );
          }

          var confirmedOldStatus =
            text(
              result.old_status ||
              newStatus
            ).trim();

          state.appointments.forEach(
            function (row) {
              if (
                row.name ===
                originalAppointmentName
              ) {
                row.call_back_status =
                  confirmedOldStatus;
              }
            }
          );

          state.appointmentHistoryCache =
            {};
          state.appointmentRangeCache.clear();
          state.schedulerOverviewCache.clear();

          var loadedRange =
            state.currentAppointmentRange
              ? {
                  from:
                    state.currentAppointmentRange.from ||
                    "",

                  to:
                    state.currentAppointmentRange.to ||
                    ""
                }
              : null;

          if (
            loadedRange &&
            loadedRange.from &&
            loadedRange.to
          ) {
            await loadAppointmentRange(
              loadedRange.from,
              loadedRange.to,
              1000
            );

            populateBranchOptions();
          }

          renderActivePage();
          closeAppointmentDetails();

          if (isReschedule) {
            var rescheduledDate = text(
              result.new_appointment_date ||
              result.appointment_date ||
              newAppointmentDate
            ).substring(0, 10);

            var rescheduledDateInput = qs(
              '[data-role="scheduler-date"]'
            );

            if (rescheduledDateInput) {
              rescheduledDateInput.value = rescheduledDate;
            }

            state.currentAppointmentRange = null;
            showTab("scheduler");
            await loadSchedulerSelectedDate();

            showAlert(
              "Old appointment marked Re-Scheduled. New appointment " +
                text(
                  result.new_appointment ||
                  ""
                ) +
                " created as Scheduled for " +
            formatDateSlash(
               result.new_appointment_date ||
               result.appointment_date ||
               newAppointmentDate
            ) +
            " at " +
              displayHour(
              result.new_appointment_time ||
              result.appointment_time ||
              newAppointmentTime
            ) +
              ".",
              "green"
            );

          } else {
            showAlert(
              "Appointment status updated successfully.",
              "green"
            );

          }

          loadAppointmentKpiCounts()
            .then(
              function () {
                renderKPIs();
              }
            )
            .catch(
              function (error) {

              }
            );

        } catch (error) {
          void 0;

          showError(
            statusUpdateErrorMessage(
              error
            )
          );

          if (updateButton) {
            updateButton.disabled =
              false;

            updateButton.textContent =
              isReschedule
                ? "Create Re-Scheduled Appointment"
                : "Update Status";
          }

        } finally {
          state.detailStatusUpdating =
            false;
        }
      }

