          text(
            getBookingField("practitioner")
              ? getBookingField("practitioner").value
              : ""
          ).trim();

        var status =
          text(
            getBookingField("status")
              ? getBookingField("status").value
              : "Scheduled"
          ).trim() ||
          "Scheduled";

        var notes =
          text(
            getBookingField("notes")
              ? getBookingField("notes").value
              : ""
          ).trim();

        var selectedPlan =
          state.selectedPatientPlans.find(
            function (plan) {
              return (
                plan.name ===
                therapyPlan
              );
            }
          );

        if (
          !concern &&
          selectedPlan &&
          selectedPlan.therapy_types &&
          selectedPlan.therapy_types.length
        ) {
          concern =
            selectedPlan.therapy_types[0];
        }

        if (
          !category &&
          selectedPlan
        ) {
          category =
            selectedPlan.category ||
            "";
        }

        if (!serviceUnit) {
          serviceUnit =
            category;
        }

        var missingFields = [];

        if (!patient) {
          missingFields.push(
            "Client"
          );
        }

        if (!branch) {
          missingFields.push(
            "Branch"
          );
        }

        if (!serviceRoom) {
          missingFields.push(
            "Service Room"
          );
        }

        if (!therapyPlan) {
          missingFields.push(
            "Category"
          );
        }

        if (!concern) {
          missingFields.push(
            "Concern"
          );
        }

        if (!appointmentDate) {
          missingFields.push(
            "Date"
          );
        }

        if (!appointmentTime) {
          missingFields.push(
            "Time"
          );
        }

        if (!practitioner) {
          missingFields.push(
            "Therapist / Given By"
          );
        }

        if (missingFields.length) {
          showAlert(
            "Please select: " +
              missingFields.join(", "),
            "orange"
          );

          return;
        }

        /*
         * Final server-submit protection:
         * never allow an appointment to be created for a past date,
         * even if the browser/date input was manually manipulated.
         */
        var todayForBooking =
          getTodayISO();

        if (
          appointmentDate &&
          appointmentDate <
            todayForBooking
        ) {
          var appointmentDateField =
            getBookingField(
              "appointment_date"
            );

          if (appointmentDateField) {
            appointmentDateField.setAttribute(
              "min",
              todayForBooking
            );

            appointmentDateField.value =
              todayForBooking;
          }

          showAlert(
            "Past appointment dates are not allowed. Please select today or a future date.",
            "orange"
          );

          return;
        }

        /*
         * A Service Room is a Link field. Confirm that the
         * exact document name exists before inserting.
         */
        var serviceRoomExists =
          await callFrappe(
            "frappe.client.get_count",
            {
              doctype:
                "Service Room",

              filters: [
                [
                  "Service Room",
                  "name",
                  "=",
                  serviceRoom
                ]
              ]
            }
          );

        if (
          Number(
            serviceRoomExists ||
            0
          ) === 0
        ) {
          showAlert(
            "The selected Service Room is invalid for this branch. Refresh the Scheduler and select the slot again.",
            "orange"
          );

          return;
        }

        /*
         * service_unit is also a Link field. Validate it
         * before insertion so ERPNext cannot return a
         * LinkValidationError after the user clicks Book.
         */
        if (serviceUnit) {
          var serviceUnitExists =
            await callFrappe(
              "frappe.client.get_count",
              {
                doctype:
                  "Healthcare Service Unit",

                filters: [
                  [
                    "Healthcare Service Unit",
                    "name",
                    "=",
                    serviceUnit
                  ]
                ]
              }
            );

          if (
            Number(
              serviceUnitExists ||
              0
            ) === 0
          ) {
            showAlert(
              "The selected Therapy Plan does not contain a valid Healthcare Service Unit. Update the Therapy Plan and try again.",
              "orange"
            );

            return;
          }
        }

        if (
          mobile &&
          !/^[6-9]\d{9}$/.test(
            mobile
          )
        ) {
          showAlert(
            "The selected client has an invalid mobile number.",
            "orange"
          );

          return;
        }

        var appointmentTimeValue =
          appointmentTime;

        if (
          /^\d{2}:\d{2}$/.test(
            appointmentTimeValue
          )
        ) {
          appointmentTimeValue +=
            ":00";
        }

        /*
         * Recheck the selected slot immediately
         * before insertion.
         */
        var duplicateCount =
          await callFrappe(
            "frappe.client.get_count",
            {
              doctype:
                "Patient Appointment",

              filters: [
                [
                  "Patient Appointment",
                  "appointment_date",
                  "=",
                  appointmentDate
                ],
                [
                  "Patient Appointment",
                  "appointment_time",
                  "=",
                  appointmentTimeValue
                ],
                [
                  "Patient Appointment",
                  "branch",
                  "=",
                  branch
                ],
                [
                  "Patient Appointment",
                  "service_room",
                  "=",
                  serviceRoom
                ]
              ]
            }
          );

        if (
          Number(
            duplicateCount ||
            0
          ) > 0
        ) {
          showAlert(
            "This room and time slot is already booked. Refresh the Scheduler and select another slot.",
            "orange"
          );

          return;
        }

        /*
         * Create the normal Patient Appointment document.
         * In your Desk this DocType is titled Client Appointment.
         */
        var appointmentDocument = {
          docstatus:
            0,

          doctype:
            "Patient Appointment",

          naming_series:
            "HLC-APP-.YYYY.-",

          company:
            "Life Slimming And Cosmetic Pvt Ltd",

          appointment_for:
            "Practitioner",

          appointment_type:
            "Session",

          patient:
            patient,

          patient_name:
            patientDisplayName ||
            patient,

          patient_sex:
            gender ||
            "",

          custom_client_mobile_no:
            mobile ||
            "",

          branch:
            branch,

          service_room:
            serviceRoom,

          service_unit:
            serviceUnit ||
            category ||
            "",

          therapy_plan_1:
            therapyPlan,

          therapy_type1:
            concern,

          concern:
            concern,

          appointment_date:
            appointmentDate,

          appointment_time:
            appointmentTimeValue,

          duration:
            30,

          /*
           * call_back_status is the booking status used by
           * the Scheduler. Let the DocType manage its own
           * standard status field.
           */
          call_back_status:
            status ||
            "Scheduled",

          add_video_conferencing:
            0,

          invoiced:
            0,

          appointment_based_on_check_in:
            0,

          reminded:
            0
        };

        if (practitioner) {
          appointmentDocument.practitioner =
            practitioner;
        }

        if (notes) {
          appointmentDocument.notes =
            notes;
        }

        setLoading(
          true,
          "Booking appointment..."
        );

        var submitButton =
          qs(
            '[data-action="submit-appointment"]'
          );

        try {
          if (submitButton) {
            submitButton.disabled =
              true;

            submitButton.textContent =
              "Creating...";
          }

          var createdDocument =
            await callFrappe(
              "frappe.client.insert",
              {
                doc:
                  appointmentDocument
              }
            );

          if (
            !createdDocument ||
            !createdDocument.name
          ) {
            throw new Error(
              "Patient Appointment was not created."
            );
          }

          var specialBookingContext =
            root.__lifeOpsAppointmentBookingContext ||
            null;

          /*
           * The Client Appointment record now exists.
           * Capture the special context before closing because
           * closeAppointmentModal clears it on cancel/close.
           */
          closeAppointmentModal();

          if (
            specialBookingContext &&
            typeof specialBookingContext.onCreated ===
              "function"
          ) {
            try {
              await specialBookingContext.onCreated(
                createdDocument,
                appointmentDocument
              );
            } catch (bridgeError) {
              void 0;

              showError(
                "Appointment " +
                createdDocument.name +
                " was created, but it could not be linked back to New Session Entry."
              );
            }
          }

          state.schedulerBranch =
            branch;

          var schedulerDateInput =
            qs(
              '[data-role="scheduler-date"]'
            );

          if (schedulerDateInput) {
            schedulerDateInput.value =
              appointmentDate;
          }

          var schedulerBranchInput =
            qs(
              '[data-role="scheduler-branch"]'
            );

          if (schedulerBranchInput) {
            schedulerBranchInput.value =
              branch;
          }

          if (
            !specialBookingContext ||
            !specialBookingContext.stayOnCurrentTab
          ) {
            showTab(
              "scheduler"
            );
          }

          showAlert(
            "Appointment created successfully: " +
              createdDocument.name,
            "green"
          );

          /*
           * Refreshing the Scheduler is secondary. A refresh
           * failure must not report the already-created record
           * as a failed booking.
           */
          try {
            state.appointmentRangeCache.clear();
            state.schedulerOverviewCache.clear();

            await Promise.all([
              loadAppointmentRange(
                appointmentDate,
                appointmentDate,
                1000
              ),

              loadAppointmentKpiCounts()
            ]);

            state.reportPage =
              1;

            populateBranchOptions();

            if (schedulerDateInput) {
              schedulerDateInput.value =
                appointmentDate;
            }

            if (schedulerBranchInput) {
              schedulerBranchInput.value =
                branch;
            }

            renderScheduler();

          } catch (refreshError) {

          }

        } catch (error) {
          void 0;

          var serverMessage =
            text(
              error &&
              (
                error.message ||
                error._server_messages ||
                error.responseText
              )
            ).trim();

          showError(
            serverMessage
              ? (
                  "Appointment could not be booked: " +
                  serverMessage
                )
              : "Appointment could not be booked. Check the first red console error."
          );

        } finally {
          if (submitButton) {
            submitButton.disabled =
              false;

            submitButton.textContent =
              "Book Appointment";
          }

          setLoading(false);
        }
      }

        function openFrappeDocument(
        doctype,
        name
      ) {
        if (!doctype || !name) {
          return;
        }

        if (
          window.frappe &&
          frappe.set_route
        ) {
          frappe.set_route(
            "Form",
            doctype,
            name
          );

          return;
        }

        window.open(
          "/app/" +
            encodeURIComponent(
              doctype
                .toLowerCase()
                .replace(/\s+/g, "-")
            ) +
            "/" +
            encodeURIComponent(name),
          "_blank"
        );
      }

      var lastClockText = "";
      var lastClockDateText = "";

      function updateClock() {
        if (document.hidden || !dashboard.isConnected) {
          return;
        }

        var now = new Date();
        var clock = qs('[data-role="clock"]');
        var todayLabel = qs('[data-role="today-label"]');
        var nextClockText = now.toLocaleTimeString(
          "en-IN",
          {
            hour: "2-digit",
            minute: "2-digit",
            second: "2-digit",
            hour12: true
          }
        );
        var nextDateText =
          window.lifeOpsFormatDisplayDate(now);

        if (clock && nextClockText !== lastClockText) {
          clock.textContent = nextClockText;
          lastClockText = nextClockText;
        }

        if (todayLabel && nextDateText !== lastClockDateText) {
          todayLabel.textContent = nextDateText;
          lastClockDateText = nextDateText;
        }
      }

      function setActiveReportQuickFilter(filterName) {
        qsa(
          ".lo-quick[data-filter]"
        ).forEach(
          function (button) {
            button.classList.toggle(
              "active",
              button.dataset.filter ===
                filterName
            );
          }
        );
      }

      function clearCustomDateInputs() {
        var fromInput =
          qs('[data-role="report-from-date"]');

        var toInput =
          qs('[data-role="report-to-date"]');

        if (fromInput) {
          fromInput.value = "";
        }

        if (toInput) {
          toInput.value = "";
        }

        validateReportDateRange(false);
      }

      function syncReportQuickRangeToDateFields(range) {
        var fromInput =
          qs('[data-role="report-from-date"]');

        var toInput =
          qs('[data-role="report-to-date"]');

        if (!range || !range.from || !range.to) {
          if (fromInput) fromInput.value = "";
          if (toInput) toInput.value = "";
          validateReportDateRange(false);
          return;
        }

        if (fromInput) fromInput.value = range.from;
        if (toInput) toInput.value = range.to;
        validateReportDateRange(false);
      }

      async function activateReportQuickFilter(button) {
        if (
          !button ||
          state.loading
        ) {
          return;
        }

        var filterName =
          text(
            button.dataset.filter ||
            "today"
          ).trim();

        state.reportFilter = filterName;
        state.reportPage = 1;

        setActiveReportQuickFilter(
          filterName
        );

        var range =
          appointmentRange(filterName);

        syncReportQuickRangeToDateFields(
          range
        );

        await renderReport();
      }

      async function activateExecutionQuickFilter(button) {
        if (
          !button ||
          state.loading
        ) {
          return;
        }

        var filterName =
          text(
            button.dataset.executionFilter ||
            "today"
          ).trim();

        state.executionFilter = filterName;
        state.executionPage = 1;

        setActiveExecutionQuickFilter(
          filterName
        );

        var range =
          sessionRange(filterName);

        await ensureSessionRange(
          range.from,
          range.to,
          range.limit,
          filterName === "today"
            ? "Loading today's therapy sessions..."
            : "Loading selected therapy-session range..."
        );

        renderExecution();
