      async function switchManualDateMode() {
        if (state.loading) {
          return;
        }

        var fromInput =
          qs('[data-role="report-from-date"]');

        var toInput =
          qs('[data-role="report-to-date"]');

        var errorBox =
          qs('[data-role="report-date-error"]');

        var fromDate =
          fromInput
            ? text(fromInput.value).trim()
            : "";

        var toDate =
          toInput
            ? text(toInput.value).trim()
            : "";

        if (!fromDate && !toDate) {
          return;
        }

        if (!fromDate || !toDate) {
          if (errorBox) {
