      /* =========================================================
       SCHEDULER-ONLY APPOINTMENT OVERVIEW
       Uses separate data and does not replace state.appointments
    ========================================================= */

    var schedulerOverviewRequestToken = 0;

    function schedulerOverviewSet(
      metricName,
      value
    ) {
      var element =
        qs(
          '[data-scheduler-overview="' +
          metricName +
          '"]'
        );

      if (element) {
        element.textContent =
          String(
            value == null
              ? 0
              : value
          );
      }
    }

    function schedulerOverviewSetDate(
      dateName,
      value
    ) {
      var element =
        qs(
          '[data-scheduler-overview-date="' +
          dateName +
          '"]'
        );

      if (element) {
        element.textContent =
          String(value || "");
      }
    }

    function schedulerOverviewShortDate(
      value
    ) {
      var parts =
        text(value)
          .substring(0, 10)
          .split("-");

      if (parts.length !== 3) {
        return value || "";
      }

      return (
        parts[2] +
        "/" +
        parts[1]
      );
    }

    function schedulerOverviewBusinessMonth(
      referenceDate
    ) {
      var date =
        parseDate(referenceDate);

      var start;

      if (date.getDate() >= 6) {
        start =
          new Date(
            date.getFullYear(),
            date.getMonth(),
            6
          );
      } else {
        start =
          new Date(
            date.getFullYear(),
            date.getMonth() - 1,
            6
          );
      }

      var end =
        new Date(
          start.getFullYear(),
          start.getMonth() + 1,
          5
        );

      return {
        from: toISO(start),
        to: toISO(end)
      };
    }

    function schedulerOverviewStatusGroup(row) {
      var status = String(row?.status || "")
        .trim()
        .toLowerCase();

      var callbackStatus = String(row?.call_back_status || "")
        .trim()
        .toLowerCase();

      /*
       * In your Patient Appointment workflow:
       * Closed = Visited
       */
      if (
        status === "closed" ||
        status === "visited" ||
        status === "executed"
      ) {
        return "visited";
      }

      if (
        status.includes("cancel") ||
        status === "no show"
      ) {
        return "cancelled";
      }

      if (
        status.includes("postpon") ||
        status.includes("re-sched") ||
        status.includes("resched")
      ) {
        return "postponed";
      }

      /*
       * Confirmation Status is checked only after
       * the main Patient Appointment status.
       */
      if (
        callbackStatus === "closed" ||
        callbackStatus === "visited" ||
        callbackStatus === "executed"
      ) {
        return "visited";
      }

      if (
        callbackStatus.includes("cancel") ||
        callbackStatus === "no show"
      ) {
        return "cancelled";
      }

      if (
        callbackStatus.includes("postpon") ||
        callbackStatus.includes("re-sched") ||
        callbackStatus.includes("resched")
      ) {
        return "postponed";
      }

      return "pending";
    }

    function schedulerOverviewSummary(
      rows
    ) {
      var list =
        Array.isArray(rows)
          ? rows
          : [];

      var summary = {
        total: list.length,
        male: 0,
        female: 0,
        visited: 0,
        postponed: 0,
        cancelled: 0,
        pending: 0
      };

      list.forEach(
        function (row) {
          var gender =
            text(
              row.patient_sex ||
              row.gender
            )
              .trim()
              .toLowerCase();

          if (gender.indexOf("male") === 0) {
            summary.male += 1;
          } else if (
            gender.indexOf("female") === 0
          ) {
            summary.female += 1;
          }

          var group =
            schedulerOverviewStatusGroup(row);

          summary[group] += 1;
        }
      );

      return summary;
    }

    function schedulerOverviewPercent(
      value,
      total
    ) {
      if (!total) {
        return "0%";
      }

      return (
        Math.round(
          (
            Number(value || 0) /
            Number(total)
          ) *
          100
        ) +
        "%"
      );
    }

    function schedulerOverviewHourLabel(
      hour
    ) {
      var value =
        Number(hour || 0);

      var period =
        value >= 12
          ? "PM"
          : "AM";

      var hour12 =
        value % 12 || 12;

      return (
        String(hour12)
          .padStart(2, "0") +
        ":00 " +
        period
      );
    }

    function schedulerOverviewPeakRange(
      rows
    ) {
      var list =
        Array.isArray(rows)
          ? rows
          : [];

      if (!list.length) {
        return "—";
      }

      var bestStart = 9;
      var bestCount = -1;

      for (
        var startHour = 7;
        startHour <= 18;
        startHour += 1
      ) {
        var count =
          list.filter(
            function (row) {
              var time =
                text(
                  row.appointment_time
                );

              var hour =
                Number(
                  time.substring(0, 2)
                );

              return (
                Number.isFinite(hour) &&
                hour >= startHour &&
                hour < startHour + 2
              );
            }
          ).length;

        if (count > bestCount) {
          bestCount = count;
          bestStart = startHour;
        }
      }

      if (bestCount <= 0) {
        return "—";
      }

      var startLabel =
        schedulerOverviewHourLabel(
          bestStart
        );

      var endLabel =
        schedulerOverviewHourLabel(
          bestStart + 2
        );

      var startPeriod =
        startLabel.slice(-2);

      var endPeriod =
        endLabel.slice(-2);

      if (startPeriod === endPeriod) {
        startLabel =
          startLabel.replace(
            /\s(?:AM|PM)$/,
            ""
          );
      }

      return (
        startLabel +
        "–" +
        endLabel
      );
    }

    function renderSchedulerOverviewPeriod(
      prefix,
      summary
    ) {
      schedulerOverviewSet(
        prefix + "-total",
        summary.total
      );

      schedulerOverviewSet(
        prefix + "-male",
        summary.male
      );

      schedulerOverviewSet(
        prefix + "-female",
        summary.female
      );

      schedulerOverviewSet(
        prefix + "-visited",
        summary.visited
      );

      schedulerOverviewSet(
        prefix + "-postponed",
        summary.postponed
      );

      schedulerOverviewSet(
        prefix + "-cancelled",
        summary.cancelled
      );

      schedulerOverviewSet(
        prefix + "-pending",
        summary.pending
      );
    }

    async function loadSchedulerOverview() {
      var overview =
        qs(
          '[data-role="scheduler-overview"]'
        );

      if (!overview) {
        return;
      }

      var branchInput =
        qs(
          '[data-role="scheduler-branch"]'
        );

      var selectedBranch =
        text(
          branchInput
            ? branchInput.value
            : state.schedulerBranch
        ).trim();

      if (!selectedBranch) {
        return;
      }

      var requestToken =
        ++schedulerOverviewRequestToken;

      var today =
        state.today ||
        getTodayISO();

      var tomorrow =
        addDays(
          today,
          1
        );

      var nextSevenEnd =
        addDays(
          today,
          6
        );

      var businessMonth =
        schedulerOverviewBusinessMonth(
          today
        );

      var loadFrom =
        businessMonth.from < today
          ? businessMonth.from
          : today;

      var loadTo =
        businessMonth.to > nextSevenEnd
          ? businessMonth.to
          : nextSevenEnd;

      schedulerOverviewSetDate(
        "today",
        schedulerOverviewShortDate(today)
      );

      schedulerOverviewSetDate(
        "tomorrow",
        schedulerOverviewShortDate(tomorrow)
      );

      schedulerOverviewSetDate(
        "next-seven",
        schedulerOverviewShortDate(today) +
        "–" +
        schedulerOverviewShortDate(
          nextSevenEnd
        )
      );

      schedulerOverviewSetDate(
        "month",
        schedulerOverviewShortDate(
          businessMonth.from
        ) +
        "–" +
        schedulerOverviewShortDate(
          businessMonth.to
        )
      );

      try {
        var overviewCacheKey =
          selectedBranch + "|" + loadFrom + "|" + loadTo;

        var cachedOverview =
          state.schedulerOverviewCache.get(overviewCacheKey);

        var rows = [];
        var limitStart = 0;
        var pageSize = 1000;

        var schedulerOverviewFilters = [
          [
            "Patient Appointment",
            "appointment_date",
            ">=",
            loadFrom
          ],
          [
            "Patient Appointment",
            "appointment_date",
            "<=",
            loadTo
          ]
        ];

        if (
          !isAllBranch(
            selectedBranch
          )
        ) {
          schedulerOverviewFilters.push([
            "Patient Appointment",
            "branch",
            "=",
            selectedBranch
          ]);
        }

        if (
          cachedOverview &&
          Date.now() - cachedOverview.loadedAt <
            state.schedulerOverviewCacheTtlMs
        ) {
          rows = cachedOverview.rows.map(
            function (row) {
              return Object.assign({}, row);
            }
          );
        } else {
          while (true) {
            var page =
              await callFrappe(
                "frappe.client.get_list",
                {
                  doctype:
                    "Patient Appointment",

                fields: [
                  "name",
                  "appointment_date",
                  "appointment_time",
                  "patient",
                  "patient_name",
                  "patient_sex",
                  "call_back_status",
                  "status",
                  "branch"
                ],

                filters:
                  schedulerOverviewFilters,

                order_by:
                  "appointment_date asc, appointment_time asc",

                limit_start:
                  limitStart,

                limit_page_length:
                  pageSize
              }
            );

          page =
            Array.isArray(page)
              ? page
              : [];

          rows =
            rows.concat(page);

          if (page.length < pageSize) {
            break;
          }

          limitStart += pageSize;

            if (rows.length >= 10000) {
              break;
            }
          }

          state.schedulerOverviewCache.set(
            overviewCacheKey,
            {
              loadedAt: Date.now(),
              rows: rows.map(
                function (row) {
                  return Object.assign({}, row);
                }
              )
            }
          );

          if (state.schedulerOverviewCache.size > 8) {
            var oldestOverviewKey =
              state.schedulerOverviewCache.keys().next().value;
            state.schedulerOverviewCache.delete(oldestOverviewKey);
          }
        }

        if (
          requestToken !==
          schedulerOverviewRequestToken
        ) {
          return;
        }

        var todayRows =
          rows.filter(
            function (row) {
              return (
                text(
                  row.appointment_date
                ).substring(0, 10) ===
                today
              );
            }
          );

        var tomorrowRows =
          rows.filter(
            function (row) {
              return (
                text(
                  row.appointment_date
                ).substring(0, 10) ===
                tomorrow
              );
            }
          );

        var nextSevenRows =
          rows.filter(
            function (row) {
              var date =
                text(
                  row.appointment_date
                ).substring(0, 10);

              return (
                date >= today &&
                date <= nextSevenEnd
              );
            }
          );

        var monthRows =
          rows.filter(
            function (row) {
              var date =
                text(
                  row.appointment_date
                ).substring(0, 10);

              return (
                date >= businessMonth.from &&
                date <= businessMonth.to
              );
            }
          );

        var todaySummary =
          schedulerOverviewSummary(
            todayRows
          );

        var tomorrowSummary =
          schedulerOverviewSummary(
            tomorrowRows
          );

        var nextSevenSummary =
          schedulerOverviewSummary(
            nextSevenRows
          );

        var monthSummary =
          schedulerOverviewSummary(
            monthRows
          );

        renderSchedulerOverviewPeriod(
          "today",
          todaySummary
        );

        renderSchedulerOverviewPeriod(
          "tomorrow",
          tomorrowSummary
        );

        renderSchedulerOverviewPeriod(
          "next-seven",
          nextSevenSummary
        );

        renderSchedulerOverviewPeriod(
          "month",
          monthSummary
        );

        schedulerOverviewSet(
          "visit-rate",
          schedulerOverviewPercent(
            monthSummary.visited,
            monthSummary.total
          )
        );

        schedulerOverviewSet(
          "cancel-rate",
          schedulerOverviewPercent(
            monthSummary.cancelled,
            monthSummary.total
          )
        );

        schedulerOverviewSet(
          "postpone-rate",
          schedulerOverviewPercent(
            monthSummary.postponed,
            monthSummary.total
          )
        );

        schedulerOverviewSet(
          "performance-total",
          monthSummary.total
        );

        var monthStart =
          parseDate(
            businessMonth.from
          );

        var currentDate =
          parseDate(today);

        var elapsedDays =
          Math.floor(
            (
              currentDate.getTime() -
              monthStart.getTime()
            ) /
            86400000
          ) + 1;

        elapsedDays =
          Math.max(
            1,
            Math.min(
              30,
              elapsedDays
            )
          );

        var projectedMonth =
          monthSummary.total
            ? Math.round(
                (
                  monthSummary.total /
                  elapsedDays
                ) *
                30
              )
            : 0;

        schedulerOverviewSet(
          "forecast-month",
          projectedMonth
        );

        schedulerOverviewSet(
          "forecast-tomorrow",
          tomorrowSummary.total
        );

        schedulerOverviewSet(
          "forecast-peak",
          schedulerOverviewPeakRange(
            monthRows
          )
        );

      } catch (error) {
        void 0;
      }
    }

