      async function handleClickEvent(event) {
        var target = event.target;

        if (
          !target ||
          !root.contains(target)
        ) {
          return;
        }

        var tabButton =
          target.closest("[data-tab]");

        if (tabButton) {
          event.preventDefault();

          showTab(
            tabButton.dataset.tab
          );

          return;
        }

        var executionQuick =
          target.closest(
            ".lo-exec-quick"
          );

        if (executionQuick) {
          event.preventDefault();

          await activateExecutionQuickFilter(
            executionQuick
          );

          return;
        }

        var reportQuick =
          target.closest(
            ".lo-quick[data-filter]"
          );

        if (reportQuick) {
          event.preventDefault();

          await activateReportQuickFilter(
            reportQuick
          );

          return;
        }

        var appointmentButton =
          target.closest(
            "[data-open-appointment]"
          );

        if (appointmentButton) {
          event.preventDefault();

          await openAppointmentDetailsModal(
            appointmentButton.dataset
              .openAppointment
          );

          return;
        }

        var sessionButton =
          target.closest(
            "[data-open-session]"
          );

        if (sessionButton) {
          event.preventDefault();

          openFrappeDocument(
            "Therapy Session",
            sessionButton.dataset
              .openSession
          );

          return;
        }

        var actionElement =
          target.closest("[data-action]");

        if (!actionElement) {
          return;
        }

        var action =
          actionElement.dataset.action;

        event.preventDefault();

        if (action === "select-patient") {
          await selectPatientForBooking(
            actionElement
          );

          return;
        }

        if (action === "new-appointment") {
          var schedulerDateField =
            qs(
              '[data-role="scheduler-date"]'
            );

          await openAppointmentModal({
            branch:
              !isAllBranch(
                state.schedulerBranch
              )
                ? state.schedulerBranch
                : (
                    !isAllBranch(
                      state.branch
                    )
                      ? state.branch
                      : ""
                  ),

            date:
              schedulerDateField &&
              schedulerDateField.value
                ? schedulerDateField.value
                : state.today
          });

          return;
        }

        if (action === "book-slot") {
          await openAppointmentModal({
            date:
              actionElement.dataset.date ||
              state.today,

            time:
              actionElement.dataset.time ||
              "",

            /*
             * The Scheduler button contains the real
             * Service Room document name.
             */
            room:
              actionElement.dataset.room ||
              "",

            branch:
              actionElement.dataset.branch ||
              state.schedulerBranch ||
              (
                isAllBranch(state.branch)
                  ? ""
                  : state.branch
              )
          });

          return;
        }

        if (
          action ===
          "close-appointment-modal"
        ) {
          closeAppointmentModal();
          return;
        }

        if (
          action ===
          "close-appointment-detail"
        ) {
          closeAppointmentDetails();
          return;
        }

        if (
          action ===
          "update-appointment-status"
        ) {
          await updateAppointmentStatus();
          return;
        }

        if (
          action ===
          "submit-appointment"
        ) {
          await submitAppointment();
          return;
        }

        if (action === "manage-rooms") {
          if (
            window.frappe &&
            typeof frappe.set_route === "function"
          ) {
            frappe.set_route(
              "List",
              "Service Room"
            );
          } else {
            window.open(
              "/app/service-room",
              "_blank"
            );
          }

          return;
        }

        if (action === "refresh") {
          await refreshCurrentView();
          return;
        }

        if (
          action ===
          "clear-report-dates"
        ) {
          await clearReportDates();
          return;
        }

        if (action === "export-report") {
          await exportReportCsv();
          return;
        }

        if (
          action ===
          "export-executions"
        ) {
          exportExecutionsCsv();
          return;
        }

        if (action === "report-prev") {
          if (state.reportPage > 1) {
            state.reportPage -= 1;
            await renderReport();
          }

          return;
        }

        if (action === "report-next") {
          var canGoNext = state.reportTotalKnown
            ? state.reportPage < Math.max(
                1,
                Math.ceil(
                  Number(state.reportTotal || 0) /
                  Number(state.reportPageSize || 25)
                )
              )
            : state.reportHasMore;

          if (canGoNext) {
            state.reportPage += 1;
            await renderReport();
          }
          return;
        }

      }

