        function text(value) {
          return String(value == null ? "" : value);
        }

        function clean(value) {
          return text(value).trim();
        }

        function numberValue(value) {
          var number = Number(
            text(value).replace(/[^0-9.\-]/g, "")
          );

          return Number.isFinite(number)
            ? number
            : 0;
        }

        function escapeHtml(value) {
          return text(value)
            .replace(/&/g, "&amp;")
            .replace(/</g, "&lt;")
            .replace(/>/g, "&gt;")
            .replace(/"/g, "&quot;")
            .replace(/'/g, "&#039;");
        }

        function todayISO() {
          if (
            window.frappe &&
            frappe.datetime &&
            frappe.datetime.get_today
          ) {
            return frappe.datetime.get_today();
          }

          var date = new Date();

          return (
            date.getFullYear() +
            "-" +
            String(date.getMonth() + 1).padStart(2, "0") +
            "-" +
            String(date.getDate()).padStart(2, "0")
          );
        }

        function nowTime() {
          var date = new Date();

          return (
            String(date.getHours()).padStart(2, "0") +
            ":" +
            String(date.getMinutes()).padStart(2, "0")
          );
        }

        function addLiveDays(
          dateValue,
          numberOfDays
        ) {
          var value =
            clean(dateValue) ||
            todayISO();

          var date = new Date(
            value.substring(0, 10) +
            "T00:00:00"
          );

          date.setDate(
            date.getDate() +
            Number(numberOfDays || 0)
          );

          return (
            date.getFullYear() +
            "-" +
            String(
              date.getMonth() + 1
            ).padStart(2, "0") +
            "-" +
            String(
              date.getDate()
            ).padStart(2, "0")
          );
        }

        function formatDate(value) {
          return window.lifeOpsFormatDisplayDate(value);
        }

        function initials(name) {
          var words = clean(name)
            .split(/\s+/)
            .filter(Boolean);

          if (!words.length) {
            return "--";
          }

          return words
            .slice(0, 2)
            .map(function (word) {
              return word.charAt(0).toUpperCase();
            })
            .join("");
        }

        function calculateAge(dob) {
          var value = clean(dob).substring(0, 10);

          if (!value) {
            return "";
          }

          var birthDate = new Date(value + "T00:00:00");

          if (Number.isNaN(birthDate.getTime())) {
            return "";
          }

          var now = new Date();
          var age = now.getFullYear() - birthDate.getFullYear();
          var monthDifference = now.getMonth() - birthDate.getMonth();

          if (
            monthDifference < 0 ||
            (
              monthDifference === 0 &&
              now.getDate() < birthDate.getDate()
            )
          ) {
            age -= 1;
          }

          return age >= 0
            ? String(age)
            : "";
        }

        function getFrappeRequestError(error) {
