                  var item = serverMessages[index];
                  var parsed = item;

                  if (typeof item === "string") {
                    try {
                      parsed = JSON.parse(item);
                    } catch (ignoreMessageParseError) {
                      parsed = item;
                    }
                  }

                  if (
                    parsed &&
                    typeof parsed === "object" &&
                    parsed.message
                  ) {
                    message = clean(parsed.message);
                    break;
                  }

                  if (
                    typeof parsed === "string" &&
                    clean(parsed)
                  ) {
                    message = clean(parsed);
                    break;
                  }
                }
