        /*
         * SESSION EXECUTION — NEXT APPOINTMENT VALIDATION
         *
         * This validation is intentionally client-level.
         * A valid future Session appointment for the selected client is enough
         * to satisfy the next-appointment requirement even when the appointment
         * was created against an older/different Therapy Plan or Therapy Type.
         *
         * No appointment is created when ERPNext appointment history cannot be
         * verified. This prevents duplicate appointments during retries.
         */
        async function validateClientNextAppointmentForSession() {
          var patient =
            liveState.selectedPatient;

          if (
            !patient ||
            !patient.name
          ) {
            return {
              checked: false,
              appointment: null
            };
          }

          var fieldSets = [
            [
              "name",
              "patient",
              "appointment_type",
              "appointment_date",
              "appointment_time",
              "status",
              "call_back_status",
              "branch",
              "docstatus"
            ],
            [
              "name",
              "patient",
              "appointment_date",
              "appointment_time",
              "status",
              "branch",
              "docstatus"
            ]
          ];

          var lastError = null;

          for (
            var fieldIndex = 0;
            fieldIndex < fieldSets.length;
            fieldIndex += 1
          ) {
            try {
              var rows = await callFrappe(
                "frappe.client.get_list",
                {
                  doctype: "Patient Appointment",
                  fields: fieldSets[fieldIndex],
                  filters: [
                    [
                      "Patient Appointment",
                      "patient",
                      "=",
                      patient.name
                    ]
                  ],
                  order_by:
                    "appointment_date asc, appointment_time asc",
                  limit_start: 0,
                  limit_page_length: 1000
                }
              );

              rows = Array.isArray(rows)
                ? rows
                : [];

              var existingAppointment =
                rows.find(function (appointment) {
                  if (!appointment) {
                    return false;
                  }

                  /*
                   * Cancelled ERPNext document.
                   */
                  if (
                    Number(
                      appointment.docstatus || 0
                    ) === 2
                  ) {
                    return false;
                  }

                  /*
                   * Only Session appointments should satisfy
                   * the Session Execution next-appointment rule.
                   * Older records without appointment_type are allowed.
                   */
                  var appointmentType = clean(
                    appointment.appointment_type
                  ).toLowerCase();

                  if (
                    appointmentType &&
                    appointmentType !== "session"
                  ) {
                    return false;
                  }

                  /*
                   * Read both status fields because this site uses
                   * call_back_status for Scheduled / confirmation state.
                   */
                  var statusText = [
                    appointment.status,
                    appointment.call_back_status
                  ]
                    .map(function (value) {
                      return clean(value);
                    })
                    .filter(Boolean)
                    .join(" ")
                    .toLowerCase();

                  /*
                   * These appointments are not a fixed usable
                   * "next appointment".
                   */
                  if (
                    statusText.indexOf("cancel") !== -1 ||
                    statusText.indexOf("no show") !== -1 ||
                    statusText.indexOf("closed") !== -1 ||
                    statusText.indexOf("executed") !== -1 ||
                    statusText.indexOf("visited") !== -1 ||
                    statusText.indexOf("postpon") !== -1
                  ) {
                    return false;
                  }

                  /*
                   * IMPORTANT:
                   * Do NOT compare Therapy Plan or Therapy Type here.
                   * The rule is whether this client already has a valid
                   * future Session appointment fixed.
                   */
                  return appointmentIsAfterCurrentSession(
                    appointment
                  );
                }) || null;

              if (existingAppointment) {
                markNextAppointmentBooked(
                  existingAppointment
                );
              }

              return {
                checked: true,
                appointment:
                  existingAppointment
              };

            } catch (error) {
              lastError = error;
            }
          }

          void 0;

          showError(
            "Could not verify this client's existing appointments. No new appointment was created. Please try again."
          );

          return {
            checked: false,
            appointment: null
          };
        }



        async function lifeNormalizeWalkInMediaForNextAppointment(
          selectedPatient,
          selectedPlan
        ) {
          /*
           * LIFE FIX — LEGACY "Walk In" MEDIA/SOURCE
           * -------------------------------------------------------------
           * On this site Media fields are Link fields to Lead Source.
           * Some older Patient / Therapy Plan records still contain
           * "Walk In", while the canonical Lead Source is "DIRECT WALKIN".
           *
           * Frappe therefore raises:
           *   Could not find Media: Walk In
           *
           * Before opening/submitting the required Next Appointment, repair
           * only recognized Walk-In aliases to the canonical Lead Source.
           * Other sources are never changed.
           */
          var aliases = {
            "walk in": "DIRECT WALKIN",
            "walk-in": "DIRECT WALKIN",
            "walkin": "DIRECT WALKIN",
            "direct walk in": "DIRECT WALKIN",
            "direct walk-in": "DIRECT WALKIN",
            "direct walkin": "DIRECT WALKIN"
          };

          function canonical(value) {
            var key = clean(value).toLowerCase();
            return aliases[key] || "";
          }

          async function leadSourceExists(value) {
            if (!value) {
              return false;
            }

            try {
              var count = await callFrappe(
                "frappe.client.get_count",
                {
                  doctype: "Lead Source",
                  filters: [
                    [
                      "Lead Source",
                      "name",
                      "=",
                      value
                    ]
                  ]
                }
              );

              return Number(count || 0) > 0;
            } catch (error) {
              void 0;
              return false;
            }
          }

          if (!(await leadSourceExists("DIRECT WALKIN"))) {
            void 0;
            return;
          }

          var updates = [];

          /*
           * Patient.custom_media -> Lead Source
           */
          if (
            selectedPatient &&
            selectedPatient.name
          ) {
            var patientMedia =
              selectedPatient.custom_media ||
              selectedPatient.media ||
              selectedPatient.source ||
              "";

            var patientCanonical =
              canonical(patientMedia);

            if (patientCanonical) {
              updates.push(
                callFrappe(
                  "frappe.client.set_value",
                  {
                    doctype: "Patient",
                    name: selectedPatient.name,
                    fieldname: "custom_media",
                    value: patientCanonical
                  }
                )
                  .then(function () {
                    selectedPatient.custom_media =
                      patientCanonical;
                  })
                  .catch(function (error) {
                    void 0;
                  })
              );
            }
          }

          /*
           * Therapy Plan.media -> Lead Source
           */
          var planName =
            selectedPlan &&
            (
              selectedPlan.planName ||
              selectedPlan.planId ||
              selectedPlan.therapyPlan ||
              selectedPlan.plan ||
              selectedPlan.name
            );

          var planMedia =
            selectedPlan &&
            (
              selectedPlan.media ||
              selectedPlan.custom_media ||
              (
                selectedPlan.plan &&
                selectedPlan.plan.media
              )
            );

          var planCanonical =
            canonical(planMedia);

          /*
           * When the compact selectedPlan row does not contain media, load
           * the Therapy Plan once so legacy "Walk In" can still be repaired.
           */
          if (
            planName &&
            !planCanonical
          ) {
            try {
              var planDoc =
                await getDoc(
                  "Therapy Plan",
                  planName
                );

              if (planDoc) {
                planMedia =
                  planDoc.media ||
                  planDoc.custom_media ||
                  "";

                planCanonical =
                  canonical(planMedia);
              }
            } catch (error) {
              void 0;
            }
          }

          if (
            planName &&
            planCanonical
          ) {
            updates.push(
              callFrappe(
                "frappe.client.set_value",
                {
                  doctype: "Therapy Plan",
                  name: planName,
                  fieldname: "media",
                  value: planCanonical
                }
              )
                .then(function () {
                  if (selectedPlan) {
                    selectedPlan.media =
                      planCanonical;

                    if (
                      selectedPlan.plan &&
                      typeof selectedPlan.plan === "object"
                    ) {
                      selectedPlan.plan.media =
                        planCanonical;
                    }
                  }
                })
                .catch(function (error) {
                  void 0;
                })
            );
          }

          if (updates.length) {
            await Promise.all(updates);
          }
        }

        async function openLiveAppointmentBooking(context) {
