        function getLoginBranch() {
          var liveBranch = qs(
            '[data-role="live-session-branch"]'
          );

          if (
            liveBranch &&
            liveBranch.value &&
            liveBranch.value !== "all"
          ) {
            return liveBranch.value;
          }

          var branchSelectors = [
            '[data-role="scheduler-branch"]',
            '[data-role="report-branch"]',
            '[data-role="execution-branch"]',
            '[data-role="today-exec-branch"]'
          ];

          for (
            var index = 0;
            index < branchSelectors.length;
            index += 1
          ) {
            var select = qs(branchSelectors[index]);

            if (
              select &&
              select.value &&
              select.value !== "all"
            ) {
              return select.value;
            }
          }

          try {
            if (
              frappe.defaults &&
              frappe.defaults.get_user_default
            ) {
              var defaultBranch = clean(
                frappe.defaults.get_user_default("branch")
              );

              return (
                typeof window.lifeOpsIsExcludedBranch === "function" &&
                window.lifeOpsIsExcludedBranch(defaultBranch)
              )
                ? ""
                : defaultBranch;
            }
          } catch (error) {
            window.__lifeOpsV4Debug && void 0;
          }

          return "";
        }

        function populateLiveBranch() {
          var select = qs(
            '[data-role="live-session-branch"]'
          );

          if (!select) {
            return;
          }

          var source =
            qs('[data-role="scheduler-branch"]') ||
            qs('[data-role="report-branch"]');

          var preferred =
            liveState.branch ||
            getLoginBranch();

          if (
            typeof window.lifeOpsIsExcludedBranch === "function" &&
            window.lifeOpsIsExcludedBranch(preferred)
          ) {
            preferred = "";
          }

          if (
            source &&
            source.options &&
            source.options.length
          ) {
            select.innerHTML = source.innerHTML;

            Array.from(select.options).forEach(function (option) {
              if (
                typeof window.lifeOpsIsExcludedBranch === "function" &&
                window.lifeOpsIsExcludedBranch(option.value)
              ) {
                option.remove();
              }
            });
          }

          if (preferred) {
            var exists = Array.prototype.some.call(
              select.options,
              function (option) {
                return option.value === preferred;
              }
            );

            if (!exists) {
              var option = document.createElement("option");
              option.value = preferred;
              option.textContent = preferred;
              select.appendChild(option);
            }

            select.value = preferred;
            liveState.branch = preferred;
          } else if (select.value === "all") {
            liveState.branch = "";
          }
        }

