          var planValue = clean(planName);
          var therapyValue = clean(therapyType);
          var today = todayISO();

          var rows = liveState.appointments.filter(
            function (appointment) {
              var samePlan =
                clean(appointment.therapy_plan) === planValue;

              if (!samePlan) {
                return false;
              }

              var appointmentTherapy =
                clean(appointment.therapy_type);

              if (therapyValue) {
                return (
                  appointmentTherapy ===
                  therapyValue
                );
              }

              return true;
            }
          );

          var cancelled = rows.filter(
            function (row) {
              return isCancelledAppointment(row.status);
            }
          ).length;

          var postponed = rows.filter(
            function (row) {
              return isPostponedAppointment(row.status);
            }
          ).length;

          var openRows = rows
            .filter(function (row) {
              return (
                clean(row.appointment_date) >= today &&
                !isCancelledAppointment(row.status) &&
                !isClosedAppointment(row.status)
              );
            })
            .sort(function (left, right) {
              var leftValue =
                clean(left.appointment_date) +
                " " +
                clean(left.appointment_time);

              var rightValue =
                clean(right.appointment_date) +
                " " +
                clean(right.appointment_time);

              return leftValue.localeCompare(rightValue);
            });

          var todayAppointment = openRows.find(
            function (row) {
              return clean(row.appointment_date) === today;
            }
          );

          return {
            cancelled: cancelled,
            postponed: postponed,
            nextDue:
              openRows.length
                ? openRows[0].appointment_date
                : fallbackDueDate,
            /*
             * Only today's appointment can be linked to the
             * Therapy Session. A future appointment remains
             * visible through Next Due and is never used as
             * the current session appointment.
             */
            appointment:
              todayAppointment
                ? todayAppointment.name
                : "",
            appointmentRow:
              todayAppointment ||
              null
          };
        }

