           ========================================================= */

        async function loadLivePatientPlans(patient) {
          var table = qs(
            '[data-table="live-plans"]'
          );

          var card = qs(
            '[data-role="live-plans-card"]'
          );

          if (!table || !card) {
            return;
          }

          var requestId =
            Number(liveState.planRequestId || 0) + 1;

          liveState.planRequestId = requestId;

          function isCurrentRequest() {
            return (
              liveState.planRequestId === requestId &&
              liveState.selectedPatient &&
              liveState.selectedPatient.name === patient.name
            );
          }

          table.innerHTML =
            '<tr><td colspan="11" class="lo-empty">' +
            '<div class="lo-live-inline-loading">' +
            '<span class="lo-live-inline-spinner"></span>' +
            '<span>Loading Therapy Plans with balance sessions...</span>' +
            '</div>' +
            '</td></tr>';

          card.hidden = false;

          var slowNotice = window.setTimeout(function () {
            if (
              isCurrentRequest() &&
              table.textContent.indexOf(
                "Loading Therapy Plans with balance sessions"
              ) !== -1
            ) {
              table.innerHTML =
                '<tr><td colspan="11" class="lo-empty">' +
                'Still loading this client\'s Therapy Plans. ' +
                'The server is processing the records...' +
                '</td></tr>';
            }
          }, 10000);

          try {
            /*
             * Fast parent query: fetch the required Therapy Plan values in
             * one request instead of opening every Therapy Plan document.
             */
            var plans = await callFrappe(
              "frappe.client.get_list",
              {
                doctype: "Therapy Plan",
                fields: [
                  "name",
                  "patient",
                  "patient_name",
                  "creation",
                  "status",
                  "start_date",
                  "due_date",
                  "branch",
                  "category",
                  "company",
                  "consultant_name",
                  "invoiced",
                  "total_sessions",
                  "total_sessions_completed",
                  "modified"
                ],
                /*
                 * LIFE V88 EXACT CLIENT PLAN FILTER
                 * ---------------------------------------------------------
                 * Therapy Plan.patient is the real Patient Link and must be
                 * the ONLY identity used for Session Execution.
                 *
                 * Do NOT use patient_name here. patient_name is display text
                 * and is not unique. Two different Patient records can have
                 * the same Full Name, which can mix another client's plans.
                 * ---------------------------------------------------------
                 */
                filters: [
                  [
                    "Therapy Plan",
                    "patient",
                    "=",
                    patient.name
                  ]
                ],
                order_by: "modified desc",
                limit_start: 0,
                limit_page_length: 100
              }
            );

            plans = Array.isArray(plans)
              ? plans
              : [];

            /*
             * LIFE V88:
             * No patient_name fallback is allowed.
             * If the exact Patient Link returns no Therapy Plans, show no
             * plans rather than borrowing plans from another client who has
             * the same displayed patient name.
             */

            /*
             * LIFE V89 — STRICT CLIENT IDENTITY GUARD
             * -------------------------------------------------------------
             * 1) Therapy Plan.patient MUST equal the exact selected Patient
             *    document name.
             * 2) A Therapy Plan created before this Patient document existed
             *    cannot belong to this Patient record. This catches legacy
             *    same-name/collision data where old plans were later linked
             *    against a newer duplicate Patient record.
             *
             * Example:
             *   selected Patient: Ravi Kiran - 7 (created Aug-2026)
             *   Therapy Plan created in 2023/2024/2025
             * Such a plan is impossible for this Patient document and must
             * never appear in Session Execution.
             * -------------------------------------------------------------
             */
            var selectedPatientCreatedAt = clean(
              patient.creation || ""
            );

            var excludedPlanAudit = [];

            plans = plans.filter(function (plan) {
              var exactPatient =
                clean(plan.patient) ===
                clean(patient.name);

              var planCreatedAt =
                clean(plan.creation || "");

              var chronologyValid = true;

              if (
                selectedPatientCreatedAt &&
                planCreatedAt
              ) {
                chronologyValid =
                  new Date(planCreatedAt).getTime() >=
                  new Date(selectedPatientCreatedAt).getTime();
              }

              if (
                !exactPatient ||
                !chronologyValid
              ) {
                excludedPlanAudit.push({
                  plan: clean(plan.name),
                  plan_patient: clean(plan.patient),
                  selected_patient: clean(patient.name),
                  plan_created: planCreatedAt,
                  patient_created: selectedPatientCreatedAt,
                  reason: !exactPatient
                    ? "different Patient Link"
                    : "plan predates Patient record"
                });

                return false;
              }

              return true;
            });

            if (excludedPlanAudit.length) {
              void 0;
            }

            plans = plans.filter(function (plan) {
              var status = clean(plan.status).toLowerCase();

              /*
               * Expiry/due date must NOT hide a client's pending sessions.
               * Keep every non-cancelled Therapy Plan here; the actual therapy
               * rows are filtered later only by their remaining balance.
               */
              return status.indexOf("cancel") === -1;
            });

            if (!isCurrentRequest()) {
              return;
            }

            var planNames = plans.map(function (plan) {
              return plan.name;
            });

            /*
             * Permission-safe detail loading.
             * Frappe blocks frappe.client.get_list on child DocTypes for many
             * non-System-Manager users. Open each permitted parent Therapy Plan
             * document instead; its therapy_plan_details rows are returned with it.
             */
            if (planNames.length) {
              var fullDocs = [];
              var chunkSize = 4;

              for (
                var offset = 0;
                offset < planNames.length;
                offset += chunkSize        ) {
                if (!isCurrentRequest()) {
                  return;
                }

                var chunk = planNames.slice(
                  offset,
                  offset + chunkSize
                );

                var chunkDocs = await Promise.all(
                  chunk.map(function (name) {
                    return getDoc(
                      "Therapy Plan",
                      name
                    ).catch(function (error) {
                      window.__lifeOpsV4Debug && void 0;
                      return null;
                    });
                  })
                );

                fullDocs = fullDocs.concat(
                  chunkDocs.filter(Boolean)
                );
              }

              if (fullDocs.length) {
                plans = fullDocs;
              }
            }

            /*
             * LIFE V89 FINAL RECORD CHECK
             * Re-check the full Therapy Plan documents immediately before
             * appointments/session history and rendering.
             */
            plans = plans.filter(function (plan) {
              if (
                clean(plan.patient) !==
                clean(patient.name)
              ) {
                return false;
              }

              var patientCreated =
                clean(patient.creation || "");

              var planCreated =
                clean(plan.creation || "");

              if (
                patientCreated &&
                planCreated &&
                new Date(planCreated).getTime() <
                  new Date(patientCreated).getTime()
              ) {
                return false;
              }

              return true;
            });

            if (!isCurrentRequest()) {
              return;
            }

            /* Appointments and Therapy Type metadata now load in parallel. */
            await Promise.all([
              loadPatientAppointments(patient.name),
              loadPatientTherapySessions(patient.name),
              loadPatientZeroSessions(patient.name),
              loadTherapyTypeDocuments(plans)
            ]);

            if (!isCurrentRequest()) {
              return;
            }

            // --- SLIMMING / DERMAT CATEGORY SPLIT ---

            // Clear existing plan rows before processing
            liveState.planRows = [];

            // Define category keywords based on your DocType's `category` field
            // These are the names of the Healthcare Service Unit records.
            var slimmingCategories = [
              'Slimming - LSACPL',
              'Cryo - LSACPL',
              // Add any other "Slimming" service units here
            ];

            var dermatCategories = [
              'Hair - LSACPL',
              'Skin - LSACPL',
              'Laser - LSACPL',
              // Add any other "Dermat" service units here
            ];

            // Process all plans
            plans.forEach(function (plan) {
              var status = clean(plan.status).toLowerCase();

              if (status.indexOf("cancel") !== -1) {
                return;
              }

              var planDetails = Array.isArray(
                plan.therapy_plan_details
              )
                ? plan.therapy_plan_details.slice()
                : [];

              /*
               * V82 THERAPY PLAN DETAILS ONLY
               * Execution rows must come only from Therapy Plan.therapy_plan_details.
               * Sales Invoice items are intentionally NOT used to create, recover,
               * or replace therapy rows. Payment status also does not decide whether
               * a therapy row is shown.
               */
              if (!planDetails.length) {
                return;
              }

              planDetails.forEach(function (detail, index) {
                var therapyType = clean(
                  detail.therapy_type ||
                  detail.therapy ||
                  detail.service ||
                  detail.item_code ||
                  plan.title
                );

                var therapyDoc =
                  liveState.therapyTypes[therapyType] ||
                  {};

                var total = therapyDetailTotal(
                  detail,
                  plan
                );


                var planCompleted = therapyDetailCompleted(
                  detail,
                  plan
                );

                /*
                 * Recalculate Done and Cancelled directly from Therapy Session
                 * documents. This prevents a cancelled submitted session from
                 * remaining inside the Done count when Therapy Plan counters are
                 * stale. If Therapy Session history is unavailable, retain the
                 * Therapy Plan value as a safe fallback.
                 */
                var sessionStats = therapySessionStatsFor(
                  plan.name,
                  therapyType
                );

                var completed = sessionStats.hasRows
                  ? sessionStats.submitted
                  : planCompleted;

                var balance = Math.max(
                  0,
                  total - completed
                );

                /* LIFE V94: keep completed Therapy Types visible. */

                // Determine the category of this plan row
                // The plan.category field is a link to 'Healthcare Service Unit'
                var planCategory = clean(plan.category || '');

                var rowCategory = 'Other'; // Default category

                if (slimmingCategories.some(cat => planCategory === cat)) {
                    rowCategory = 'Slimming';
                } else if (dermatCategories.some(cat => planCategory === cat)) {
                    rowCategory = 'Dermat';
                }

                var stats = appointmentStatsFor(
                  plan.name,
                  therapyType,
                  plan.due_date || ""
                );

                var planBranch = clean(
                  plan.custom_transfer_branch ||
                  plan.branch ||
                  patient.branch_name ||
                  patient.custom_branch ||
                  liveState.branch
                );

                // Add the row with its category
                liveState.planRows.push({
                  key:
                    plan.name +
                    "::" +
                    String(index),
                  plan: plan,
                  detail: detail,
                  planName: plan.name,
                  service:
                    therapyType ||
                    therapyDetailService(
                      detail,
                      plan
                    ),
                  therapyType: therapyType,
                  therapyDoc: therapyDoc,
                  department: clean(
                    detail.department ||
                    detail.medical_department ||
                    therapyDoc.medical_department ||
                    ""
                  ),
                  category: planCategory, // Store the full category for display
                  serviceUnit: clean(
                    therapyDoc.healthcare_service_unit ||
                    plan.category ||
                    ""
                  ),
                  total: total,
                  completed: completed,
                  balance: balance,
                  cancelled: sessionStats.cancelled,
                  postponed: stats.postponed,
                  dueDate: stats.nextDue,
                  appointment: stats.appointment,
                  appointmentRow: stats.appointmentRow,
                  branch: planBranch,
                  company: plan.company || "",
                  consultant: plan.consultant_name || "",
                  invoiced: Number(plan.invoiced || 0),
                  duration:
                    numberValue(
                      therapyDoc.default_duration
                    ) || 30,
                  rate:
                    numberValue(therapyDoc.rate),
                  categoryGroup: rowCategory // Store the group for rendering
                });
              });
            });

            // --- END CATEGORY SPLIT ---

            renderLivePlans();
          } catch (error) {
            if (!isCurrentRequest()) {
              return;
            }

            void 0;

            liveState.planRows = [];

            table.innerHTML =
              '<tr><td colspan="11" class="lo-empty">' +
              escapeHtml(
                error && error.message
                  ? error.message
                  : "Unable to load Therapy Plans."
              ) +
              '<br><button type="button" class="lo-btn lo-light" ' +
              'data-action="live-search-client" style="margin-top:10px">' +
              'Retry</button></td></tr>';

            setText(
              '[data-count="live-plans"]',
              "0"
            );
          } finally {
            window.clearTimeout(slowNotice);
          }
        }

        function cleanLiveDepartmentLabel(value) {
      var label = String(value || "").trim();

      if (!label) {
        return "-";
      }

      return (
        label
          .replace(/\s*-\s*LSACPL\s*$/i, "")
          .trim() || "-"
      );
    }

        function renderLivePlans() {
          var table = qs(
            '[data-table="live-plans"]'
          );

          if (!table) {
            return;
          }

          /*
           * Group all balance therapy rows by Therapy Plan ID.
           * The individual therapy rows and Execute buttons remain separate.
           */
          var groupedPlans = [];
          var planGroupMap = Object.create(null);

          liveState.planRows.forEach(function (row) {
            var planName =
              text(row.planName).trim();

            /*
             * Do not combine rows that have no Therapy Plan ID.
             */
            var groupKey = planName
              ? planName.toLowerCase()
              : "__missing_plan__" + text(row.key);

            if (!planGroupMap[groupKey]) {
              planGroupMap[groupKey] = {
                planName: planName || "-",
                rows: []
              };

              groupedPlans.push(
                planGroupMap[groupKey]
              );
            }

            planGroupMap[groupKey].rows.push(row);
          });

          /*
           * Show the number of unique Therapy Plan IDs,
           * not the number of therapy child rows.
           */
          setText(
            '[data-count="live-plans"]',
            groupedPlans.length
          );

          var plansCard = qs(
            '[data-role="live-plans-card"]'
          );

          if (plansCard) {
            var heading = plansCard.querySelector(
              ".lo-card-head h3"
            );

            if (heading) {
              var patientName =
                liveState.selectedPatient &&
                (
                  liveState.selectedPatient.patient_name ||
                  liveState.selectedPatient.first_name ||
                  liveState.selectedPatient.name
                );

              heading.textContent =
                "📋 Therapy Plans & Session Status" +
                (
                  patientName
                    ? " — " + patientName
                    : ""
                );
            }
          }

          if (!liveState.planRows.length) {
            table.innerHTML =
              '<tr>' +
                '<td colspan="11" class="lo-empty">' +
                  "No Therapy Plan was found for this client." +
                "</td>" +
              "</tr>";

            return;
          }

          var output = [];

          groupedPlans.forEach(function (group) {
            var groupRowCount =
              group.rows.length;

            group.rows.forEach(function (
              row,
              rowIndex
            ) {
              var percentage = row.total
                ? Math.min(
                    100,
                    Math.max(
                      0,
                      row.completed /
                        row.total *
                        100
                    )
                  )
                : 0;

              /*
               * Show the Therapy Plan ID only on the first row.
               * rowspan merges the ID cell across all therapy rows
               * belonging to the same Therapy Plan.
               */
              var planIdCell =
                rowIndex === 0
                  ? (
                      '<td rowspan="' +
                        groupRowCount +
                      '" class="lo-live-plan-id-cell">' +
                        '<span class="lo-live-plan-id">' +
                          escapeHtml(group.planName) +
                        "</span>" +
                      "</td>"
                    )
                  : "";

              output.push(
                "<tr>" +

                  planIdCell +

                  '<td>' +
                    '<div class="lo-live-plan-service" title="' +
                      escapeHtml(row.service) +
                    '">' +
                      escapeHtml(
                        row.service || "-"
                      ) +
                    "</div>" +
                  "</td>" +

                  '<td class="lo-live-plan-department-cell">' +
                      '<div class="lo-live-plan-category" title="' +
                        escapeHtml(
                          cleanLiveDepartmentLabel(
                            row.department ||
                            row.category ||
                            "-"
                          )
                        ) +
                      '">' +
                        escapeHtml(
                          cleanLiveDepartmentLabel(
                            row.department ||
                            row.category ||
                            "-"
                          )
                        ) +
                      "</div>" +
                    "</td>" +

                  '<td class="lo-live-plan-number">' +
                    escapeHtml(row.total) +
                  "</td>" +

                  '<td class="lo-live-plan-number">' +
                    escapeHtml(row.completed) +
                  "</td>" +

                  '<td class="lo-live-plan-number">' +
                    escapeHtml(row.cancelled) +
                  "</td>" +

                  '<td class="lo-live-plan-number">' +
                    escapeHtml(row.postponed) +
                  "</td>" +

                  "<td>" +
                    '<div class="lo-live-plan-progress">' +
                      '<div class="lo-live-plan-progress-bar" style="width:' +
                        percentage.toFixed(2) +
                      '%"></div>' +

                      "<span>" +
                        percentage.toFixed(0) +
                        "%" +
                      "</span>" +
                    "</div>" +
                  "</td>" +

                  '<td class="lo-live-plan-number">' +
                    escapeHtml(row.balance) +
                  "</td>" +

                  "<td>" +
                    escapeHtml(
                      formatDate(row.dueDate)
                    ) +
                  "</td>" +

                  "<td>" +
                    livePlanActionHtml(row) +
                  "</td>" +

                "</tr>"
              );
            });
          });

          table.innerHTML =
            output.join("");
        }

        function normalizeLiveStaffBranch(value) {
          var normalized = clean(value)
            .toLowerCase()
            .replace(/\s*-\s*lsacpl\s*$/i, "")
            .replace(/^[a-z0-9]{1,6}\s*[—–-]\s*/i, "")
            /*
             * V65: Portal/client branch labels may contain the word "Branch"
             * while Healthcare Practitioner Branch List stores only "SR Nagar".
             * Treat "SR Nagar Branch" and "SR Nagar" as the same branch.
             */
            .replace(/\s+branch\s*$/i, "")
            .replace(/\s+/g, " ")
            .trim();

          /*
           * LIFE branch aliases. This also handles short branch codes if they
           * appear in Patient / Therapy Plan / login defaults.
           */
          var aliases = {
            "srn": "sr nagar",
            "sr nagar": "sr nagar",
            "s r nagar": "sr nagar",
            "kp": "kukatpally",
            "kukatpally": "kukatpally",
            "chn": "chandanagar",
            "chandanagar": "chandanagar",
            "bh": "banjara hills",
            "banjara hills": "banjara hills",
            "dsk": "dilsukhnagar",
            "dilsukhnagar": "dilsukhnagar",
            "hn": "himayatnagar",
            "himayatnagar": "himayatnagar",
            "mp": "madhapur",
            "madhapur": "madhapur",
            "gcb": "gachibowli",
            "gachibowli": "gachibowli",
            "nlr": "nellore",
            "nellore": "nellore",
            "vz": "vizag",
            "vizag": "vizag",
            "vja": "vijayawada",
            "vijayawada": "vijayawada"
          };

          return aliases[normalized] || normalized;
        }

        function liveStaffBranchTextMatches(
          value,
          selectedBranchKey
        ) {
          if (!value || !selectedBranchKey) {
            return false;
          }

          var raw = String(value || "");

          var parts = raw
            .split(/[\n\r,;|]+/)
            .map(function (item) {
              return normalizeLiveStaffBranch(item);
            })
            .filter(Boolean);

          if (
            parts.some(function (item) {
              return item === selectedBranchKey;
            })
          ) {
            return true;
          }

          return (
            normalizeLiveStaffBranch(raw) ===
            selectedBranchKey
          );
        }

        async function loadLivePractitioners(branch) {
          var selectedBranch = clean(branch);

          /*
           * V73 — SERVER-SIDE BRANCH PRACTITIONER LOADER
           * ---------------------------------------------------------------
           * IMPORTANT:
           * Frappe blocks browser-side frappe.client.get_list calls to the
           * child table "Employee Branches" with 403 PermissionError because
           * check_parent_permission() is enforced.
           *
           * Therefore branch membership from Healthcare Practitioner
           * custom_branch_list MUST be resolved server-side.
           *
           * API Server Script:
           *   life_ops_branch_practitioners
           */
          try {
            if (!selectedBranch) {
              liveState.practitioners = [];
              populateLiveStaffSelects();
              return;
            }

            var rows = await callFrappe(
              "life_ops_branch_practitioners",
              {
                branch: selectedBranch
              }
            );

            rows = Array.isArray(rows)
              ? rows
              : (
                  rows &&
                  Array.isArray(rows.message)
                    ? rows.message
                    : []
                );

            liveState.practitioners = rows
              .map(function (row) {
                return {
                  name: clean(row.name),
                  label:
                    clean(row.practitioner_name) ||
                    clean(row.label) ||
                    clean(row.name),
                  practitioner_name:
                    clean(row.practitioner_name),
                  designation:
                    clean(
                      row.designation ||
                      row.department ||
                      ""
                    ),
                  department:
                    clean(row.department || ""),
                  branch:
                    clean(row.branch || ""),
                  branchListText:
                    clean(
                      row.custom_branch_list_text ||
                      row.branch_list_text ||
                      ""
                    ),
                  custom_branch_list_text:
                    clean(
                      row.custom_branch_list_text ||
                      row.branch_list_text ||
                      ""
                    ),
                  custom_additional_branches:
                    clean(
                      row.custom_additional_branches ||
                      ""
                    ),
                  custom_available_all_branches:
                    Number(
                      row.custom_available_all_branches ||
                      0
                    ),
                  custom_branch_list:
                    Array.isArray(
                      row.custom_branch_list
                    )
                      ? row.custom_branch_list
                      : []
                };
              })
              .filter(function (row) {
                return clean(row.name);
              })
              .sort(function (left, right) {
                return clean(left.label)
                  .localeCompare(clean(right.label));
              });

            void 0;

            populateLiveStaffSelects();
          } catch (error) {
            void 0;

            /*
             * Do not retry forbidden Employee Branches get_list calls.
             * Keep the form usable and surface a clear console message.
             */
            liveState.practitioners = [];
            populateLiveStaffSelects();

            if (
              typeof frappe !== "undefined" &&
              frappe &&
              typeof frappe.show_alert === "function"
            ) {
              frappe.show_alert(
                {
                  message:
                    "Unable to load branch practitioners. Check Server Script API: life_ops_branch_practitioners",
                  indicator: "red"
                },
                8
              );
            }
          }
        }

        function normalizeDesignation(value) {
        return clean(value)
          .toLowerCase()
          .replace(/[_\-]+/g, " ")
          .replace(/\s+/g, " ")
          .trim();
      }

      function practitionerMatchesDesignation(
        practitioner,
        requiredDesignation
      ) {
        if (!requiredDesignation) {
          return true;
        }

        var designation =
          normalizeDesignation(
            practitioner.designation
          );

        var required =
          normalizeDesignation(
            requiredDesignation
          );

        /*
         * Exact designation matching prevents
         * Physiotherapist from appearing under Therapist.
         */
        return designation === required;
      }

      function normalizePractitionerDesignation(value) {
        return String(value || "")
          .trim()
          .toLowerCase()
          .replace(/[_\-]+/g, " ")
          .replace(/\s+/g, " ");
      }

      function practitionerHasDesignation(
        practitioner,
        allowedDesignations
      ) {
        var currentDesignation =
          normalizePractitionerDesignation(
            practitioner.designation ||
            practitioner.department ||
            ""
          );

        if (!currentDesignation) {
          return false;
        }

        var allowed = (allowedDesignations || []).map(
          function (designation) {
            return normalizePractitionerDesignation(
              designation
            );
          }
        );

        /*
         * V49 — Therapist field:
         * Include Therapist/Senior Therapist and Dr/Doctor Assistant
         * designations even when LIFE uses small naming variations.
         * Never include Physiotherapist in the Therapist field.
         */
        var wantsTherapistOrDrAssistant = allowed.some(
          function (designation) {
            /*
             * "__THERAPIST_OR_DR_ASSISTANT__" is normalized by
             * normalizePractitionerDesignation() to:
             *     "therapist or dr assistant"
             *
             * V50 incorrectly compared against the un-normalized sentinel,
             * which made this special Therapist/Dr Assistant branch never run.
             */
            return designation ===
              "therapist or dr assistant";
          }
        );

        if (wantsTherapistOrDrAssistant) {
          var isPhysio =
            currentDesignation.indexOf("physio") !== -1;

          var isTherapist =
            !isPhysio &&
            currentDesignation.indexOf("therap") !== -1;

          var isDrAssistant =
            (
              currentDesignation.indexOf("assistant") !== -1 &&
              (
                currentDesignation.indexOf("doctor") !== -1 ||
                currentDesignation.indexOf("dr") !== -1
              )
            ) ||
            currentDesignation.indexOf("doctor assistant") !== -1 ||
            currentDesignation.indexOf("dr assistant") !== -1 ||
            currentDesignation.indexOf("dr.assistant") !== -1 ||
            currentDesignation.indexOf("dr. assistant") !== -1 ||
            currentDesignation.indexOf("assistant doctor") !== -1;

          return isTherapist || isDrAssistant;
        }

        if (
          allowed.some(function (designation) {
            return currentDesignation === designation;
          })
        ) {
          return true;
        }

        var wantsPhysiotherapist = allowed.some(
          function (designation) {
            return designation.indexOf("physio") !== -1;
          }
        );

        if (wantsPhysiotherapist) {
          return (
            currentDesignation.indexOf("physiotherapist") !== -1 ||
            currentDesignation.indexOf("physio therapist") !== -1
          );
        }

        var wantsTherapist = allowed.some(
          function (designation) {
            return designation.indexOf("therapist") !== -1;
          }
        );

        if (wantsTherapist) {
          return (
            currentDesignation.indexOf("therapist") !== -1 &&
            currentDesignation.indexOf("physio") === -1
          );
        }

        var wantsDoctor = allowed.some(
          function (designation) {
            return (
              designation.indexOf("doctor") !== -1 ||
              designation.indexOf("medical officer") !== -1 ||
              designation.indexOf("dermatologist") !== -1 ||
              designation.indexOf("physician") !== -1
            );
          }
        );

        if (wantsDoctor) {
          var isAssistantDoctor =
            currentDesignation.indexOf("assistant") !== -1;

          var isNonDoctorRole =
            currentDesignation.indexOf("therap") !== -1 ||
            currentDesignation.indexOf("physio") !== -1 ||
            currentDesignation.indexOf("diet") !== -1 ||
            currentDesignation.indexOf("manager") !== -1;

          if (isAssistantDoctor || isNonDoctorRole) {
            return false;
          }

          return (
            currentDesignation.indexOf("doctor") !== -1 ||
            currentDesignation.indexOf("consultant") !== -1 ||
            currentDesignation.indexOf("medical officer") !== -1 ||
            currentDesignation.indexOf("dermatologist") !== -1 ||
            currentDesignation.indexOf("physician") !== -1 ||
            currentDesignation.indexOf("cosmetologist") !== -1
          );
        }

        var wantsDietitian = allowed.some(
          function (designation) {
            return (
              designation.indexOf("diet") !== -1 ||
              designation.indexOf("detit") !== -1
            );
          }
        );

        if (wantsDietitian) {
          return (
            currentDesignation.indexOf("diet") !== -1 ||
            currentDesignation.indexOf("detit") !== -1
          );
        }

        return allowed.some(function (designation) {
          return currentDesignation.indexOf(designation) !== -1;
        });
      }

      function staffOptionsByDesignation(
        placeholder,
        allowedDesignations
      ) {
        var options = [
          '<option value="">' +
            escapeHtml(placeholder) +
          "</option>"
        ];

        liveState.practitioners
          .filter(function (practitioner) {
            return (
              practitionerMatchesClientBranch(
                practitioner
              ) &&
              practitionerHasDesignation(
                practitioner,
                allowedDesignations
              )
            );
          })
          .forEach(function (practitioner) {
            options.push(
              '<option value="' +
                escapeHtml(practitioner.name) +
              '" data-label="' +
                escapeHtml(practitioner.label) +
              '" data-designation="' +
                escapeHtml(practitioner.designation || "") +
              '">' +
                escapeHtml(practitioner.label) +
              "</option>"
            );
          });

        return options.join("");
      }

