      function ensureSearchableLiveStaffSelect(
        select,
        placeholder,
        allowedDesignations
      ) {
        if (!select) {
          return null;
        }

        ensureLiveStaffSearchStyles();

        var normalizedDesignations = Array.isArray(
          allowedDesignations
