              .filter(Boolean)
          : [];

        /*
         * V4.1.16:
         * The visible field is our own searchable textbox so the user sees
         * practitioner_name, while the hidden <select> continues storing the
         * Healthcare Practitioner document ID.
         *
         * IMPORTANT:
         * Search results are loaded from ERPNext's Healthcare Practitioner
         * Link search itself. We do not depend on designation being present in
         * the bulk get_list cache because many LIFE installations expose the
         * designation only through the Healthcare Practitioner link query.
         */
        if (
          select.__lifeSearchableStaff &&
          select.__lifeSearchableStaff.type ===
            "life-staff-server-search"
        ) {
          select.__lifeSearchableStaff.setConfiguration(
            placeholder,
            normalizedDesignations
          );
          select.__lifeSearchableStaff.syncFromSelect();
          return select.__lifeSearchableStaff;
        }

        if (select.__lifeSearchableStaff) {
          try {
            if (select.__lifeSearchableStaff.host) {
              select.__lifeSearchableStaff.host.remove();
            }
            if (
              select.__lifeSearchableStaff.control &&
              select.__lifeSearchableStaff.control.$wrapper
            ) {
              select.__lifeSearchableStaff.control.$wrapper.remove();
            }
          } catch (error) {

          }

          select.__lifeSearchableStaff = null;
        }

        var staleSibling = select.nextElementSibling;

        if (
          staleSibling &&
          staleSibling.classList &&
          (
            staleSibling.classList.contains(
              "lo-live-practitioner-link"
            ) ||
            staleSibling.classList.contains(
              "lo-live-staff-search"
            )
          )
        ) {
          staleSibling.remove();
        }

        var host = document.createElement("div");
        host.className =
          "lo-live-practitioner-link lo-live-staff-search";

        var input = document.createElement("input");
        input.type = "text";
        input.className =
          "form-control lo-live-staff-search-input";
        input.autocomplete = "off";
        input.spellcheck = false;

        var menu = document.createElement("div");
        menu.className = "lo-live-staff-search-menu";
        menu.hidden = true;

        host.appendChild(input);
        host.appendChild(menu);

        select.parentNode.insertBefore(
          host,
          select.nextSibling
        );

        select.style.display = "none";
        select.setAttribute("aria-hidden", "true");
        select.tabIndex = -1;

        var currentPlaceholder =
          clean(placeholder) ||
          "Search practitioner";

        var currentDesignations =
          normalizedDesignations.slice();

        var activeIndex = -1;
        var visibleRows = [];
        var syncing = false;
        var searchTimer = null;
        var requestToken = 0;

        function stripHtml(value) {
          return clean(
            String(value == null ? "" : value)
              .replace(/<[^>]*>/g, " ")
              .replace(/\s+/g, " ")
          );
        }

        function nameFromDescription(
          description,
          fallback
        ) {
          var value = stripHtml(description);

          if (!value) {
            return clean(fallback);
          }

          /*
           * LIFE Healthcare Practitioner search descriptions are normally:
           * "Mohd Mujeeb, 9703000308"
           * Only the person's name must remain visible after selection.
           */
          if (value.indexOf(",") !== -1) {
            value = clean(
              value.split(",")[0]
            );
          }

          return value || clean(fallback);
        }

        function localPractitionerById(value) {
          var practitionerId = clean(value);

          if (!practitionerId) {
            return null;
          }

          return (
            liveState.practitioners || []
          ).find(function (row) {
            return clean(row.name) ===
              practitionerId;
          }) || null;
        }

        function selectedOptionById(value) {
          var practitionerId = clean(value);

          if (!practitionerId) {
            return null;
          }

          return Array.prototype.find.call(
            select.options || [],
            function (option) {
              return clean(option.value) ===
                practitionerId;
            }
          ) || null;
        }

        function selectedLabel(value) {
          var practitionerId = clean(value);

          if (!practitionerId) {
            return "";
          }

          var localRow =
            localPractitionerById(
              practitionerId
            );

          if (
            localRow &&
            clean(localRow.label) &&
            clean(localRow.label) !==
              practitionerId
          ) {
            return clean(localRow.label);
          }

          var option =
            selectedOptionById(
              practitionerId
            );

          if (option) {
            var optionLabel = clean(
              option.dataset.label ||
              option.textContent
            );

            if (
              optionLabel &&
              optionLabel !== practitionerId
            ) {
              return optionLabel;
            }
          }

          return practitionerId;
        }

