        async function queryServer(searchText) {
          var query = clean(searchText)
            .toLowerCase();

          var fieldname = clean(
            select &&
            select.dataset &&
            select.dataset.liveField
          );

          function normalizedDesignation(doc) {
            return normalizePractitionerDesignation(
              (
                doc &&
                (
                  doc.designation ||
                  doc.department
                )
              ) ||
              ""
            );
          }

          function isDoctor(doc) {
            var designation =
              normalizedDesignation(doc);

            if (!designation) {
              return false;
            }

            if (
              designation.indexOf("assistant") !== -1 ||
              designation.indexOf("therap") !== -1 ||
              designation.indexOf("physio") !== -1 ||
              designation.indexOf("diet") !== -1 ||
              designation.indexOf("manager") !== -1
            ) {
              return false;
            }

            return (
              designation.indexOf("doctor") !== -1 ||
              designation.indexOf("consultant") !== -1 ||
              designation.indexOf("medical officer") !== -1 ||
              designation.indexOf("dermatologist") !== -1 ||
              designation.indexOf("physician") !== -1 ||
              designation.indexOf("cosmetologist") !== -1
            );
          }

          function isTherapist(doc) {
            var designation =
              normalizedDesignation(doc);

            if (!designation) {
              return false;
            }

            var compact = designation.replace(
              /[\s._-]+/g,
              ""
            );

            var isPhysio =
              designation.indexOf("physio") !== -1;

            var therapist =
              !isPhysio &&
              designation.indexOf("therap") !== -1;

            var doctorAssistant =
              compact.indexOf("drassistant") !== -1 ||
              compact.indexOf("doctorassistant") !== -1 ||
              compact.indexOf("assistantdoctor") !== -1;

            return therapist || doctorAssistant;
          }

          function isPhysiotherapist(doc) {
            var designation =
              normalizedDesignation(doc);

            return (
              designation.indexOf("physiotherapist") !== -1 ||
              designation.indexOf("physio therapist") !== -1
            );
          }

          function isDietitian(doc) {
            var designation =
              normalizedDesignation(doc);

            if (!designation) {
              return false;
            }

            var compact = designation.replace(
              /[\s._-]+/g,
              ""
            );

            return (
              designation.indexOf("diet") !== -1 ||
              designation.indexOf("detit") !== -1 ||
              designation === "cm" ||
              compact === "cm" ||
              designation === "acm" ||
              compact === "acm" ||
              designation.indexOf("center manager") !== -1 ||
              designation.indexOf("centre manager") !== -1 ||
              designation.indexOf("assistant center manager") !== -1 ||
              designation.indexOf("assistant centre manager") !== -1
            );
          }

          function designationMatchesField(doc) {
            if (fieldname === "doctor") {
              return isDoctor(doc);
            }

            if (fieldname === "therapist") {
              return isTherapist(doc);
            }

            if (fieldname === "physiotherapist") {
              return isPhysiotherapist(doc);
            }

            if (fieldname === "dietitian") {
              return isDietitian(doc);
            }

            return true;
          }

          return (liveState.practitioners || [])
            .filter(function (row) {
              if (
                !practitionerMatchesClientBranch(
                  row
                )
              ) {
                return false;
              }

              if (!designationMatchesField(row)) {
                return false;
              }

              if (!query) {
                return true;
              }

              var haystack = [
                row.label,
                row.practitioner_name,
                row.name,
                row.designation,
                row.department
              ]
                .map(function (value) {
                  return clean(value)
                    .toLowerCase();
                })
                .join(" ");

              return (
                haystack.indexOf(query) !== -1
              );
            })
            .map(function (row) {
              return {
                value: clean(row.name),
                name: clean(row.name),
                label:
                  clean(
                    row.label ||
                    row.practitioner_name
                  ) ||
                  clean(row.name),
                description:
                  clean(
                    row.designation ||
                    row.department
                  ),
                designation:
                  clean(
                    row.designation ||
                    row.department
                  )
              };
            })
            .sort(function (left, right) {
              return clean(left.label)
                .localeCompare(
                  clean(right.label)
                );
            })
            .slice(0, 100);
        }

        function localFallbackRows(searchText) {
          var query = clean(searchText)
            .toLowerCase();

          return (
            liveState.practitioners || []
          )
            .filter(function (practitioner) {
              return (
                practitionerMatchesClientBranch(
                  practitioner
                ) &&
                practitionerHasDesignation(
                  practitioner,
                  currentDesignations
                )
              );
            })
            .filter(function (practitioner) {
              if (!query) {
                return true;
              }

              return [
                practitioner.label,
                practitioner.name,
                practitioner.designation,
                practitioner.department
              ]
                .map(function (value) {
                  return clean(value)
                    .toLowerCase();
                })
                .some(function (value) {
                  return (
                    value.indexOf(query) !== -1
                  );
                });
            })
            .slice(0, 50)
            .map(function (row) {
              return {
                name: clean(row.name),
                label:
                  clean(row.label) ||
                  clean(row.name),
                description: "",
                designation:
                  clean(row.designation),
                department:
                  clean(row.department)
              };
            });
        }

        function closeMenu() {
          menu.hidden = true;
          menu.innerHTML = "";
          visibleRows = [];
          activeIndex = -1;
        }

        function renderLoading() {
          menu.innerHTML =
            '<div class="lo-live-staff-search-empty">' +
              "Loading staff..." +
            "</div>";

          menu.hidden = false;
        }

        function renderRows(rows) {
          visibleRows = Array.isArray(rows)
            ? rows
            : [];

          activeIndex = -1;

          if (!visibleRows.length) {
            menu.innerHTML =
              '<div class="lo-live-staff-search-empty">' +
                "No matching staff found" +
              "</div>";

            menu.hidden = false;
            return;
          }

          menu.innerHTML = visibleRows
            .map(function (
              practitioner,
              index
            ) {
              var meta = [
                practitioner.name,
                practitioner.description
              ]
                .map(function (value) {
                  return clean(value);
                })
                .filter(function (value, itemIndex, all) {
                  return (
                    value &&
                    all.indexOf(value) === itemIndex
                  );
                })
                .join(" · ");

              return (
                '<button type="button" ' +
                  'class="lo-live-staff-search-option" ' +
                  'data-staff-index="' +
                    index +
                  '">' +
                  '<span class="lo-live-staff-search-option-name">' +
                    escapeHtml(
                      practitioner.label ||
                      practitioner.name
                    ) +
                  "</span>" +
                  '<span class="lo-live-staff-search-option-meta">' +
                    escapeHtml(meta) +
                  "</span>" +
                "</button>"
              );
            })
            .join("");

          menu.hidden = false;
        }

        async function loadMenuRows(
          searchText
        ) {
          var thisToken =
            requestToken + 1;

          requestToken = thisToken;
          renderLoading();

          try {
            var rows =
              await queryServer(
                searchText
              );

            if (thisToken !== requestToken) {
              return;
            }

            /*
             * Keep a permission-safe fallback. If a custom Healthcare
             * Practitioner search is temporarily unavailable, use the already
             * loaded practitioner cache rather than leaving the field unusable.
             */
            if (!rows.length) {
              rows =
                localFallbackRows(
                  searchText
                );
            }

            renderRows(rows);
          } catch (error) {
            if (thisToken !== requestToken) {
              return;
            }

            window.__lifeOpsV4Debug &&
              void 0;

            renderRows(
              localFallbackRows(
                searchText
              )
            );
          }
        }

        function scheduleMenuLoad(
          searchText,
          immediate
        ) {
          if (searchTimer) {
            window.clearTimeout(
              searchTimer
            );
            searchTimer = null;
          }

          if (immediate) {
            loadMenuRows(searchText);
            return;
          }

          searchTimer =
            window.setTimeout(
              function () {
                searchTimer = null;
                loadMenuRows(
                  searchText
                );
              },
              180
            );
        }

        function updateActiveOption() {
          Array.prototype.forEach.call(
            menu.querySelectorAll(
              ".lo-live-staff-search-option"
            ),
            function (button, index) {
              button.classList.toggle(
                "is-active",
                index === activeIndex
              );
            }
          );

          var active =
            menu.querySelector(
              ".lo-live-staff-search-option.is-active"
            );

          if (active) {
            active.scrollIntoView({
              block: "nearest"
            });
          }
        }

        function ensureHiddenOption(
          value,
          label
        ) {
          var practitionerId = clean(value);
          var practitionerLabel =
            clean(label) ||
            practitionerId;

          if (!practitionerId) {
            return null;
          }

          var option =
            selectedOptionById(
              practitionerId
            );

          if (!option) {
            option =
              document.createElement(
                "option"
              );

            option.value =
              practitionerId;

            select.appendChild(
              option
            );
          }

          option.textContent =
            practitionerLabel;

          option.dataset.label =
            practitionerLabel;

          return option;
        }

        function choosePractitioner(
          practitioner
        ) {
          if (!practitioner) {
            return;
          }

          var value = clean(
            practitioner.name
          );

          var label = clean(
            practitioner.label ||
            practitioner.name
          );

          if (!value) {
            return;
          }

          ensureHiddenOption(
            value,
            label
          );

          syncing = true;
          select.value = value;
          input.value = label;
          syncing = false;

          closeMenu();

          select.dispatchEvent(
            new Event("change", {
              bubbles: true
            })
          );
        }

        async function resolveSelectedName(
          practitionerId
        ) {
          var value =
            clean(practitionerId);

          if (!value) {
            return;
          }

          try {
            var rows =
              await queryServer(value);

            var match =
              rows.find(function (row) {
                return clean(row.name) ===
                  value;
              }) ||
              rows[0] ||
              null;

            /*
             * If the filtered designation search does not return an already
             * selected value, read Healthcare Practitioner directly.
             */
            if (!match) {
              var doc = await callFrappe(
                "frappe.client.get_value",
                {
                  doctype:
                    "Healthcare Practitioner",
                  filters: {
                    name: value
                  },
                  fieldname: [
                    "name",
                    "practitioner_name"
                  ]
                }
              );

              if (doc) {
                match = {
                  name:
                    clean(doc.name) ||
                    value,
                  label:
                    clean(
                      doc.practitioner_name
                    ) ||
                    value
                };
              }
            }

            if (
              !match ||
              clean(select.value) !==
                value
            ) {
              return;
            }

            var label =
              clean(match.label) ||
              value;

            ensureHiddenOption(
              value,
              label
            );

            syncing = true;
            select.value = value;
            input.value = label;
            syncing = false;
          } catch (error) {
            window.__lifeOpsV4Debug &&
              void 0;
          }
        }

        function syncFromSelect() {
          var selectedValue =
            clean(select.value);

          syncing = true;

          input.value =
            selectedValue
              ? selectedLabel(
                  selectedValue
                )
              : "";

          syncing = false;

          if (
            selectedValue &&
            clean(input.value) ===
              selectedValue
          ) {
            resolveSelectedName(
              selectedValue
            );
          }
        }

        function setConfiguration(
          nextPlaceholder,
          nextDesignations
        ) {
          currentPlaceholder =
            clean(nextPlaceholder) ||
            "Search practitioner";

          currentDesignations =
            Array.isArray(nextDesignations)
              ? nextDesignations
                  .map(function (value) {
                    return clean(value);
                  })
                  .filter(Boolean)
              : [];

          input.placeholder =
            currentPlaceholder;

          input.setAttribute(
            "aria-label",
            currentPlaceholder
          );
        }

        input.addEventListener(
          "focus",
          function () {
            scheduleMenuLoad(
              input.value,
              true
            );
          },
          { signal: signal }
        );

        input.addEventListener(
          "input",
          function () {
            if (syncing) {
              return;
            }

            var selectedValue =
              clean(select.value);

            var oldLabel =
              selectedLabel(
                selectedValue
              );

            if (
              selectedValue &&
              clean(input.value) !==
                clean(oldLabel)
            ) {
              select.value = "";
            }

            scheduleMenuLoad(
              input.value,
              false
            );
          },
          { signal: signal }
        );

        input.addEventListener(
          "keydown",
          function (event) {
            if (
              event.key === "Escape"
            ) {
              closeMenu();
              return;
            }

            if (
              event.key ===
                "ArrowDown" ||
              event.key ===
                "ArrowUp"
            ) {
              event.preventDefault();

              if (
                menu.hidden ||
                !visibleRows.length
              ) {
                scheduleMenuLoad(
                  input.value,
                  true
                );
                return;
              }

              if (
                event.key ===
                  "ArrowDown"
              ) {
                activeIndex =
                  activeIndex >=
                    visibleRows.length - 1
                    ? 0
                    : activeIndex + 1;
              } else {
                activeIndex =
                  activeIndex <= 0
                    ? visibleRows.length - 1
                    : activeIndex - 1;
              }

              updateActiveOption();
              return;
            }

            if (
              event.key === "Enter"
            ) {
              if (
                activeIndex >= 0 &&
                visibleRows[
                  activeIndex
                ]
              ) {
                event.preventDefault();

                choosePractitioner(
                  visibleRows[
                    activeIndex
                  ]
                );
              } else if (
                visibleRows.length === 1
              ) {
                event.preventDefault();

                choosePractitioner(
                  visibleRows[0]
                );
              }
            }
          },
          { signal: signal }
