      /*
       * V56 STRICT STAFF SCOPE
       * ---------------------------------------------------------------
       * Session Entry staff is ALWAYS scoped to the selected client's branch.
       * The top dashboard filter may say "All Branches"; that must NOT widen
       * Therapist / Dr Assistant / Physiotherapist / Doctor / Dietitian lists.
       *
       * Healthcare Practitioner "Available All Branches" is intentionally
       * ignored here. A practitioner is shown only when the CLIENT'S branch
       * exists in the practitioner's main branch or Branch List fields/rows.
       */
      function currentLiveClientBranch() {
        return clean(
          (
            liveState.selectedPatient &&
            (
              liveState.selectedPatient.branch_name ||
              liveState.selectedPatient.custom_branch ||
              liveState.selectedPatient.branch
            )
          ) ||
          (
            liveState.selectedPlan &&
            liveState.selectedPlan.branch
          ) ||
          (
            liveState.selectedPlanRow &&
            liveState.selectedPlanRow.branch
          ) ||
          liveState.branch ||
          ""
        );
      }

      function practitionerMatchesClientBranch(practitioner) {
        if (!practitioner) {
          return false;
        }

        var clientBranch =
          currentLiveClientBranch();

        var wanted =
          normalizeLiveStaffBranch(
            clientBranch
          );

        if (!wanted) {
          /*
           * V56 STRICT RULE:
           * Never show unscoped staff when the client's branch is unknown.
           */
          return false;
        }

        function matches(value) {
          var raw = clean(value);

          if (!raw) {
            return false;
          }

          if (
            normalizeLiveStaffBranch(raw) ===
            wanted
          ) {
            return true;
          }

          return raw
            .split(/[\n,;|]+/)
            .map(function (item) {
              return normalizeLiveStaffBranch(
                item
              );
            })
            .filter(Boolean)
            .some(function (item) {
              return item === wanted;
            });
        }

        if (
          matches(practitioner.branch) ||
          matches(practitioner.custom_branch) ||
          matches(practitioner.branchListText) ||
          matches(practitioner.custom_branch_list_text) ||
          matches(practitioner.custom_additional_branches)
        ) {
          return true;
        }

        /*
         * V62 — child-table branch access.
         * Check every child table in Healthcare Practitioner, not only
         * custom_branch_list. This keeps staff visible when the client's branch
         * exists in any branch-assignment child table.
         */
        var branchFields = [
          "transfer_branch",
          "custom_transfer_branch",
          "branch",
          "branch_name",
          "custom_branch",
          "clinic_branch",
          "custom_clinic_branch",
          "assigned_branch",
          "custom_assigned_branch"
        ];

        return Object.keys(practitioner).some(function (key) {
          var rows = practitioner[key];

          if (!Array.isArray(rows)) {
            return false;
          }

          return rows.some(function (row) {
            if (!row || typeof row !== "object") {
              return false;
            }

            return branchFields.some(function (fieldname) {
              return matches(row[fieldname]);
            });
          });
        });
      }

