        async function checkClientFirstExecution(
          patientName,
          therapyPlan,
          therapyType,
          selectedRow
        ) {
          var clientName = clean(patientName);

          /*
           * V68 CONSENT RULE — CLIENT FIRST SESSION ONLY
           * ---------------------------------------------------------------
           * Consent is mandatory ONLY when this client has NEVER had a
           * submitted Therapy Session before.
           *
           * If the client already has even one submitted Therapy Session,
           * Consent is NOT mandatory again, even for another Therapy Plan.
           *
           * Draft Therapy Sessions do not count as completed execution.
           */
          if (!clientName) {
            return true;
          }

          var filters = [
            ["Therapy Session", "patient", "=", clientName],
            ["Therapy Session", "docstatus", "=", 1]
          ];

          try {
            var sessions = await callFrappe(
              "frappe.client.get_list",
              {
                doctype: "Therapy Session",
                fields: ["name"],
                filters: filters,
                order_by: "creation asc",
                limit_start: 0,
                limit_page_length: 1
              }
            );

            sessions = Array.isArray(sessions)
              ? sessions
              : [];

            return sessions.length === 0;
          } catch (error) {
            void 0;

            /*
             * Safe fallback: if history cannot be confirmed, do not allow a
             * possible first execution to bypass Consent.
             */
            return true;
          }
        }

