            liveState.fourDCryoSubmittedTodayCount = 0;
            liveState.fourDCryoRepeatToday = false;

            void 0;

            return 0;
          }
        }

        /*
         * LIFE Slimming execution sequence
         * --------------------------------
         * The sequence is CLIENT-WIDE across Slimming therapy types/plans.
         *
         * Required BMI/BMR sessions:
         *   1, 4, 8, 12, 16, 20, ...
         *
         * BP is optional on every session.
         *
         * IMPORTANT:
         * This helper is intentionally defined in the same outer scope as
         * syncTherapySessionMeasurementRequirements() because it is also used
         * by syncSlimmingMandatoryIndicators().  Do NOT declare it with
         * `var`/`let` inside another function.
         */
        function getSlimmingClientExecutionNumber() {
          if (!liveState || !liveState.isSlimming) {
            return 0;
          }

          var selected = liveState.selectedPlan || null;
          var selectedPlanName = clean(
            selected && (
              selected.planId ||
              selected.therapyPlan ||
              selected.planName ||
              selected.plan ||
              ""
            )
          );

          var completedTotal = 0;
          var seenPlans = Object.create(null);

          /*
           * Count completed executions from every Slimming plan currently
           * available for this client. This prevents the counter from
           * resetting when the same client has multiple Slimming therapy
           * types/plans.
           */
          (Array.isArray(liveState.planRows) ? liveState.planRows : [])
            .forEach(function (row) {
              if (!row || !isSlimmingTherapyPlan(row)) {
                return;
              }

              var planName = clean(
                row.planName ||
                row.planId ||
                row.therapyPlan ||
                row.plan ||
                ""
              );

              if (planName && seenPlans[planName]) {
                return;
              }

              if (planName) {
                seenPlans[planName] = true;
              }

              completedTotal += Math.max(
                0,
                Number(row.completed || 0)
              );
            });

          /*
           * The selected plan can sometimes be omitted from planRows after
           * its balance reaches zero. Make sure its completed count is still
           * included exactly once.
           */
          if (selected && selectedPlanName && !seenPlans[selectedPlanName]) {
            completedTotal += Math.max(
              0,
              Number(selected.completed || 0)
            );
          }

          /*
           * The selected plan is normally already included in planRows.
           * For a newly selected plan with no completed sessions, the next
           * client Slimming execution is therefore completedTotal + 1.
           */
          return completedTotal + 1;
        }

        function isEveryFourthSlimmingSession() {
          var sessionNumber = getSlimmingClientExecutionNumber();

          /*
           * User requirement:
           * - First Slimming execution: BMI + BMR mandatory.
           * - Then every 4th execution: 4, 8, 12, 16, ...
           * - BP remains optional for every execution.
           */
          return (
            sessionNumber === 1 ||
            (sessionNumber > 0 && sessionNumber % 4 === 0)
          );
        }

        /*
         * LIFE V92 — FIRST 4D CRYO EXECUTION MANDATORY FIELDS
         * ---------------------------------------------------------------
         * For the FIRST submitted 4D Cryo execution of the client on a date,
         * these fields are mandatory:
         *
         * - Before Weight
         * - After Weight
         * - Dietitian
         * - BMI
         * - Water
         * - Neck
         * - Fat %
         * - Tummy Region of Maximum Girth While Lying Down
         * - Thighs 9" Above the Outermost Edge of Bent Knees
         * - BMR
         * - Arms Midpoint Between Shoulder and Elbow
         * - Hip — Most Prominent Widest Part While Lying Down
         * - Waist 1" Above the Iliac Crest
         *
         * Repeat 4D Cryo executions for the same client on the same date do
         * not require these fields again.
         * Draft Therapy Sessions do not count as the first execution.
         * ---------------------------------------------------------------
         */
        var LIFE_FOUR_D_CRYO_FIRST_EXECUTION_REQUIRED_FIELDS = [
          "before_weight",
          "after_weight",
          "dietitian",
          "bmi",
          "water",
          "neck",
          "fat",
          "tummy_region_of_maximum_girth",
          "thighs_9",
          "bmr",
          "arms_mid_pt",
          "hip_most_prominent_widest_part_of_hipwhile_lying_down",
          "waist_1_above_the_iliac_crest"
        ];

        function isFourDCryoFirstExecutionRequiredField(fieldname) {
          return (
            LIFE_FOUR_D_CRYO_FIRST_EXECUTION_REQUIRED_FIELDS
              .indexOf(clean(fieldname)) !== -1
          );
        }

        function syncTherapySessionMeasurementRequirements() {
          hideLiveMachineUsedField();

          var meta = sessionMeta();

          if (!meta && liveState.selectedPlan) {
            loadSessionMeta()
              .then(function () {
                syncTherapySessionMeasurementRequirements();
              })
              .catch(function () {});
          }

          var doc = therapySessionMandatoryContext();
          var requirements = Object.create(null);
          var slimmingRequired = false;
          var bcaRequired = false;

          therapySessionMeasurementRules.forEach(function (rule) {
            var required = Boolean(
              liveState.selectedPlan &&
              isTherapySessionMeasurementRequired(rule, doc)
            );

            /*
             * LIFE Slimming rules for Website Session Entry:
             * 1. BP is optional on EVERY execution.
             * 2. The COMPLETE Slimming Measurements section is mandatory on
             *    execution 1 and every 4th execution: 1, 4, 8, 12, 16...
             * 3. This applies across the client's Slimming executions, even
             *    when the client has multiple Slimming Therapy Types/plans.
             * 4. Other Therapy Types continue to follow Therapy Session
             *    DocType mandatory/depends-on configuration.
             */
            var fourDCryoSelected = Boolean(
              liveState.selectedPlan &&
              isFourDCryoTherapyPlan(
                liveState.selectedPlan
              )
            );

            var fourDCryoRepeatToday = Boolean(
              fourDCryoSelected &&
              liveState.fourDCryoRepeatToday
            );

            var fourDCryoFirstToday = Boolean(
              fourDCryoSelected &&
              !liveState.fourDCryoRepeatToday
            );

            var slimmingCheckpoint = Boolean(
              liveState.selectedPlan &&
              liveState.isSlimming &&
              !fourDCryoSelected &&
              isEveryFourthSlimmingSession()
            );

            /*
             * STANDARD Slimming:
             * - BP optional every execution.
             * - Complete Slimming measurements mandatory on session 1 and
             *   every 4th execution.
             *
             * 4D CRYO OVERRIDE:
             * - First submitted 4D Cryo execution of the client/date:
             *   all Slimming measurements mandatory.
             * - Repeat 4D Cryo on same date:
             *   all Slimming measurements optional, including BP/BMI/BMR.
             */
            /* BP is optional; set the final requirement below after all overrides. */

            if (
              liveState.selectedPlan &&
              liveState.isSlimming &&
              !fourDCryoSelected &&
              slimmingCheckpoint &&
              rule.section === "slimming"
            ) {
              required = true;
            }

            /*
             * LIFE V92 — explicit first 4D Cryo mandatory fields.
             * Do not depend only on section metadata: the exact fields listed
             * by the business rule are enforced one-by-one.
             */
            if (
              fourDCryoFirstToday &&
              isFourDCryoFirstExecutionRequiredField(
                rule.live
              )
            ) {
              required = true;
            }

            /*
             * On repeat 4D Cryo executions on the same date, do not ask the
             * same measurements again. This includes the exact V92 list and
             * Body Composition fields.
             */
            if (
              fourDCryoRepeatToday &&
              (
                isFourDCryoFirstExecutionRequiredField(
                  rule.live
                ) ||
                rule.section === "bca"
              )
            ) {
              required = false;
            }

            /* Dermat/Skin/Hair/Laser must never require BCA on this page. */
            if (rule.section === "bca" && liveState.isDermat) {
              required = false;
            }

            if (rule.live === "blood_pressure") {
              required = false;
            }
            requirements[rule.live] = required;
            setLiveFieldMandatoryIndicator(rule.live, required);

            if (required && rule.section === "slimming") {
              slimmingRequired = true;
            }

            if (required && rule.section === "bca") {
              bcaRequired = true;
            }
          });

          liveState.measurementRequirements = requirements;

          var slimmingSection = qs('[data-role="live-slimming-fields"]');
          if (slimmingSection) {
            slimmingSection.hidden = !(
              liveState.selectedPlan &&
              (liveState.isSlimming || slimmingRequired)
            );

            var slimmingNote = slimmingSection.querySelector(
              ".lo-live-section-title small"
            );
            if (slimmingNote) {
              slimmingNote.textContent = liveState.isSlimming
                ? (
                    isFourDCryoTherapyPlan(liveState.selectedPlan)
                      ? (
                          liveState.fourDCryoRepeatToday
                            ? "Repeat 4D Cryo execution today for this Therapy Plan — first-execution measurements are optional"
                            : "FIRST 4D Cryo execution for this Therapy Plan today — all fields marked * below are mandatory"
                        )
                      : (
                          isEveryFourthSlimmingSession()
                            ? "Slimming Measurements are mandatory for this execution (Session 1 / every 4th session); BP is optional"
                            : "BP is optional; full Slimming Measurements are mandatory on Session 1 and every 4th session"
                        )
                  )
                : (slimmingRequired
                    ? "Mandatory fields follow Therapy Session rules for this Therapy Type"
                    : "Displayed for Slimming services");
            }
          }

          var bodyCompositionSection = qs(
            '[data-role="live-body-composition-section"]'
          );

          if (bodyCompositionSection) {
            bodyCompositionSection.hidden = Boolean(
              liveState.isDermat ||
              !liveState.selectedPlan ||
              (!liveState.isSlimming && !bcaRequired)
            );

            var bcaNote = bodyCompositionSection.querySelector(
              ".lo-live-section-title small"
            );
            if (bcaNote) {
              bcaNote.textContent = bcaRequired
                ? "Mandatory for this Therapy Type as configured in Therapy Session"
                : "Slimming services only; required fields follow Therapy Session rules";
            }
          }

          return requirements;
        }

        function validateTherapySessionMeasurementRequirements() {
          var requirements = syncTherapySessionMeasurementRequirements();

          for (
            var ruleIndex = 0;
            ruleIndex < therapySessionMeasurementRules.length;
            ruleIndex += 1
          ) {
            var rule = therapySessionMeasurementRules[ruleIndex];

            if (!requirements[rule.live]) {
              continue;
            }

            var value = getLiveField(rule.live);
            var missing = clean(value) === "";

            if (rule.numeric && !missing) {
              missing = numberValue(value) <= 0;
            }

            if (missing) {
              showError(
                rule.label +
                " is mandatory for " +
                (
                  getLiveField("therapy_type") ||
                  (liveState.selectedPlan && (
                    liveState.selectedPlan.therapyType ||
                    liveState.selectedPlan.service
                  )) ||
                  "this Therapy Type"
                ) +
                "."
              );
              return false;
            }
          }

          return true;
        }

        /* Backward-compatible name used by older parts of this build. */
        function syncSlimmingMandatoryIndicators() {
          return syncTherapySessionMeasurementRequirements();
        }

        // function isLiveDoctorRequired() {
