        function livePhotoFlagIsTrue(value) {
          if (
            value === true ||
            value === 1 ||
            value === "1"
          ) {
            return true;
          }

          var normalized =
            clean(value)
              .toLowerCase();

          return [
            "yes",
            "true",
            "required",
            "mandatory",
            "on"
          ].indexOf(normalized) !== -1;
        }

        function selectedLiveTherapyTypeDoc() {
          var row =
            liveState.selectedPlan ||
            {};

          var therapyType =
            clean(
              row.therapyType ||
              row.service ||
              getLiveField("therapy_type")
            );

          return (
            row.therapyDoc ||
            (
              therapyType &&
              liveState.therapyTypes &&
              liveState.therapyTypes[therapyType]
            ) ||
            {}
          );
        }

        function detectTherapyTypePhotoRequirement(
          photoKind
        ) {
          var doc =
            selectedLiveTherapyTypeDoc();

          var kind =
            clean(photoKind)
              .toLowerCase();

          if (
            !doc ||
            !kind
          ) {
            return false;
          }

          var opposite =
            kind === "before"
              ? "after"
              : "before";

          var explicitMatch = false;
          var combinedMatch = false;

          Object.keys(doc).forEach(
            function (fieldname) {
              if (
                explicitMatch ||
                !fieldname
              ) {
                return;
              }

              var key =
                String(fieldname)
                  .toLowerCase();

              var value =
                doc[fieldname];

              if (!livePhotoFlagIsTrue(value)) {
                return;
              }

              var hasPhotoWord =
                key.indexOf("photo") !== -1 ||
                key.indexOf("image") !== -1;

              var hasRequiredWord =
                key.indexOf("mandatory") !== -1 ||
                key.indexOf("required") !== -1 ||
                key.indexOf("reqd") !== -1;

              if (
                hasPhotoWord &&
                hasRequiredWord &&
                key.indexOf(kind) !== -1 &&
                key.indexOf(opposite) === -1
              ) {
                explicitMatch = true;
                return;
              }

              /*
               * Support one combined checkbox such as:
               * custom_before_after_photo_mandatory
               * custom_photos_required
               * custom_session_images_mandatory
               */
              if (
                hasPhotoWord &&
                hasRequiredWord &&
                (
                  (
                    key.indexOf("before") !== -1 &&
                    key.indexOf("after") !== -1
                  ) ||
                  (
                    key.indexOf("before") === -1 &&
                    key.indexOf("after") === -1
                  )
                )
              ) {
                combinedMatch = true;
              }
            }
          );

          return (
            explicitMatch ||
            combinedMatch
          );
        }

        function isHairCategoryTreatment() {
          var row =
            liveState.selectedPlan ||
            {};

          var therapyDoc =
            selectedLiveTherapyTypeDoc() ||
            {};

          /*
           * LIFE V85 PHOTO RULE:
           * -------------------------------------------------------------
           * BEFORE photo is mandatory ONLY for HAIR category treatments.
           *
           * Skin / Laser / Slimming / Cryo / Dermat / other categories:
           * BEFORE photo is optional.
           *
           * We check category/department/service-unit style fields only,
           * so a treatment name containing "hair" does not accidentally
           * make another category mandatory.
           * -------------------------------------------------------------
           */
          var categoryText = [
            row.category,
            row.department,
            row.serviceUnit,
            row.service_unit,
            therapyDoc.category,
            therapyDoc.custom_category,
            therapyDoc.medical_department,
            therapyDoc.department,
            therapyDoc.healthcare_service_unit,
            therapyDoc.service_unit
          ]
            .map(function (value) {
              return clean(value);
            })
            .filter(Boolean)
            .join(" ")
            .toLowerCase();

          return (
            categoryText === "hair" ||
            categoryText.indexOf("hair -") !== -1 ||
            categoryText.indexOf("hair treatment") !== -1 ||
            categoryText.indexOf("hair") !== -1
          );
        }

        /*
         * LIFE V85 PHOTO REQUIREMENT
         * ---------------------------------------------------------------
         * BEFORE:
         *   Mandatory ONLY for Hair category.
         *
         * AFTER:
         *   Keep the existing Therapy Type-specific configuration.
         *
         * This intentionally removes the old mandatory Before-photo rules
         * for Skin, Cryo/Slimming and Therapy Type-specific Before flags.
         * ---------------------------------------------------------------
         */
        function livePhotoRequirements() {
          return {
            before:
              isHairCategoryTreatment(),

            after:
              detectTherapyTypePhotoRequirement(
                "after"
              )
          };
        }

        function syncLivePhotoRequirements() {
          var requirements =
            livePhotoRequirements();

          var page = qs(
            '[data-page="live-session-entry"]'
          );

          if (!page) {
            return requirements;
          }

          var groupTitles =
            qsa(
