              ".lo-live-photo-group-title"
            );

          groupTitles.forEach(
            function (title) {
              var value =
                clean(
                  title.textContent
                ).toLowerCase();

              if (
                value.indexOf("before") !== -1
              ) {
                title.innerHTML =
                  requirements.before
