                    : 'BEFORE PHOTOS — 3 slots, optional';
              }

              if (
                value.indexOf("after") !== -1
              ) {
                title.innerHTML =
                  requirements.after
                    ? 'AFTER PHOTOS <span>*</span> — 3 slots, minimum 1 required'
                    : 'AFTER PHOTOS — 3 slots, optional';
              }
            }
          );

          var photoSection =
            groupTitles.length
              ? groupTitles[0].closest(
