            } else if (
              requirements.before
            ) {
              note.textContent =
                "Before photo is mandatory for Hair category; After photo is optional";
            } else if (
              requirements.after
            ) {
              note.textContent =
                "After photo is mandatory for this Therapy Type; Before photo is optional";
            } else {
              note.textContent =
                "Before and After photos are optional for this Therapy Type";
            }
          }

          return requirements;
        }

        function validateLiveSessionEntry() {
          if (!liveState.selectedPatient) {
            showError("Please select a client.");
            return false;
          }

          if (!liveState.selectedPlan) {
            showError("Please select a Therapy Plan.");
            return false;
          }

          /*
           * Never create an execution when the selected Therapy Plan has no
           * session balance left. This mirrors the Therapy Session / Therapy
           * Plan rule: completed sessions must not exceed the purchased total.
           * The dashboard normally hides zero-balance rows, but this second
           * check prevents a stale/open screen from saving an extra execution.
           */
          var selectedPlanForValidation = liveState.selectedPlan || {};
          var selectedTotalSessions = Math.max(
            0,
            numberValue(
              selectedPlanForValidation.total ??
              selectedPlanForValidation.total_sessions ??
              selectedPlanForValidation.totalSessions
            )
          );
          var selectedCompletedSessions = Math.max(
            0,
            numberValue(
              selectedPlanForValidation.completed ??
              selectedPlanForValidation.completed_sessions ??
              selectedPlanForValidation.completedSessions
            )
          );
          var selectedBalanceSessions = Math.max(
            0,
            numberValue(
              selectedPlanForValidation.balance ??
              selectedPlanForValidation.pending_sessions ??
              selectedPlanForValidation.remaining_sessions
            )
          );

          if (
            (selectedTotalSessions > 0 && selectedCompletedSessions >= selectedTotalSessions) ||
            selectedBalanceSessions <= 0
          ) {
            showError(
              "This Therapy Plan has no remaining sessions. Completed sessions cannot exceed the purchased session balance. The execution was not saved."
            );
            return false;
          }

          if (!getLiveField("branch")) {
            showError("Branch is mandatory.");
            return false;
          }

          if (!getLiveField("therapy_type")) {
            showError("Therapy Type is mandatory.");
            return false;
          }

          if (!getLiveField("service_unit")) {
            showError("Service Unit is mandatory.");
            return false;
          }

          if (!getLiveField("company")) {
            showError("Company is mandatory.");
            return false;
          }

          /*
           * Therapist is optional.
           * Doctor remains mandatory only where isLiveDoctorRequired() says so.
           */
          var requiredPractitionerFields = [];

          if (isLiveDoctorRequired()) {
            requiredPractitionerFields.push({
              fieldname: "doctor",
              label: "Doctor"
            });
          }

          for (
            var practitionerIndex = 0;
            practitionerIndex < requiredPractitionerFields.length;
            practitionerIndex += 1
          ) {
            var practitionerRequirement =
              requiredPractitionerFields[practitionerIndex];

            if (
              !getLiveField(
                practitionerRequirement.fieldname
              )
            ) {
              showError(
                "Please search and select " +
                practitionerRequirement.label +
                "."
              );
              return false;
            }
          }

          if (
            numberValue(
              getLiveField("duration")
            ) <= 0
          ) {
            showError(
              "Duration must be greater than zero."
            );
            return false;
          }

          if (!getLiveField("session_date")) {
            showError("Please select Session Date.");
            return false;
          }

          if (!getLiveField("in_time")) {
            showError("Please enter In Time.");
            return false;
          }

          if (liveState.firstExecution) {
            var consentInput = qs(
              '[data-live-field="consent_form"]'
            );

            if (
              !consentInput ||
              !consentInput.files ||
              !consentInput.files.length
            ) {
              showError(
                "Consent Form is mandatory for this client's first Therapy Session."
              );
              return false;
            }

            var consentFile =
              consentInput.files[0];

            var validConsentType =
              consentFile.type ===
                "application/pdf" ||
              (
                consentFile.type &&
                consentFile.type.indexOf(
                  "image/"
                ) === 0
              );

            if (!validConsentType) {
              showError(
                "Consent Form must be a PDF or image."
              );
              return false;
            }

            if (
              Number(consentFile.size || 0) >
              5 * 1024 * 1024
            ) {
              showError(
                "Consent Form must be 5 MB or smaller."
              );
              return false;
            }
          }

          var photoRequirements =
            syncLivePhotoRequirements();

          if (
            photoRequirements.before &&
            !hasSelectedSessionPhoto(
              "before"
            )
          ) {
            showError(
              "At least one Before photo is mandatory for Hair category treatments."
            );

            return false;
          }

          if (
            photoRequirements.after &&
            !hasSelectedSessionPhoto(
              "after"
            )
          ) {
            showError(
              "At least one After photo is mandatory for this Therapy Type."
            );

            return false;
          }
          var quantity = Math.max(
            1,
            Math.floor(
              numberValue(
                getLiveField("sessions_quantity")
              )
            )
          );

          if (!Number.isInteger(Number(getLiveField("sessions_quantity"))) || Number(getLiveField("sessions_quantity")) < 1) {
            showError("Sessions Qty must be a positive whole number.");
            return false;
