            showError(
              "Sessions Quantity must be 1. One submitted Therapy Session updates one completed session in the Therapy Plan."
            );
            return false;
          }

          if (
            quantity >
            liveState.selectedPlan.balance
          ) {
            showError(
              "Session Quantity cannot exceed the balance of " +
              liveState.selectedPlan.balance +
              "."
            );
            return false;
          }

          /* BP is optional. validateVitalReadings() still checks supplied values. */

          /*
           * LIFE: on Slimming execution 1 and every 4th execution, EVERY
           * field in the Slimming Measurements section is mandatory. The
           * requirement is enforced by validateTherapySessionMeasurementRequirements()
           * from the same client-wide sequence used for the red stars.
           */
          if (liveState.isSlimming && liveState.selectedPlan) {
            var checkpointSession = getSlimmingClientExecutionNumber();

            if (isEveryFourthSlimmingSession()) {
              for (
                var slimmingRuleIndex = 0;
                slimmingRuleIndex < therapySessionMeasurementRules.length;
                slimmingRuleIndex += 1
              ) {
                var slimmingRule = therapySessionMeasurementRules[slimmingRuleIndex];

                if (slimmingRule.section !== "slimming" || slimmingRule.live === "blood_pressure") {
                  continue;
                }

                var slimmingValue = clean(
                  getLiveField(slimmingRule.live)
                );
                var slimmingMissing = slimmingValue === "";

                if (slimmingRule.numeric && !slimmingMissing) {
                  slimmingMissing = numberValue(slimmingValue) <= 0;
                }

                if (slimmingMissing) {
                  showError(
                    slimmingRule.label +
                    " is mandatory for Slimming execution " +
                    checkpointSession +
                    ". All Slimming Measurements are required on Session 1 and every 4th session."
                  );
                  return false;
                }
              }
            }
          }

          if (!validateTherapySessionMeasurementRequirements()) {
            return false;
          }

          var beforeWeight = getLiveField(
            "before_weight"
          );

          var afterWeight = getLiveField(
            "after_weight"
          );

          if (
            beforeWeight &&
            numberValue(beforeWeight) <= 0
          ) {
            showError(
              "Before Weight must be greater than zero."
            );
            return false;
          }

          if (
            afterWeight &&
            numberValue(afterWeight) <= 0
          ) {
            showError(
              "After Weight must be greater than zero."
            );
            return false;
          }

          return validateVitalReadings();
        }

