        async function getExistingLiveSessionFiles(sessionName) {
          if (!sessionName) {
            return [];
          }

          try {
            var rows = await callFrappe(
              "frappe.client.get_list",
              {
                doctype: "File",
                fields: [
                  "name",
                  "file_name",
                  "file_url",
                  "creation"
                ],
                filters: {
                  attached_to_doctype: "Therapy Session",
                  attached_to_name: sessionName
                },
                order_by: "creation desc",
                limit_start: 0,
                limit_page_length: 100
              }
            );

            return Array.isArray(rows) ? rows : [];
          } catch (error) {
            window.__lifeOpsV4Debug && void 0;
            return [];
          }
        }

        async function uploadSessionPhotos(sessionName) {
          var inputs = qsa(
            '[data-page="live-session-entry"] [data-live-photo]'
          ).filter(function (input) {
            return (
              input.files &&
              input.files.length
            );
          });

          if (!inputs.length) {
            return [];
          }

          var existingFiles =
            await getExistingLiveSessionFiles(sessionName);

          return Promise.all(
            inputs.map(async function (input) {
              var originalFile = input.files[0];
              var photoKey = clean(
                input.dataset.livePhoto
              );

              var prefix = photoKey
                .replace(/-/g, "_")
                .toUpperCase();

              var expectedFileName =
                prefix + "_" + originalFile.name;

              /*
               * Retrying the same Draft must not attach the same BEFORE_1 /
               * AFTER_1 file again.
               */
              var existing = existingFiles.find(
                function (row) {
                  return (
                    clean(row.file_name) ===
                    clean(expectedFileName)
                  );
                }
              );

              if (
                existing &&
                clean(existing.file_url)
              ) {
                return {
                  key: photoKey,
                  kind:
                    photoKey.indexOf("after-") === 0
                      ? "after"
                      : "before",
                  file: clean(existing.file_url),
                  response: existing,
                  reused: true
                };
              }

              var renamedFile = originalFile;

              try {
                renamedFile = new File(
                  [originalFile],
                  expectedFileName,
                  {
                    type: originalFile.type,
                    lastModified:
                      originalFile.lastModified
                  }
                );
              } catch (error) {
                renamedFile = originalFile;
              }

              var formData = new FormData();
              formData.append("file", renamedFile);
              formData.append("is_private", "1");
              formData.append(
                "doctype",
                "Therapy Session"
              );
              formData.append(
                "docname",
                sessionName
              );
              formData.append("fieldname", "");

              var headers = {};

              try {
                if (
                  window.frappe &&
                  frappe.csrf_token
                ) {
                  headers["X-Frappe-CSRF-Token"] =
                    frappe.csrf_token;
                }
              } catch (error) {}

              var response = await fetch(
                "/api/method/upload_file",
                {
                  method: "POST",
                  headers: headers,
                  body: formData,
                  credentials: "same-origin"
                }
              );

              if (!response.ok) {
                throw new Error(
                  "Photo upload failed for " +
                  originalFile.name
                );
              }

              var responseJson =
                await response.json();

              var fileData =
                responseJson &&
                responseJson.message
                  ? responseJson.message
                  : responseJson;

              return {
                key: photoKey,
                kind:
                  photoKey.indexOf("after-") === 0
                    ? "after"
                    : "before",
                file:
                  fileData &&
                  (
                    fileData.file_url ||
                    fileData.file_name ||
                    fileData.name
                  ),
                response: fileData,
                reused: false
              };
            })
          );
        }

        function loadDoctypeMeta(doctype) {
