        function childPhotoAttachFields(meta, photoKind) {
          if (
            !meta ||
            !Array.isArray(meta.fields)
          ) {
            return [];
          }

          var kind = clean(photoKind).toLowerCase();
          var scored = [];

          function addCandidate(fieldname, score) {
            var name = clean(fieldname);

            if (!name) {
              return;
            }

            /* Only write fields that actually exist in the child DocType. */
            var exists = meta.fields.some(function (field) {
              return field && clean(field.fieldname) === name;
            });

            if (!exists) {
              return;
            }

            var existing = scored.find(function (item) {
              return item.fieldname === name;
            });

            if (existing) {
              existing.score = Math.max(existing.score, score || 0);
              return;
            }

            scored.push({
              fieldname: name,
              score: score || 0
            });
          }

          /*
           * LIFE fixed field mapping. These are the dedicated fields used by
           * the current Therapy Session setup when they exist. Prefer them
           * before heuristic metadata scoring so the After photo is visible
           * in the child table instead of only in Attachments.
           */
          if (kind === "after") {
            addCandidate("custom_after_image", 12000);
            addCandidate("after_image", 11900);
            addCandidate("attach_image", 11800);
          } else if (kind === "before") {
            addCandidate("attach_image", 12000);
            addCandidate("custom_before_image", 11900);
            addCandidate("before_image", 11800);
          }

          meta.fields.forEach(function (field) {
            if (!field || !field.fieldname) {
              return;
            }

            var fieldname = clean(field.fieldname);
            var lowerName = fieldname.toLowerCase();
            var label = clean(field.label).toLowerCase();
            var fieldtype = clean(field.fieldtype);
            var haystack = lowerName + " " + label;
            var score = 0;

            if (fieldtype === "Attach Image") {
              score += 1800;
            } else if (fieldtype === "Attach") {
              score += 1700;
            } else if (fieldtype === "Image") {
              score += 1500;
            } else if (
              fieldtype === "Data" ||
              fieldtype === "Small Text"
            ) {
              score += 350;
            }

            if (Number(field.reqd || 0) === 1) {
              score += 650;
            }

            if (Number(field.in_list_view || 0) === 1) {
              score += 350;
            }

            if (lowerName === "attach_image") {
              score += 2200;
            }

            if (
              haystack.indexOf("photo") !== -1 ||
              haystack.indexOf("image") !== -1 ||
              haystack.indexOf("picture") !== -1 ||
              haystack.indexOf("file") !== -1 ||
              haystack.indexOf("attachment") !== -1
            ) {
              score += 850;
            }

            if (kind && haystack.indexOf(kind) !== -1) {
              score += 1100;
            }

            var looksLikePhotoStorage =
              fieldtype === "Attach" ||
              fieldtype === "Attach Image" ||
              fieldtype === "Image" ||
              lowerName === "attach_image" ||
              lowerName === "image" ||
              lowerName === "photo" ||
              lowerName === "file" ||
              lowerName === "file_url" ||
              haystack.indexOf("photo") !== -1 ||
              haystack.indexOf("image") !== -1 ||
              haystack.indexOf("picture") !== -1 ||
              haystack.indexOf("attachment") !== -1 ||
              (kind && haystack.indexOf(kind) !== -1 &&
                (fieldtype === "Data" || fieldtype === "Small Text"));

            if (looksLikePhotoStorage && fieldtype !== "Image") {
              addCandidate(fieldname, score);
            }

            /*
             * A Frappe Image control normally displays the value stored in
             * the field named in Options. Save the URL into that backing
             * field so the image is visible in the child row, not only in
             * the Attachments sidebar.
             */
            if (
              fieldtype === "Image" &&
              clean(field.options)
            ) {
              addCandidate(clean(field.options), 2600 + score);
            }
          });

          scored.sort(function (a, b) {
            return b.score - a.score;
          });

          return scored.map(function (item) {
            return item.fieldname;
          });
        }

        function sessionTableConfig(fieldname, fallbackDoctype) {
          var meta = sessionMeta();
          var field = null;

          if (meta && Array.isArray(meta.fields)) {
            field = meta.fields.find(function (row) {
              return row && row.fieldname === fieldname;
            }) || null;
          }

          return {
            fieldname: fieldname,
            doctype:
              field && clean(field.options)
                ? clean(field.options)
                : fallbackDoctype
          };
        }

        function findConsentAttachField(meta) {
          if (!meta || !Array.isArray(meta.fields)) {
            return "";
          }

          function getField(fieldname) {
            return meta.fields.find(function (field) {
              return field && field.fieldname === fieldname;
            }) || null;
          }

          function usableBackingField(field) {
            if (!field) {
              return "";
            }

            var type = clean(field.fieldtype);
            var options = clean(field.options);

            /*
             * Frappe Image fields usually display the value stored in the
             * field named in Options. Use that backing Attach/Attach Image
             * field so the image is visible in the Therapy Session DocType.
             */
            if (type === "Image" && options) {
              var backing = getField(options);
              if (backing) {
                return clean(backing.fieldname);
              }
              return options;
            }

            if (type === "Attach" || type === "Attach Image") {
              return clean(field.fieldname);
            }

            return "";
          }

