            ).filter(function (input) {
              return input.files && input.files.length;
            });

            if (submitButton) {
              submitButton.textContent = "Uploading Session Files...";
            }

            /*
             * Consent and Before/After images upload in parallel.
             */
            var uploadResults = await lifeOpsExecutionTimeout(
              Promise.all([
                liveState.firstExecution
                  ? uploadLiveConsentForm(saved.name)
                  : Promise.resolve(null),
                photoInputs.length
                  ? uploadSessionPhotos(saved.name)
                  : Promise.resolve([])
              ]),
              60000,
              "Uploading session photos/files"
            );

            var consentUpload = uploadResults[0] || null;
            var uploaded = uploadResults[1] || [];

            if (uploaded.length || consentUpload) {
              if (submitButton) {
                submitButton.textContent = "Linking Session Files...";
              }

              var linkedSessionDoc =
                await lifeOpsExecutionTimeout(
                  saveSessionFileLinks(
                    saved.name,
                    consentUpload,
                    uploaded
                  ),
                  30000,
                  "Linking session photos/files"
                );

              if (
                linkedSessionDoc &&
                linkedSessionDoc.name
              ) {
                saved =
                  linkedSessionDoc;
              }
            }

            /*
             * Remember the latest server copy so appointment -> submit can
             * submit it directly without another reload.
             */
            rememberPendingDraftSession(saved);

            var remainingBalance = remainingBalanceAfterCurrentSession();

            /*
             * LIFE V90:
             * For repeat 4D therapy sessions today, refresh the already-booked
             * future appointment immediately before the mandatory check.
             */
            if (
              remainingBalance > 0 &&
              isFourDCryoRepeatSameDay() &&
              !clean(liveState.nextAppointmentName)
            ) {
              await refreshExistingNextAppointmentForFourDCryo();
            }

            /*
             * STEP 2 — If sessions remain, Next Appointment is mandatory.
             * The execution stays Draft until that appointment is booked.
             */
            if (
              remainingBalance > 0 &&
              !clean(liveState.nextAppointmentName)
            ) {
              liveState.awaitingNextAppointmentForDraft = true;
              setDraftWaitingUi();

              showAlert(
                "Therapy Session " +
                  saved.name +
                  " saved as Draft. Book the required Next Appointment to submit it.",
                "orange"
              );

              if (!liveState.bookingOpening) {
                liveState.bookingOpening = true;

                try {
                  ensureAppointmentAboveExecutionPopup();
                  await lifeOpsExecutionTimeout(
                    openLiveAppointmentBooking({
                      skipExistingAppointmentValidation: true
                    }),
                    30000,
                    "Opening Next Appointment"
                  );
                } finally {
                  liveState.bookingOpening = false;
                }
              }

              return;
            }

            /*
             * Last session, or the next appointment was already booked:
             * submit the saved Draft immediately.
             */
            if (submitButton) {
              submitButton.textContent = "Submitting Session...";
            }

            var submitted = await submitDraftTherapySession(
              saved,
              submitButton
            );

            await finishSuccessfulLiveSession(saved, submitted);
          } catch (error) {
            void 0;

            var errorMessage =
              error && error.message
                ? String(error.message)
                : "Therapy Session could not be saved.";

            /*
             * LIFE FIX — SERVER REQUIRES NEXT APPOINTMENT
             * -------------------------------------------------------------
             * The custom life_slimming before_submit hook can reject with:
             * "Please Take Next Appointment of Client ..."
             *
             * When that happens:
             * 1. Keep/reuse the same Therapy Session Draft.
             * 2. Do not create another Therapy Session.
             * 3. Open the Next Appointment popup automatically.
             * 4. After appointment booking, submit the same Draft.
             */
            var nextAppointmentRequired =
              /Please\s+Take\s+Next\s+Appointment/i.test(
                errorMessage
              ) ||
              /Take\s+Next\s+Appointment/i.test(
                errorMessage
              ) ||
              /Next\s+Appointment.*required/i.test(
                errorMessage
              );

            if (nextAppointmentRequired) {
              if (
                typeof saved !== "undefined" &&
                saved &&
                saved.name
              ) {
                rememberPendingDraftSession(saved);
              }

              liveState.nextAppointmentName = "";
              liveState.nextAppointmentDate = "";
              liveState.nextAppointmentTime = "";
              liveState.awaitingNextAppointmentForDraft = true;

              setDraftWaitingUi();

              showAlert(
                (
                  typeof saved !== "undefined" &&
                  saved &&
                  saved.name
                    ? "Therapy Session " +
                      saved.name +
                      " is saved as Draft. "
                    : ""
                ) +
                "Please book the Next Appointment to continue.",
                "orange"
              );

              if (!liveState.bookingOpening) {
                liveState.bookingOpening = true;

                try {
                  ensureAppointmentAboveExecutionPopup();

                  await lifeOpsExecutionTimeout(
                    openLiveAppointmentBooking({
                      skipExistingAppointmentValidation: true
                    }),
                    30000,
                    "Opening Next Appointment"
                  );
                } catch (appointmentError) {
                  void 0;

                  showError(
                    appointmentError &&
                    appointmentError.message
                      ? appointmentError.message
                      : "Could not open Next Appointment. Please click Book Next Appointment."
                  );
                } finally {
                  liveState.bookingOpening = false;
                }
              }

              return;
            }

            /*
             * ERPNext server-side overlap message -> friendly UI message.
             */
            if (
              /Therapy Session overlaps with/i.test(
                errorMessage
              )
            ) {
              var idMatch =
                errorMessage.match(
                  /HLC-THP-[0-9A-Za-z-]+/
                );

              errorMessage =
                "This Therapy Session overlaps an existing session" +
                (
                  idMatch &&
                  idMatch[0]
                    ? " (" +
                      idMatch[0] +
                      ")"
                    : ""
                ) +
                ". Change the In Time or select a practitioner who is free. The execution was not submitted.";
            }

            if (pendingDraftExists()) {
              setDraftWaitingUi();
            } else {
              resetLiveSessionSubmitState(
                submitButton,
                card
              );
            }

            if (
              /taking too long/i.test(
                errorMessage
              )
            ) {
              errorMessage +=
                " The loading state has been cleared. If a Draft was already created, reopen this client and continue from that Draft instead of clicking repeatedly.";
            }

            showError(
              errorMessage
            );
          } finally {
            liveState.submitting = false;

            if (card) {
              card.classList.remove("is-submitting");
              card.removeAttribute("aria-busy");
            }

            if (submitButton) {
              submitButton.disabled = false;
              submitButton.removeAttribute("aria-busy");

              if (pendingDraftExists()) {
                submitButton.textContent = clean(liveState.nextAppointmentName)
                  ? "✅ Submit Saved Draft"
                  : "📅 Draft Saved — Book Next Appointment";
              } else if (!card || !card.classList.contains("is-completed")) {
                submitButton.textContent = "✅ Submit Session Entry";
              }
            }
          }
        }

