        function previewLivePhoto(input) {
          if (
            !input ||
            !input.files ||
            !input.files.length
          ) {
            return;
          }

          var file = input.files[0];
          var selectedPhotoKey = clean(
            input.dataset.livePhoto
          );

          var selectedSignature =
            sessionPhotoQuickSignature(file);

          var duplicateInput = selectedSessionPhotoInputs().find(
            function (otherInput) {
              if (otherInput === input) {
                return false;
              }

              var otherKey = clean(
                otherInput.dataset.livePhoto
              );

              if (otherKey === selectedPhotoKey) {
                return false;
              }

              return (
                otherInput.files &&
                otherInput.files.length &&
                sessionPhotoQuickSignature(
                  otherInput.files[0]
                ) === selectedSignature
              );
            }
          );

          if (duplicateInput) {
            input.value = "";
            showError(
              "Duplicate session photo is not allowed. Please use a different photo for each slot."
            );
            return;
          }

          /*
           * A slot has one gallery input and one camera input.
           * Keep only the most recently selected source.
           */
          qsa(
            '[data-page="live-session-entry"] [data-live-photo]'
          ).forEach(function (otherInput) {
            if (
              otherInput !== input &&
              clean(otherInput.dataset.livePhoto) ===
                selectedPhotoKey
            ) {
              otherInput.value = "";
            }
          });

          if (
            !file.type ||
            file.type.indexOf("image/") !== 0
          ) {
            input.value = "";
            showError("Only image files are allowed.");
            return;
          }

          if (file.size > 5 * 1024 * 1024) {
            input.value = "";
            showError(
              "Each image must be 5 MB or smaller."
            );
            return;
          }

          var slot = input.closest(
            ".lo-live-photo-slot"
          );

          if (!slot) {
            return;
          }

          var existing = slot.querySelector("img");

          if (existing) {
            if (existing.src && existing.src.indexOf("blob:") === 0) {
              try {
                URL.revokeObjectURL(existing.src);
              } catch (error) {}
            }
            existing.remove();
          }

          var existingRemoveButton = slot.querySelector(
            ".lo-live-photo-remove"
          );

          if (existingRemoveButton) {
            existingRemoveButton.remove();
          }

          var image = document.createElement("img");
          image.alt = "Session photo";
          image.src = URL.createObjectURL(file);

          slot.appendChild(image);
          slot.classList.add(
            "has-file",
            "has-preview"
          );
          slot.setAttribute(
            "data-photo-label",
            file.name
          );

          addLivePhotoRemoveButton(
            slot,
            selectedPhotoKey
          );
        }

