        async function resolveLiveLoginBranch() {
          var branch =
            typeof window.lifeOpsGetLoggedEmployeeBranch === "function"
              ? await window.lifeOpsGetLoggedEmployeeBranch()
              : "";

          if (!branch && liveState.branch) {
            branch = liveState.branch;
          }

          if (
            branch &&
            typeof window.lifeOpsIsExcludedBranch === "function" &&
            window.lifeOpsIsExcludedBranch(branch)
          ) {
            branch = "";
          }

          if (!branch) {
            branch = getLoginBranch();
          }

          if (
            branch &&
            typeof window.lifeOpsIsExcludedBranch === "function" &&
            window.lifeOpsIsExcludedBranch(branch)
          ) {
            branch = "";
          }

          if (!branch) {
            try {
              var user =
                window.frappe &&
                frappe.session
                  ? clean(frappe.session.user)
                  : "";

              if (user) {
                var rows = await callFrappe(
                  "frappe.client.get_list",
                  {
                    doctype: "Employee",
                    fields: [
                      "name",
                      "branch"
                    ],
                    filters: [
                      [
                        "Employee",
                        "user_id",
                        "=",
                        user
                      ],
                      [
                        "Employee",
                        "status",
                        "=",
                        "Active"
                      ]
                    ],
                    order_by: "modified desc",
                    limit_start: 0,
                    limit_page_length: 1
                  }
                );

                rows = Array.isArray(rows)
                  ? rows
                  : [];

                branch =
                  rows.length
                    ? clean(rows[0].branch)
                    : "";

                if (
                  typeof window.lifeOpsIsExcludedBranch === "function" &&
                  window.lifeOpsIsExcludedBranch(branch)
                ) {
                  branch = "";
                }
              }
            } catch (error) {

            }
          }

          if (!branch) {
            return "";
          }

          liveState.branch = branch;
          populateLiveBranch();

          var select = qs(
            '[data-role="live-session-branch"]'
          );

          if (select) {
            select.value = branch;
            select.disabled = true;
            select.title =
              "Branch is fixed from the logged-in Employee.";
          }

          return branch;
        }

        async function uploadClientPhoto(sourceInput) {
          var input =
            sourceInput ||
            qs(
              '[data-role="live-client-photo-input"]'
            );

          if (
            !input ||
            !input.files ||
            !input.files.length ||
            !liveState.selectedPatient
          ) {
            return;
          }

          var file = input.files[0];

          if (
            !file.type ||
            file.type.indexOf("image/") !== 0
          ) {
            input.value = "";
            showError("Only image files are allowed.");
            return;
          }

          if (file.size > 5 * 1024 * 1024) {
            input.value = "";
            showError(
              "Client photo must be 5 MB or smaller."
            );
            return;
          }

          try {
            var formData = new FormData();
            formData.append("file", file);
            formData.append("is_private", "1");
            formData.append("doctype", "Patient");
            formData.append(
              "docname",
              liveState.selectedPatient.name
            );
            formData.append(
              "fieldname",
              "custom_client_photo_attach"
            );

            var headers = {};

            if (
              window.frappe &&
              frappe.csrf_token
            ) {
              headers["X-Frappe-CSRF-Token"] =
                frappe.csrf_token;
            }

            var response = await fetch(
              "/api/method/upload_file",
              {
                method: "POST",
                headers: headers,
                body: formData,
                credentials: "same-origin"
              }
            );

            if (!response.ok) {
              throw new Error(
                "Client photo upload failed."
              );
            }

            var json = await response.json();
            var fileData =
              json && json.message
                ? json.message
                : json;

            var fileUrl =
              fileData &&
              (
                fileData.file_url ||
                fileData.file_name
              );

            if (!fileUrl) {
              throw new Error(
                "Uploaded client photo URL was not returned."
              );
            }

            await callFrappe(
              "frappe.client.set_value",
              {
                doctype: "Patient",
                name:
                  liveState.selectedPatient.name,
                fieldname:
                  "custom_client_photo_attach",
                value: fileUrl
              }
            );

            liveState.selectedPatient
              .custom_client_photo_attach =
