              linkedMap.set(appointmentName, session);
            }

            if (sessionDate(session) !== date) {
              return;
            }

            var patientKey = normalize(sessionPatient(session));
            if (!patientKey) {
              return;
            }

            if (!sessionsByPatient.has(patientKey)) {
              sessionsByPatient.set(patientKey, []);
            }
            sessionsByPatient.get(patientKey).push(session);
