          var usedSessions = new Set();
          var results = appointments.map(function (appointment) {
            var session = linkedMap.get(clean(appointment.name)) || null;
            if (session) {
              usedSessions.add(clean(session.name));
            }

            return {
              appointment: appointment,
              session: session,
              entered: Boolean(session)
