          /*
           * Search only sessions belonging to the same client. This replaces the
           * former appointments × all-sessions scan that became expensive after
           * data had finished loading.
           */
          results.forEach(function (item) {
            if (item.entered) {
              return;
            }

            var patientKey = normalize(
              appointmentPatient(item.appointment)
            );
            var candidates = sessionsByPatient.get(patientKey) || [];
            var appointmentType = normalize(
              appointmentService(item.appointment)
            );
            var fallback = null;

            for (var index = 0; index < candidates.length; index += 1) {
              var candidate = candidates[index];
              var candidateName = clean(candidate.name);

              if (usedSessions.has(candidateName)) {
                continue;
              }

              var sessionType = normalize(candidate.therapy_type);
              if (
                !appointmentType ||
                !sessionType ||
                appointmentType === sessionType
              ) {
                fallback = candidate;
                break;
              }
            }

            if (fallback) {
              item.session = fallback;
              item.entered = true;
              usedSessions.add(clean(fallback.name));
            }
          });

