          .life-ops-dashboard .lo-book-search-option:last-child{border-bottom:0;}
          .life-ops-dashboard .lo-book-search-option:hover,.life-ops-dashboard .lo-book-search-option.is-active{background:#edf9f4;}
          .life-ops-dashboard .lo-book-search-option strong{display:block;color:#064e3b;font-size:13px;line-height:1.35;}
          .life-ops-dashboard .lo-book-search-option span{display:block;margin-top:3px;color:#607089;font-size:11px;line-height:1.4;white-space:normal;}
