        `;
        dashboard.appendChild(style);
      }

      function createSearchField(select, type) {
        if (!select || select.dataset.searchableBookingReady === "1") return;
        select.dataset.searchableBookingReady = "1";
        select.style.setProperty("display", "none", "important");

        var wrap = document.createElement("div");
        wrap.className = "lo-book-search-wrap";
        wrap.dataset.bookingSearchType = type;

        var input = document.createElement("input");
        input.type = "text";
        input.autocomplete = "off";
        input.className = "lo-book-search-input";
        input.placeholder = type === "plan"
          ? "Search Therapy Plan..."
          : "Search Therapy Type / Concern...";

        var arrow = document.createElement("span");
        arrow.className = "lo-book-search-arrow";
        arrow.textContent = "▼";

        var menu = document.createElement("div");
        menu.className = "lo-book-search-menu";

        wrap.appendChild(input);
        wrap.appendChild(arrow);
        wrap.appendChild(menu);
        select.insertAdjacentElement("afterend", wrap);

        var visibleOptions = [];
        var activeIndex = -1;

        function availableOptions() {
          return Array.from(select.options || []).filter(function (opt) {
            return clean(opt.value);
          });
        }

        function syncFromSelect() {
          input.disabled = Boolean(select.disabled);
          var selectedValue = clean(select.value);
          var chosen = selectedValue
            ? Array.from(select.options || []).find(function (opt) {
                return clean(opt.value) === selectedValue;
              })
            : null;

          /* Never copy native placeholder options such as
             “Select Therapy Plan” or “Select Therapy Plan first”
             into the visible searchable input. */
          input.value = chosen
            ? (type === "plan"
                ? compactPlanLabel(chosen)
                : clean(chosen.textContent).split(" — ")[0])
            : "";

          input.placeholder = type === "plan"
            ? "Search Therapy Plan..."
            : "Search Therapy Type / Concern...";
        }

        /* Allow the appointment data loader to refresh this visible field
           after programmatic option/value updates. */
        select.__lifeOpsSyncBookingSearch = syncFromSelect;

        function render(query) {
          var q = clean(query).toLowerCase();
          var options = availableOptions().filter(function (opt) {
            var haystack = [opt.value, opt.textContent, opt.title].join(" ").toLowerCase();
            return !q || haystack.indexOf(q) !== -1;
          });
          visibleOptions = options;
          activeIndex = options.length ? 0 : -1;

          if (!options.length) {
            menu.innerHTML = '<div class="lo-book-search-empty">No matching options found</div>';
          } else {
            menu.innerHTML = options.map(function (opt, index) {
              var main = type === "plan" ? clean(opt.value) : clean(opt.textContent).split(" — ")[0];
              var description = optionDescription(opt, type);
              return '<div class="lo-book-search-option' + (index === 0 ? ' is-active' : '') + '" data-index="' + index + '">' +
                '<strong>' + escapeHtml(main) + '</strong>' +
                (description && description !== main ? '<span>' + escapeHtml(description) + '</span>' : '') +
                '</div>';
            }).join("");
          }
          menu.classList.add("is-open");
        }

        function choose(index) {
          var option = visibleOptions[index];
          if (!option) return;
          select.value = option.value;
          input.value = type === "plan"
            ? compactPlanLabel(option)
            : clean(option.textContent).split(" — ")[0];
          menu.classList.remove("is-open");
          select.dispatchEvent(new Event("change", { bubbles: true }));
          input.dispatchEvent(new Event("change", { bubbles: true }));
        }

        input.addEventListener("focus", function () {
          if (input.disabled) return;
          /* A selected label may remain visible, but opening the field should
             show the available choices instead of filtering only by that label. */
          render(select.value ? "" : input.value);
        }, { signal: signal });

        input.addEventListener("input", function () {
          select.value = "";
          render(input.value);
        }, { signal: signal });


        input.addEventListener("blur", function () {
          window.setTimeout(function () {
            if (menu.matches(":hover")) return;
            menu.classList.remove("is-open");
            if (!clean(select.value)) {
              input.value = "";
            } else {
              syncFromSelect();
            }
          }, 180);
        }, { signal: signal });

        input.addEventListener("keydown", function (event) {
          if (!menu.classList.contains("is-open")) return;
          if (event.key === "ArrowDown" || event.key === "ArrowUp") {
            event.preventDefault();
            if (!visibleOptions.length) return;
            activeIndex += event.key === "ArrowDown" ? 1 : -1;
            if (activeIndex < 0) activeIndex = visibleOptions.length - 1;
            if (activeIndex >= visibleOptions.length) activeIndex = 0;
            menu.querySelectorAll(".lo-book-search-option").forEach(function (node, index) {
              node.classList.toggle("is-active", index === activeIndex);
            });
          } else if (event.key === "Enter") {
            event.preventDefault();
            choose(activeIndex);
          } else if (event.key === "Escape") {
            menu.classList.remove("is-open");
          }
        }, { signal: signal });

        menu.addEventListener("pointerdown", function (event) {
          var optionNode = event.target.closest(".lo-book-search-option");
          if (!optionNode) return;
          event.preventDefault();
          event.stopPropagation();
          choose(Number(optionNode.dataset.index));
        }, { signal: signal });

        document.addEventListener("pointerdown", function (event) {
          if (!wrap.contains(event.target)) menu.classList.remove("is-open");
        }, { signal: signal });

        select.addEventListener("change", syncFromSelect, { signal: signal });

        var observer = new MutationObserver(function () {
          syncFromSelect();
          if (menu.classList.contains("is-open")) render(input.value);
        });
        observer.observe(select, { childList: true, subtree: true, attributes: true, attributeFilter: ["disabled"] });
        signal.addEventListener("abort", function () { observer.disconnect(); }, { once: true });

        syncFromSelect();
      }

      function initialize() {
        addStyles();
        var plan = dashboard.querySelector('[data-book-field="therapy_plan"]');
        var concern = dashboard.querySelector('[data-book-field="concern"]');
        createSearchField(plan, "plan");
        createSearchField(concern, "concern");
      }

      initialize();

      var rootObserver = new MutationObserver(initialize);
      rootObserver.observe(dashboard, { childList: true, subtree: true });
      signal.addEventListener("abort", function () { rootObserver.disconnect(); }, { once: true });
    })();

  }

  function scheduleLifeOpsWebStart() {
    if (document.readyState === "loading") {
      document.addEventListener(
        "DOMContentLoaded",
        lifeOpsStartWebPage,
        { once: true }
      );
    } else {
      lifeOpsStartWebPage();
    }
  }

  window.addEventListener(
    "pagehide",
    function () {
      if (lifeOpsWebRetryTimer) {
        window.clearTimeout(lifeOpsWebRetryTimer);
        lifeOpsWebRetryTimer = null;
      }
    },
    { once: true }
  );

  scheduleLifeOpsWebStart();
})();

