      }
      var key=media.toLowerCase();
      var aliases={"unjoined":"DIRECT WALKIN","un joined":"DIRECT WALKIN","walk in":"DIRECT WALKIN","walk-in":"DIRECT WALKIN","walkin":"DIRECT WALKIN","direct walk in":"DIRECT WALKIN","direct walk-in":"DIRECT WALKIN","direct walkin":"DIRECT WALKIN"};
      var target=aliases[key]||"DIRECT WALKIN";
      var targetValid=await call("frappe.client.get_count",{doctype:"Lead Source",filters:[["Lead Source","name","=",target]]});
      if(Number(targetValid||0)<=0) throw new Error("Lead Source '"+target+"' does not exist.");
      await call("frappe.client.set_value",{doctype:"Therapy Plan",name:planName,fieldname:"media",value:target});
    }

    async function submitExactDraft(sessionName,button) {
      sessionName=clean(sessionName);
      if(!sessionName) return;
      if(submittingNames[sessionName]) return;
      submittingNames[sessionName]=true;
      var original=button.textContent;
      button.disabled=true; button.textContent="Submitting "+sessionName+"...";
      try{
        /* STRICT: load only the clicked document and verify exact name. */
        var latest=await getDoc("Therapy Session",sessionName);
        if(!latest||clean(latest.name)!==sessionName) throw new Error("Session mismatch. Nothing was submitted.");
        if(Number(latest.docstatus||0)!==0) throw new Error("Therapy Session "+sessionName+" is not Draft anymore.");

        await repairPlanMedia(latest.therapy_plan);

        /* Re-fetch exact target after Therapy Plan repair to get newest timestamp. */
        latest=await getDoc("Therapy Session",sessionName);
        if(!latest||clean(latest.name)!==sessionName||Number(latest.docstatus||0)!==0) throw new Error("Session changed before submit. Please reopen it.");

        /* EXACTLY ONE submit RPC, for this one exact document only. */
        await call("frappe.client.submit",{doc:latest});

        var confirmed=await getDoc("Therapy Session",sessionName);
        if(!confirmed||clean(confirmed.name)!==sessionName||Number(confirmed.docstatus||0)!==1) throw new Error("Therapy Session "+sessionName+" did not reach Submitted status.");

        detailCache[sessionName]={doc:confirmed,loadedAt:Date.now()};
        renderDetail(confirmed);
        listCache.loadedAt=0;
        await openList(true);
        showSuccess(sessionName,confirmed);
      }catch(err){
        void 0;
        var body=detailOverlay&&detailOverlay.querySelector("[data-v96-detail-body]");
        if(body) body.insertAdjacentHTML("afterbegin",'<div style="margin-bottom:12px;padding:11px 14px;border-radius:10px;background:#fef2f2;color:#b42318;font-size:12px;font-weight:800">'+esc(err&&err.message?err.message:"Therapy Session could not be submitted.")+'</div>');
      }finally{
        delete submittingNames[sessionName];
        button.disabled=false; button.textContent=original;
      }
    }

    function renderList(rows) {
      var body=listOverlay.querySelector('[data-role="session-entries-body"]');
      var status=listOverlay.querySelector('[data-role="session-entries-status"]');
      status.textContent=rows.length+" session entr"+(rows.length===1?"y":"ies");
      if(!rows.length){body.innerHTML='<tr><td colspan="7" class="lo-session-entries-empty">No session entries found for this branch today.</td></tr>';return;}
      body.innerHTML=rows.map(function(r){
        var st=Number(r.docstatus||0)===1?"Submitted":"Draft";
        return '<tr><td><strong>'+esc(r.name)+'</strong></td><td>'+esc(r.patient_name||r.patient||"-")+'</td><td>'+esc(r.therapy_type||"-")+'</td><td>'+esc(time12(r.start_time||r.creation))+'</td><td>'+esc(r.custom_practitioner_name||r.practitioner||"-")+'</td><td><span class="lo-session-entry-status '+(st==="Submitted"?"is-submitted":"is-draft")+'">'+esc(st)+'</span></td><td><button type="button" class="lo-session-entry-open" data-v96-open-session="'+esc(r.name)+'">'+(st==="Draft"?"View / Submit":"View")+'</button></td></tr>';
      }).join("");
    }

    async function openList(force) {
      ensureStyles(); ensureListOverlay();
      listOverlay.classList.add("is-open"); document.body.classList.add("lo-session-entries-open");
      var body=listOverlay.querySelector('[data-role="session-entries-body"]');
      var status=listOverlay.querySelector('[data-role="session-entries-status"]');
      var branchText=listOverlay.querySelector('[data-role="session-entries-branch"]');
      try{
        var branch=typeof window.lifeOpsGetLoggedEmployeeBranch==="function"?await window.lifeOpsGetLoggedEmployeeBranch():"";
        branchText.textContent=branch?"Branch: "+branch:"Your permitted branch sessions";
        var key=todayISO()+"||"+branch;
        if(!force&&listCache.key===key&&Date.now()-listCache.loadedAt<CACHE_MS){renderList(listCache.rows);return;}
        status.textContent="Loading sessions...";
        if(!body.innerHTML.trim()) body.innerHTML='<tr><td colspan="7" class="lo-session-entries-empty">Loading...</td></tr>';
        var t=todayISO();
        var filters=[["Therapy Session","creation",">=",t+" 00:00:00"],["Therapy Session","creation","<=",t+" 23:59:59"],["Therapy Session","docstatus","!=",2]];
        if(branch) filters.push(["Therapy Session","branch","=",branch]);
        var rows;
        try{
          rows=await list({doctype:"Therapy Session",fields:["name","patient","patient_name","therapy_plan","therapy_type","start_time","practitioner","custom_practitioner_name","branch","docstatus","creation"],filters:filters,order_by:"creation desc",limit_start:0,limit_page_length:200});
        }catch(e){
          rows=await list({doctype:"Therapy Session",fields:["name","patient","patient_name","therapy_plan","therapy_type","start_time","practitioner","branch","docstatus","creation"],filters:filters,order_by:"creation desc",limit_start:0,limit_page_length:200});
        }
        rows=(Array.isArray(rows)?rows:[]).filter(function(r){return !(r&&typeof window.lifeOpsIsExcludedBranch==="function"&&window.lifeOpsIsExcludedBranch(r.branch));});
        listCache={key:key,rows:rows,loadedAt:Date.now()}; renderList(rows);
      }catch(err){status.textContent="Session entries could not be loaded.";body.innerHTML='<tr><td colspan="7" class="lo-session-entries-empty">Unable to load session entries.</td></tr>';void 0;}
    }

    dashboard.addEventListener("click",function(e){var b=e.target&&e.target.closest?e.target.closest('[data-action="open-session-entries-popup"]'):null;if(!b||!dashboard.contains(b))return;e.preventDefault();openList(false);});
    document.addEventListener("keydown",function(e){if(e.key!=="Escape")return;if(successOverlay&&successOverlay.classList.contains("is-open")){successOverlay.classList.remove("is-open");return;}if(detailOverlay&&detailOverlay.classList.contains("is-open")){closeDetail();return;}if(listOverlay&&listOverlay.classList.contains("is-open"))closeList();});
    ensureStyles();
  }

  if(document.readyState==="loading") document.addEventListener("DOMContentLoaded",startLifeTodaySessionsV96,{once:true});
  else startLifeTodaySessionsV96();
})();

